-- 9AM Crew: Court6 Cycle 1 (2026-10-19, 9 weeks). Generated by supabase/cycle1.py.
-- Run once. Fails without changing anything if a cycle already covers these weeks.
begin;
insert into public.cycles (start_date, week_count, name, why, brief, goals, weeks, days, created_by) values ('2026-10-19', 9, 'Strength + Aerobic Base', 'Nine weeks, Monday to Friday: test, three Base weeks, two Build weeks, a primer/deload week, a retest week and a flex week. Week 1 tests a 3RM back squat and deadlift, a 5RM strict press and a 1 km run (or 1,000 m row); every lift percentage comes from estimated max (3RM × 1.06, press 5RM × 1.13) with an RPE 8 cap, and every run pace comes from the 1 km time. Monday and Friday are the hard days, Wednesday is steady threshold work, Thursday is easy, the lift always comes before conditioning, and class running rises no more than 10% a week. stations live in Wednesday conditioning, compromised running starts in Week 5, and toes-to-bar is the block skill (baseline Week 2, retest Week 9). Week 8 repeats the Week 1 tests on the same days, and the Week 8 numbers plus the Week 9 Helen, Mini Challenge and strict pull-up baselines become the next block''s starting points.', '', array['Raise 3RM back squat and deadlift and 5RM strict press', 'Faster 1 km run or 1,000 m row', 'First or more unbroken toes-to-bar', 'Learn the stations and running off them']::text[], '[{"kind": "test", "label": "Test", "pct": 0, "sets": 0, "reps": 3}, {"kind": "build", "label": "Base", "pct": 65, "sets": 4, "reps": 8}, {"kind": "build", "label": "Base", "pct": 70, "sets": 5, "reps": 6}, {"kind": "build", "label": "Base", "pct": 75, "sets": 5, "reps": 5}, {"kind": "build", "label": "Build", "pct": 80, "sets": 5, "reps": 3}, {"kind": "build", "label": "Build", "pct": 85, "sets": 3, "reps": 3}, {"kind": "deload", "label": "Primer", "pct": 85, "sets": 1, "reps": 2}, {"kind": "test", "label": "Retest", "pct": 0, "sets": 0, "reps": 3}, {"kind": "build", "label": "Flex", "pct": 65, "sets": 3, "reps": 5}]'::jsonb, '{"1": {"focus": "Squat · intervals · hard", "style": "intervals", "lift": "Back squat", "gentle": "Goblet squat", "skill": null, "notes": "Heavy back squat, then short bike or row intervals. No running on squat day."}, "2": {"focus": "Toes-to-bar · aerobic intervals · moderate", "style": "long", "lift": null, "gentle": null, "skill": null, "notes": "Toes-to-bar skill block, then the week''s main aerobic running. 1 km test and retest live here (Wk 1 and 8)."}, "3": {"focus": "Deadlift · threshold · sustain", "style": "amrap", "lift": "Deadlift", "gentle": "Kettlebell deadlift", "skill": null, "notes": "Deadlift, then threshold work at about 7/10 on stations; compromised running in Weeks 5–6."}, "4": {"focus": "Accessory strength · easy intervals · easy", "style": "easy", "lift": null, "gentle": null, "skill": null, "notes": "Easy day: accessory supersets and core, then easy row/bike intervals with set work and rest."}, "5": {"focus": "Clean + press · short workout · hard", "style": "short", "lift": "Strict press", "gentle": "Dumbbell press", "skill": null, "notes": "Power clean technique, then strict press, then a short hard workout. Cindy Wk 4, Mini Challenge Wk 9."}}'::jsonb, null);
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-19', 'TEST: 3RM Back Squat + Bike Intervals', 'Squat test · bike intervals · hard', 'Find your 3-rep max back squat: it sets every squat weight for this block. Short, fast bike intervals after to open up the lungs.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["General (5 min): 2 rounds: 200 m easy row, 10 air squats, 10 band pull-aparts, 5 inchworms.\nSpecific (6 min): 10 goblet squats with 3 s pause, 10/side banded lateral walks, 10 empty-bar back squats, then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 2 rounds: 200 m easy row, 10 air squats, 10 band pull-aparts, 5 inchworms.\nSpecific (6 min): 10 goblet squats with 3 s pause, 10/side banded lateral walks, 10 empty-bar back squats, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 2 rounds: 200 m easy row, 10 air squats, 10 band pull-aparts, 5 inchworms.\nSpecific (6 min): 10 goblet squats with 3 s pause, 10/side banded lateral walks, 10 empty-bar back squats, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 2 rounds: 200 m easy row, 10 air squats, 10 band pull-aparts, 5 inchworms.\nSpecific (6 min): 10 goblet squats with 3 s pause, 10/side banded lateral walks, 10 empty-bar back squats, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "TEST: 3RM back squat", "minutes": 20, "lift": {"movement": "Back squat", "gentleMovement": "Goblet squat", "mode": "build", "sets": 1, "reps": 3, "pct": [null, null, null, null], "note": "Follow the ladder; no RPE 9–10 grinders. Week 1 3RM × 1.06 = e1RM for every squat % this block."}, "versions": ["TEST: build to a 3RM goblet squat in 18 min (one dumbbell or kettlebell at your chest; sit to a box if you need a depth guide).\nLadder: light × 8, then 3 sets of 3 getting heavier, then 2–4 attempts at 3 reps, stopping at RPE 8 (2 reps left).\nThe last clean set = your 3RM.\nRecord: your 3RM goblet squat load in lb, the level you did, and anything the coach noted.", "TEST: build to a 3RM back squat in 18 min.\nLadder: bar × 8, ~50% × 5, ~65% × 3, ~75% × 3, then 2–4 attempts at 3 reps, adding 5–10 lb each time.\nYour coach calls the set if depth or position breaks. The last clean set = your 3RM.\nStart with the empty bar (or a lighter training bar). First 4 weeks after on-ramp: no max attempt; stop at your first RPE 8 set and record that.\nRecord: your 3RM load in lb, the level you did, and anything the coach noted.", "TEST: build to a 3RM back squat in 18 min.\nLadder: bar × 8, ~50% × 5, ~65% × 3, ~75% × 3, then 2–4 attempts at 3 reps, adding 5–15 lb each time.\nYour coach calls the set if depth or position breaks. The last clean set = your 3RM.\nRecord: your 3RM load in lb, the level you did, and anything the coach noted.", "TEST: build to a 3RM back squat in 18 min.\nLadder: bar × 8, ~50% × 5, ~65% × 3, ~75% × 3, then 2–4 attempts at 3 reps, adding 5–20 lb each time.\nYour coach calls the set if depth or position breaks. The last clean set = your 3RM.\nRecord: your 3RM load in lb, the level you did, and anything the coach noted."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Bike intervals", "minutes": 13, "versions": ["6 rounds: 0:30 hard / 1:30 easy (12:00).\nMachine: air bike or rower, whichever feels easier. Hard = RPE 6, smooth (hard pieces can be 0:20 if you need). Use the same machine for all 6 rounds.\nMasters (40+): RPE 8 at most on the hard pieces. Knee or back pain: air bike only.\nNo machine free: 0:30 hard = fast marching or step-jacks; 1:30 easy = slow walk. Score = reps instead of calories.\nCap 12:00 (fixed) · Aim: hold your calories within 10% from round 1 to round 6 · Feel: gas · Pace: reach", "6 rounds: 0:30 hard / 1:30 easy (12:00).\nMachine: any machine (air bike, rower). Hard = RPE 7, smooth. Use the same machine for all 6 rounds.\nMasters (40+): RPE 8 at most on the hard pieces. Knee or back pain: air bike only.\nNo machine free: 0:30 hard = jumping jacks, fast but smooth; 1:30 easy = walk. Score = reps instead of calories.\nCap 12:00 (fixed) · Aim: hold your calories within 10% from round 1 to round 6 · Feel: gas · Pace: reach", "6 rounds: 0:30 hard / 1:30 easy (12:00).\nMachine: rower. Hard = RPE 8. Use the same machine for all 6 rounds.\nMasters (40+): RPE 8 at most on the hard pieces. Knee or back pain: air bike only.\nNo machine free: 0:30 hard = fast single-unders or high knees; 1:30 easy = walk. Score = reps instead of calories.\nCap 12:00 (fixed) · Aim: hold your calories within 10% from round 1 to round 6 · Feel: gas · Pace: reach", "6 rounds: 0:30 hard / 1:30 easy (12:00).\nMachine: air bike. Hard = RPE 9. Use the same machine for all 6 rounds.\nMasters (40+): RPE 8 at most on the hard pieces. Knee or back pain: air bike only.\nNo machine free: 0:30 hard = max-effort single-unders or high knees; 1:30 easy = walk. Score = reps instead of calories.\nCap 12:00 (fixed) · Aim: hold your calories within 10% from round 1 to round 6 · Feel: gas · Pace: reach"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory superset", "minutes": 5, "versions": ["Superset, 2 rounds, 3–4 reps left: 6/side split squats holding the rig, short range + 15 s/side side plank from the knees.", "Superset, 2 rounds, 3 reps left: 10/side bodyweight split squats (hold the rig if needed) + 30 s/side side plank from the knees.", "Superset, 2 rounds, 3 reps left: 10/side light dumbbell split squats + 30 s/side side plank.", "Superset, 2 rounds, 3 reps left: 10/side light dumbbell split squats + 30 s/side side plank."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + log", "minutes": 7, "versions": ["3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads. Write your 3RM on your scorecard.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads. Write your 3RM on your scorecard.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads. Write your 3RM on your scorecard.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads. Write your 3RM on your scorecard.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
