insert into public.workout_coach_notes (class_date, body) values ('2026-10-19', 'Two coaches on test days if possible. Watch depth and back position; you call the set. Steady, Strong and Full all test the barbell back squat (smaller jumps at Steady); only Gentle tests the goblet squat. Machine-only intervals: Monday has no running on purpose (heavy-leg day), so there is no outside version.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-20', 'TEST: 1 km Run Time Trial + T2B Foundations', '1 km test · toes-to-bar · hard', 'Our one run test: your 1 km time sets your run paces for the block. Toes-to-bar work stays light today.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["General (5 min): 400 m easy jog (or 500 m row), leg swings, 2 × 20 m A-skips.\nSpecific (6 min): 2 × 10 hollow rocks + 10 arch rocks, 10 scap pull-ups, 2 × 100 m build-up strides.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy jog (or 500 m row), leg swings, 2 × 20 m A-skips.\nSpecific (6 min): 2 × 10 hollow rocks + 10 arch rocks, 10 scap pull-ups, 2 × 100 m build-up strides.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy jog (or 500 m row), leg swings, 2 × 20 m A-skips.\nSpecific (6 min): 2 × 10 hollow rocks + 10 arch rocks, 10 scap pull-ups, 2 × 100 m build-up strides.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy jog (or 500 m row), leg swings, 2 × 20 m A-skips.\nSpecific (6 min): 2 × 10 hollow rocks + 10 arch rocks, 10 scap pull-ups, 2 × 100 m build-up strides.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "skill", "label": "Skill", "title": "Toes-to-bar foundations", "minutes": 13, "versions": ["Toes-to-bar level 1, every 2:00 × 4 (light, not a test):\n15 s tuck hollow hold\n15 s arch hold (superman), arms by your sides\n4 lying bent-knee raises\n5 ring rows on a high bar, body nearly upright", "Toes-to-bar level 1, every 2:00 × 4 (light, not a test):\n20 s tuck hollow hold\n20 s arch hold (superman)\n5 lying leg raises\n6 ring rows, body upright", "Toes-to-bar level 1, every 2:00 × 4 (light, not a test):\n20 s hollow hold\n20 s arch hold (superman)\n5 hanging knee raises\n5 ring rows, feet forward", "Toes-to-bar level 1, every 2:00 × 4 (light, not a test):\n20 s hollow hold\n20 s arch hold (superman)\n5 hanging knee raises\n3 strict pull-ups (band if needed), 3 s lowering"]}, {"kind": "conditioning", "label": "Test", "title": "1,000 m row time trial", "minutes": 15, "versions": ["TEST: 1,000 m row time trial.\n1,000 m row, steady and comfortable-hard; a short pause at 500 m is fine (note it).\nRest 8–10 min after: walk and drink water.\nNo machine free: do the test on the next free rower, or as the 1 km run outside if it is safe; a bodyweight swap can''t be compared with Week 8.\nCap 15:00 · Aim: a steady pace you can hold; this is your starting number · Feel: cardio · Pace: reach\nRecord: time, level, and whether you ran or rowed.", "TEST: 1,000 m row time trial.\n1,000 m row, as fast as you can hold for the whole 1,000 m.\nRest 8–10 min after: walk and drink water.\nNo machine free: do the test on the next free rower, or as the 1 km run outside if it is safe; a bodyweight swap can''t be compared with Week 8.\nCap 15:00 · Aim: even 500 m splits; this is your starting number · Feel: cardio · Pace: reach\nRecord: time, level, and whether you ran or rowed.", "TEST: 1,000 m row time trial.\n1,000 m row, even pace.\nRest 8–10 min after: walk and drink water.\nNo machine free: do the test on the next free rower, or as the 1 km run outside if it is safe; a bodyweight swap can''t be compared with Week 8.\nCap 15:00 · Aim: even 500 m splits; this is your starting number · Feel: cardio · Pace: reach\nRecord: time, level, and whether you ran or rowed.", "TEST: 1,000 m row time trial.\n1,000 m row, hard but even: the same split every 250 m.\nRest 8–10 min after: walk and drink water.\nNo machine free: do the test on the next free rower, or as the 1 km run outside if it is safe; a bodyweight swap can''t be compared with Week 8.\nCap 15:00 · Aim: even 500 m splits; this is your starting number · Feel: cardio · Pace: reach\nRecord: time, level, and whether you ran or rowed."], "outdoor": {"title": "1 km run time trial", "versions": ["TEST: 1 km run time trial.\n1 km walk/jog: jog 1:00, walk 1:00, repeat (or brisk walk the whole way). Keep the same plan in Week 8.\nRest 8–10 min after: walk and drink water.\nCap 15:00 · Aim: 7:30–11:00 (walking is fine) · Feel: cardio · Pace: reach\nRecord: time, level, and whether you ran or rowed.", "TEST: 1 km run time trial.\n1 km run/walk, as fast as you can hold for the whole 1 km.\nRest 8–10 min after: walk and drink water.\nCap 15:00 · Aim: 5:45–8:00 · Feel: cardio · Pace: reach\nRecord: time, level, and whether you ran or rowed.", "TEST: 1 km run time trial.\n1 km run, even pace.\nRest 8–10 min after: walk and drink water.\nCap 15:00 · Aim: 4:45–5:45 · Feel: cardio · Pace: reach\nRecord: time, level, and whether you ran or rowed.", "TEST: 1 km run time trial.\n1 km run, hard but even: the same pace every 200 m.\nRest 8–10 min after: walk and drink water.\nCap 15:00 · Aim: 3:45–4:45 · Feel: cardio · Pace: reach\nRecord: time, level, and whether you ran or rowed."]}}, {"kind": "conditioning", "label": "Conditioning", "title": "Easy jump rope flush", "minutes": 13, "versions": ["12:00 easy, RPE 4, 3 rounds, not for time:\n1:00 step-jacks or marching on the spot\n8 incline push-ups (hands on a box or the wall)\n8 air squats to a box\nYou should be able to talk the whole time.\nCap 12:00 · Aim: smooth and easy · Feel: cardio (easy) · Pace: sustain", "12:00 easy, RPE 5, 3 rounds, not for time:\n1:00 easy jumping jacks or single-unders\n8 incline push-ups (hands on a box)\n12 air squats\nYou should be able to talk the whole time.\nCap 12:00 · Aim: smooth and easy · Feel: cardio (easy) · Pace: sustain", "12:00 easy, RPE 5, 3 rounds, not for time:\n1:30 easy single-unders (break whenever you like)\n10 push-ups (knees if needed)\n15 air squats\nYou should be able to talk the whole time.\nCap 12:00 · Aim: smooth and easy · Feel: cardio (easy) · Pace: sustain", "12:00 easy, RPE 5, 3 rounds, not for time:\n1:30 easy single-unders (break whenever you like)\n10 push-ups\n15 air squats\nYou should be able to talk the whole time.\nCap 12:00 · Aim: smooth and easy · Feel: cardio (easy) · Pace: sustain"], "outdoor": {"title": "Easy run flush", "versions": ["12:00 easy, RPE 4, 3 rounds, not for time:\n300 m walk/jog\n8 incline push-ups (hands on a box or the wall)\n8 air squats to a box\nYou should be able to talk the whole time.\nCap 12:00 · Aim: smooth and easy · Feel: cardio (easy) · Pace: sustain", "12:00 easy, RPE 5, 3 rounds, not for time:\n400 m easy run/walk\n8 incline push-ups (hands on a box)\n12 air squats\nYou should be able to talk the whole time.\nCap 12:00 · Aim: smooth and easy · Feel: cardio (easy) · Pace: sustain", "12:00 easy, RPE 5, 3 rounds, not for time:\n400 m easy run\n10 push-ups (knees if needed)\n15 air squats\nYou should be able to talk the whole time.\nCap 12:00 · Aim: smooth and easy · Feel: cardio (easy) · Pace: sustain", "12:00 easy, RPE 5, 3 rounds, not for time:\n400 m easy run\n10 push-ups\n15 air squats\nYou should be able to talk the whole time.\nCap 12:00 · Aim: smooth and easy · Feel: cardio (easy) · Pace: sustain"]}}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min."]}]'::jsonb, 'published', null)
