insert into public.workout_coach_notes (class_date, body) values ('2026-10-20', 'Start the 1 km in waves of 4–6 and read times out as they finish; if rowers run out inside, the next wave rows when a machine frees up (don''t swap the test). Members choose run or row once and repeat the same option in Week 8. The easy flush after the test needs no machines inside (jump ropes, floor space), so finished waves start it while the next wave rows. Write each member''s time on their scorecard; it sets all run paces (easy = +1:30–2:30/km, threshold = +0:40–0:50/km).')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-21', 'TEST: 3RM Deadlift + Easy Bike EMOM', 'Deadlift test · easy bike EMOM', 'Find your 3-rep max deadlift: it sets every deadlift weight this block. Then an easy air bike EMOM to move and breathe: no hinging, nothing like yesterday (no run test today).', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["General (5 min): 2 rounds: 250 m easy row, 10 PVC good mornings, 10 bird dogs, 5 push-ups.\nSpecific (6 min): 10 KB deadlifts, 8 empty-bar RDLs, then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 2 rounds: 250 m easy row, 10 PVC good mornings, 10 bird dogs, 5 push-ups.\nSpecific (6 min): 10 KB deadlifts, 8 empty-bar RDLs, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 2 rounds: 250 m easy row, 10 PVC good mornings, 10 bird dogs, 5 push-ups.\nSpecific (6 min): 10 KB deadlifts, 8 empty-bar RDLs, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 2 rounds: 250 m easy row, 10 PVC good mornings, 10 bird dogs, 5 push-ups.\nSpecific (6 min): 10 KB deadlifts, 8 empty-bar RDLs, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "TEST: 3RM deadlift", "minutes": 18, "lift": {"movement": "Deadlift", "gentleMovement": "Kettlebell deadlift", "mode": "build", "sets": 1, "reps": 3, "pct": [null, null, null, null], "note": "Follow the ladder; reset every rep. Week 1 3RM × 1.06 = e1RM for every deadlift % this block."}, "versions": ["TEST: build to a 3RM kettlebell deadlift in 16 min (bell between your feet, on a low step if the floor is too far).\nLadder: light × 5, then 3 sets of 3 getting heavier, then 2–4 attempts at 3 reps, stopping at RPE 8. Reset each rep.\nThe last clean set = your 3RM.\nRecord: your 3RM kettlebell deadlift load in lb, the level you did, and anything the coach noted.", "TEST: build to a 3RM deadlift in 16 min.\nLadder: 40% × 5, 55% × 3, 65% × 3, 75% × 3, then 2–4 attempts at 3 reps, adding 5–15 lb each time.\nNo touch-and-go: reset each rep. Your coach stops the set if your back rounds. The last clean set = your 3RM.\nStart light (bar plus small plates on blocks if needed). First 4 weeks after on-ramp: no max attempt; stop at your first RPE 8 set and record that.\nRecord: your 3RM load in lb, the level you did, and anything the coach noted.", "TEST: build to a 3RM deadlift in 16 min.\nLadder: 40% × 5, 55% × 3, 65% × 3, 75% × 3, then 2–4 attempts at 3 reps, adding 10–20 lb each time.\nNo touch-and-go: reset each rep. Your coach stops the set if your back rounds. The last clean set = your 3RM.\nRecord: your 3RM load in lb, the level you did, and anything the coach noted.", "TEST: build to a 3RM deadlift in 16 min.\nLadder: 40% × 5, 55% × 3, 65% × 3, 75% × 3, then 2–4 attempts at 3 reps, adding 10–30 lb each time.\nNo touch-and-go: reset each rep. Your coach stops the set if your back rounds. The last clean set = your 3RM.\nRecord: your 3RM load in lb, the level you did, and anything the coach noted."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Easy bike EMOM", "minutes": 14, "versions": ["EMOM 12 (3 rounds), not for score, RPE 4–5:\nMinute 1: 0:30 very easy air bike\nMinute 2: 6/side reverse lunges holding the rig (or step-backs)\nMinute 3: 0:30 very easy air bike\nMinute 4: 10 m hands-and-knees crawl + 8 two-leg glute bridges\nSore low back after the test: keep the bike very easy and skip the bear crawl (glute bridges only).\nNo machine free: each 0:30 air bike minute → 0:30 easy step-jacks or marching on the spot.\nCap 12:00 (fixed) · Aim: smooth and easy; breathing stays calm · Feel: cardio (easy) · Pace: sustain", "EMOM 12 (3 rounds), not for score, RPE 5–6:\nMinute 1: 0:40 easy air bike\nMinute 2: 8/side bodyweight reverse lunges\nMinute 3: 0:40 easy air bike\nMinute 4: 15 m bear crawl + 10 glute bridges\nSore low back after the test: keep the bike very easy and skip the bear crawl (glute bridges only).\nNo machine free: each 0:40 air bike minute → 0:40 easy jumping jacks.\nCap 12:00 (fixed) · Aim: smooth and easy; breathing stays calm · Feel: cardio (easy) · Pace: sustain", "EMOM 12 (3 rounds), not for score, RPE 5–6:\nMinute 1: 0:40 easy air bike\nMinute 2: 8/side bodyweight reverse lunges\nMinute 3: 0:40 easy air bike\nMinute 4: 20 m bear crawl + 10 glute bridges\nSore low back after the test: keep the bike very easy and skip the bear crawl (glute bridges only).\nNo machine free: each 0:40 air bike minute → 0:40 easy single-unders.\nCap 12:00 (fixed) · Aim: smooth and easy; breathing stays calm · Feel: cardio (easy) · Pace: sustain", "EMOM 12 (3 rounds), not for score, RPE 5–6:\nMinute 1: 0:40 easy air bike\nMinute 2: 10/side bodyweight reverse lunges\nMinute 3: 0:40 easy air bike\nMinute 4: 20 m bear crawl + 12 glute bridges\nSore low back after the test: keep the bike very easy and skip the bear crawl (glute bridges only).\nNo machine free: each 0:40 air bike minute → 0:40 easy single-unders.\nCap 12:00 (fixed) · Aim: smooth and easy; breathing stays calm · Feel: cardio (easy) · Pace: sustain"]}, {"kind": "skill", "label": "Accessory", "title": "Core", "minutes": 6, "versions": ["Core, 2 rounds: 6/side dead bugs, arms only + 15 s/side side plank from the knees.", "Core, 2 rounds: 10/side dead bugs + 20 s/side side plank from the knees.", "Core, 2 rounds: 10/side dead bugs + 20 s/side side plank.", "Core, 2 rounds: 10/side dead bugs + 20 s/side side plank."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + log", "minutes": 8, "versions": ["3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s. Write your 3RM on your scorecard.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s. Write your 3RM on your scorecard.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s. Write your 3RM on your scorecard.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s. Write your 3RM on your scorecard.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
