insert into public.workout_coach_notes (class_date, body) values ('2026-10-21', 'Coach stops any set where the back rounds. Steady, Strong and Full all test the barbell deadlift; only Gentle tests the kettlebell deadlift. The easy EMOM is air bike only in Week 1, so there is no outside version (no extra running this week); members without a bike use the ''No machine free'' swap. Stagger starts by 1:00 if bikes are short: half the class starts on Minute 2.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-22', 'Accessory Strength + Easy Row/Bike Intervals', 'Accessory strength · easy intervals · easy', 'The easy day: strength work for joints and posture, then easy intervals with set work and rest. Your coach also checks how you move, to set up your scaling.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 7, "versions": ["General (4 min): 2 min easy bike or row, then 10 90/90 hip switches and 5/side world''s greatest stretch.\nSpecific (3 min): 5/side light single-leg Romanian deadlifts, 10 band pull-aparts.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (4 min): 2 min easy bike or row, then 10 90/90 hip switches and 5/side world''s greatest stretch.\nSpecific (3 min): 5/side light single-leg Romanian deadlifts, 10 band pull-aparts.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (4 min): 2 min easy bike or row, then 10 90/90 hip switches and 5/side world''s greatest stretch.\nSpecific (3 min): 5/side light single-leg Romanian deadlifts, 10 band pull-aparts.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (4 min): 2 min easy bike or row, then 10 90/90 hip switches and 5/side world''s greatest stretch.\nSpecific (3 min): 5/side light single-leg Romanian deadlifts, 10 band pull-aparts.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "skill", "label": "Accessory", "title": "Accessory strength + core", "minutes": 21, "versions": ["2 rounds, 4 reps left on every set:\nA1) 8 chest-supported dumbbell rows on an incline bench, light\nA2) 8 two-leg Romanian deadlifts with light dumbbells, short range\nA3) 6/side dead bugs, arms only", "2 rounds, 3 reps left on every set:\nA1) 10 light dumbbell bent-over rows\nA2) 8/side single-leg Romanian deadlift holding the rig, light dumbbell or none\nA3) 10/side dead bugs", "2 rounds, 3 reps left on every set:\nA1) 10 dumbbell bent-over rows\nA2) 8/side single-leg Romanian deadlift with a light dumbbell\nA3) 10/side dead bugs", "2 rounds, 3 reps left on every set:\nA1) 10 dumbbell bent-over rows\nA2) 8/side single-leg Romanian deadlift with a light dumbbell\nA3) 10/side dead bugs"]}, {"kind": "conditioning", "label": "Easy intervals", "title": "Easy row/bike intervals", "minutes": 21, "versions": ["4 × 4:00 easy / 1:00 rest (19:00), alternating row and air bike each round.\nEffort: RPE 3–4 (very easy). Air bike or row; each round can be 1:00–2:00 shorter, and slow pedalling is fine.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: marching on the spot, step-ups to a low step, wall push-ups; repeat until the work time ends.\nCap 19:00 (fixed) · Aim: same easy pace every round; you could keep going · Feel: cardio (easy) · Pace: sustain", "4 × 4:00 easy / 1:00 rest (19:00), alternating row and air bike each round.\nEffort: RPE 4 (easy, chatty). Air bike or row. Rounds can be 1:00 shorter.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: step-ups to a low box, jumping jacks, air squats; repeat until the work time ends.\nCap 19:00 (fixed) · Aim: same pace every round: row split 0:15–0:25 per 500 m slower than your 1 km test split; bike, same calories each round (±1) · Feel: cardio (easy) · Pace: sustain", "4 × 4:00 easy / 1:00 rest (19:00), alternating row and air bike each round.\nEffort: RPE 4–5. Row or air bike.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: step-ups, jumping jacks, air squats, easy single-unders; repeat until the work time ends.\nCap 19:00 (fixed) · Aim: same pace every round: row split 0:15–0:25 per 500 m slower than your 1 km test split; bike, same calories each round (±1) · Feel: cardio (easy) · Pace: sustain", "4 × 4:00 easy / 1:00 rest (19:00), alternating row and air bike each round.\nEffort: RPE 5. Row or air bike.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: step-ups, jumping jacks, air squats, easy single-unders; repeat until the work time ends.\nCap 19:00 (fixed) · Aim: same pace every round: row split 0:15–0:25 per 500 m slower than your 1 km test split; bike, same calories each round (±1) · Feel: cardio (easy) · Pace: sustain"]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + mobility", "minutes": 8, "versions": ["3 min easy bike; hip flexor and hamstring stretch 1 min/side; 1 min deep-squat hold.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; hip flexor and hamstring stretch 1 min/side; 1 min deep-squat hold.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; hip flexor and hamstring stretch 1 min/side; 1 min deep-squat hold.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; hip flexor and hamstring stretch 1 min/side; 1 min deep-squat hold.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
