insert into public.workout_coach_notes (class_date, body) values ('2026-10-23', 'Demo the wall ball, farmers carry, sandbag lunge and burpee broad jump standards before the AMRAP (4 min). Start members on different stations if kit is short. Steady, Strong and Full all test the barbell strict press; only Gentle tests the seated dumbbell press. Benchmark: Full is the Rx standard; members record their level. No outside version: there is no running in this piece.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-26', 'Back Squat 4×8 + Row/Swing EMOM', 'Squat · intervals · hard', 'Build squat volume at moderate weights, then short, repeatable intervals.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["General (5 min): 2 rounds: 200 m easy row, 10 air squats, 10 band pull-aparts, 5 inchworms.\nSpecific (6 min): 10 goblet squats with 3 s pause, 10/side banded lateral walks, 10 empty-bar back squats, then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 2 rounds: 200 m easy row, 10 air squats, 10 band pull-aparts, 5 inchworms.\nSpecific (6 min): 10 goblet squats with 3 s pause, 10/side banded lateral walks, 10 empty-bar back squats, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 2 rounds: 200 m easy row, 10 air squats, 10 band pull-aparts, 5 inchworms.\nSpecific (6 min): 10 goblet squats with 3 s pause, 10/side banded lateral walks, 10 empty-bar back squats, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 2 rounds: 200 m easy row, 10 air squats, 10 band pull-aparts, 5 inchworms.\nSpecific (6 min): 10 goblet squats with 3 s pause, 10/side banded lateral walks, 10 empty-bar back squats, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "Back squat 4×8 @ 65%", "minutes": 20, "lift": {"movement": "Back squat", "gentleMovement": "Goblet squat", "mode": "percent", "sets": 4, "reps": 8, "pct": [null, 65, 65, 65], "note": "Ramp: empty bar × 10, 40% × 5, 50% × 3, 60% × 2, then working sets; rest 2:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Goblet box squat (light kettlebell or dumbbell at your chest, sit to a box at knee height, stand up tall): 4 × 8 at RPE 6–7 (3–4 reps left). Rest 2:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Back squat: 4 × 8 @ 65% of your estimated max (e1RM). Rest 2:00.\nLoad = e1RM × 0.65, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Back squat: 4 × 8 @ 65% of your estimated max (e1RM). Rest 2:00.\nLoad = e1RM × 0.65, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Back squat: 4 × 8 @ 65% of your estimated max (e1RM). Rest 2:00.\nLoad = e1RM × 0.65, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Row/Swing EMOM", "minutes": 15, "versions": ["EMOM 12 (4 rounds):\nMinute 1: 5/6 cal row\nMinute 2: 8 Russian KB swings to chest height 13/18 lb\nMinute 3: 4 incline step-back burpees (hands on a box)\nLow back: KB deadlifts instead of swings.\nNo machine free: 5/6 cal row → 0:20 step-jacks or marching on the spot.\nCap 12:00 (fixed) · Aim: every minute done in 35–45 s · Feel: cardio · Pace: sustain", "EMOM 12 (4 rounds):\nMinute 1: 6/8 cal row\nMinute 2: 10 Russian KB swings 18/26 lb\nMinute 3: 5 step-back burpees\nLow back: KB deadlifts instead of swings.\nNo machine free: 6/8 cal row → 30 jumping jacks.\nCap 12:00 (fixed) · Aim: every minute done in 35–45 s · Feel: cardio · Pace: sustain", "EMOM 12 (4 rounds):\nMinute 1: 8/10 cal row\nMinute 2: 12 KB swings 26/35 lb\nMinute 3: 6 burpees\nLow back: KB deadlifts instead of swings.\nNo machine free: 8/10 cal row → 70 single-unders.\nCap 12:00 (fixed) · Aim: every minute done in 35–45 s · Feel: cardio · Pace: sustain", "EMOM 12 (4 rounds):\nMinute 1: 9/12 cal row\nMinute 2: 12 KB swings 35/53 lb\nMinute 3: 8 burpees\nLow back: KB deadlifts instead of swings.\nNo machine free: 9/12 cal row → 80 single-unders.\nCap 12:00 (fixed) · Aim: every minute done in 35–45 s · Feel: cardio · Pace: sustain"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory superset", "minutes": 5, "versions": ["Superset, 3 rounds, 3–4 reps left: 6/side reverse lunges holding the rig, short step + 20 s tuck hollow hold.", "Superset, 3 rounds, 3 reps left: 10/side bodyweight reverse lunges + 30 s tuck hollow hold.", "Superset, 3 rounds, 3 reps left: 10/side dumbbell reverse lunges + 30 s hollow hold.", "Superset, 3 rounds, 3 reps left: 10/side dumbbell reverse lunges + 30 s hollow hold."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
