insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-27', 'T2B Baseline + Aerobic Rounds', 'Toes-to-bar baseline · aerobic rounds · moderate', 'A light baseline for this block''s skill, toes-to-bar, then easy aerobic volume.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["General (5 min): 400 m easy jog (or 500 m row), leg swings, 2 × 20 m A-skips.\nSpecific (6 min): 2 × 10 hollow rocks + 10 arch rocks, 10 scap pull-ups, 2 × 100 m build-up strides.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy jog (or 500 m row), leg swings, 2 × 20 m A-skips.\nSpecific (6 min): 2 × 10 hollow rocks + 10 arch rocks, 10 scap pull-ups, 2 × 100 m build-up strides.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy jog (or 500 m row), leg swings, 2 × 20 m A-skips.\nSpecific (6 min): 2 × 10 hollow rocks + 10 arch rocks, 10 scap pull-ups, 2 × 100 m build-up strides.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy jog (or 500 m row), leg swings, 2 × 20 m A-skips.\nSpecific (6 min): 2 × 10 hollow rocks + 10 arch rocks, 10 scap pull-ups, 2 × 100 m build-up strides.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "skill", "label": "Skill", "title": "Toes-to-bar baseline", "minutes": 13, "versions": ["BASELINE (one fresh attempt, then record it): max unbroken lying bent-knee raises (on your back, lower back pressed down).\nThen toes-to-bar level 1, every 2:00 × 4:\n15 s tuck hollow hold\n4 lying bent-knee raises\n5 ring rows on a high bar, body nearly upright, 3 s lowering\nRecord: your max lying knee raises and your level.", "BASELINE (one fresh attempt, then record it): max unbroken hanging knee raises to hip height.\nThen toes-to-bar level 1, every 2:00 × 4:\n20 s tuck hollow hold\n3 hanging knee raises\n3–5 ring rows, feet forward, 3 s lowering\nRecord: your max knee raises and your level.", "BASELINE (one fresh attempt, then record it): max unbroken hanging knee raises to hip height.\nThen toes-to-bar level 1, every 2:00 × 4:\n20 s hollow hold\n3 hanging knee raises\n3–5 band-assisted strict pull-ups, 3 s lowering\nRecord: your max knee raises and your level.", "BASELINE (one fresh attempt, then record it): max unbroken toes-to-bar.\nThen toes-to-bar level 1, every 2:00 × 4:\n20 s hollow hold\n3 hanging knee raises\n3–5 strict pull-ups, 3 s lowering\nRecord: your max toes-to-bar and your level."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Bike/Row Aerobic Rounds", "minutes": 28, "versions": ["Not for time, 28:00 at RPE 5–6. 4 rounds:\n12/15 cal air bike\n200 m row\n8 wall balls 4/6 lb to a low target\n30 s step-jacks\nNo machine free: 200 m row → 0:50 step-jacks or marching on the spot; 12/15 cal air bike → 0:55 step-jacks or marching on the spot.\nCap 28:00 · Aim: 4 rounds at a pace you could hold for 40 min · Feel: cardio · Pace: sustain", "Not for time, 28:00 at RPE 5–6. 4 rounds:\n16/20 cal air bike\n300 m row\n10 wall balls 6/10 lb\n30 s single-unders\nNo machine free: 300 m row → 75 jumping jacks; 16/20 cal air bike → 70 jumping jacks.\nCap 28:00 · Aim: 4 rounds at a pace you could hold for 40 min · Feel: cardio · Pace: sustain", "Not for time, 28:00 at RPE 5–6. 4 rounds:\n20/25 cal air bike\n400 m row\n15 wall balls 6/10 lb\n30 s double-under attempts\nNo machine free: 400 m row → 200 single-unders; 20/25 cal air bike → 180 single-unders.\nCap 28:00 · Aim: 4 rounds at a pace you could hold for 40 min · Feel: cardio · Pace: sustain", "Not for time, 28:00 at RPE 5–6. 4 rounds:\n24/30 cal air bike\n400 m row\n15 wall balls 10/14 lb\n30 s double-unders\nNo machine free: 400 m row → 200 single-unders; 24/30 cal air bike → 220 single-unders.\nCap 28:00 · Aim: 4 rounds at a pace you could hold for 40 min · Feel: cardio · Pace: sustain"], "outdoor": {"title": "Run/Row Aerobic Rounds", "versions": ["Not for time, 28:00 at RPE 5–6. 4 rounds:\n300 m walk/jog\n200 m row\n8 wall balls 4/6 lb to a low target\n30 s step-jacks\nNo machine free: 200 m row → 150 m walk/jog.\nCap 28:00 · Aim: 4 rounds at a pace you could hold for 40 min · Feel: cardio · Pace: sustain", "Not for time, 28:00 at RPE 5–6. 4 rounds:\n400 m run/walk\n300 m row\n10 wall balls 6/10 lb\n30 s single-unders\nNo machine free: 300 m row → 250 m run.\nCap 28:00 · Aim: 4 rounds at a pace you could hold for 40 min · Feel: cardio · Pace: sustain", "Not for time, 28:00 at RPE 5–6. 4 rounds:\n500 m run\n400 m row\n15 wall balls 6/10 lb\n30 s double-under attempts\nNo machine free: 400 m row → 300 m run.\nCap 28:00 · Aim: 4 rounds at a pace you could hold for 40 min · Feel: cardio · Pace: sustain", "Not for time, 28:00 at RPE 5–6. 4 rounds:\n600 m run\n400 m row\n15 wall balls 10/14 lb\n30 s double-unders\nNo machine free: 400 m row → 300 m run.\nCap 28:00 · Aim: 4 rounds at a pace you could hold for 40 min · Feel: cardio · Pace: sustain"]}}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min."]}]'::jsonb, 'published', null)
