insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-28', 'Deadlift 3×8 + 20-min Station Threshold AMRAP', 'Deadlift · station threshold · sustain', 'Deadlift volume, then our first threshold piece on four stations: the same pace from the first round to the last.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["General (5 min): 2 rounds: 250 m easy row, 10 PVC good mornings, 10 bird dogs, 5 push-ups.\nSpecific (6 min): 10 KB deadlifts, 8 empty-bar RDLs, then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 2 rounds: 250 m easy row, 10 PVC good mornings, 10 bird dogs, 5 push-ups.\nSpecific (6 min): 10 KB deadlifts, 8 empty-bar RDLs, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 2 rounds: 250 m easy row, 10 PVC good mornings, 10 bird dogs, 5 push-ups.\nSpecific (6 min): 10 KB deadlifts, 8 empty-bar RDLs, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 2 rounds: 250 m easy row, 10 PVC good mornings, 10 bird dogs, 5 push-ups.\nSpecific (6 min): 10 KB deadlifts, 8 empty-bar RDLs, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "Deadlift 3×8 @ 65%", "minutes": 16, "lift": {"movement": "Deadlift", "gentleMovement": "Kettlebell deadlift", "mode": "percent", "sets": 3, "reps": 8, "pct": [null, 65, 65, 65], "note": "Ramp: 40% × 5, 50% × 3, 60% × 2; reset every rep, no bouncing; rest 2:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Kettlebell deadlift (one light kettlebell between your feet; stand it on a low step if the floor is too far): 3 × 8 at RPE 6–7 (3–4 reps left). Rest 2:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Deadlift: 3 × 8 @ 65% of your estimated max (e1RM). Rest 2:00.\nLoad = e1RM × 0.65, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Deadlift: 3 × 8 @ 65% of your estimated max (e1RM). Rest 2:00.\nLoad = e1RM × 0.65, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Deadlift: 3 × 8 @ 65% of your estimated max (e1RM). Rest 2:00.\nLoad = e1RM × 0.65, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Station Threshold AMRAP", "minutes": 22, "versions": ["AMRAP 20:00 at threshold effort (about 7/10: breathing hard but controlled):\n6/8 cal row\n8 wall balls 4/6 lb to a low target\n20 m farmers carry 2 × 13/18 lb\n8 step-ups to a low step (total)\nKnees: step-ups instead of lunges. Low back: lighter farmers carry.\nNo machine free: 6/8 cal row → 0:30 step-jacks or marching on the spot.\nCap 20:00 · Aim: steady rounds; a short pause between stations is fine · Feel: cardio · Pace: sustain", "AMRAP 20:00 at threshold effort (about 7/10: breathing hard but controlled):\n8/10 cal row\n10 wall balls 6/10 lb\n20 m farmers carry 2 × 18/26 lb\n10 bodyweight lunges (total)\nKnees: step-ups instead of lunges. Low back: lighter farmers carry.\nNo machine free: 8/10 cal row → 35 jumping jacks.\nCap 20:00 · Aim: steady rounds, every round within ±15 s of round 1 · Feel: cardio · Pace: sustain", "AMRAP 20:00 at threshold effort (about 7/10: breathing hard but controlled):\n10/12 cal row\n10 wall balls 6/10 lb\n20 m farmers carry 2 × 26/35 lb\n10 sandbag lunges 22/33 lb (total)\nKnees: step-ups instead of lunges. Low back: lighter farmers carry.\nNo machine free: 10/12 cal row → 90 single-unders.\nCap 20:00 · Aim: 6–8 rounds; every round within ±15 s of round 1 · Feel: cardio · Pace: sustain", "AMRAP 20:00 at threshold effort (about 7/10: breathing hard but controlled):\n10/12 cal row\n10 wall balls 10/14 lb\n20 m farmers carry 2 × 35/53 lb\n10 sandbag lunges 22/44 lb (total)\nKnees: step-ups instead of lunges. Low back: lighter farmers carry.\nNo machine free: 10/12 cal row → 90 single-unders.\nCap 20:00 · Aim: 6–8 rounds; every round within ±15 s of round 1 · Feel: cardio · Pace: sustain"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory superset", "minutes": 4, "versions": ["Superset, 3 rounds, 3–4 reps left: 8 chest-supported dumbbell rows on an incline bench + 20 s farmers hold 2 × 13/18 lb.", "Superset, 3 rounds, 2–3 reps left: 10 light dumbbell bent-over rows + 30 s farmers hold 2 × 18/26 lb.", "Superset, 3 rounds, 2–3 reps left: 10 dumbbell bent-over rows + 30 s heavy farmers hold 2 × 35/53 lb.", "Superset, 3 rounds, 2–3 reps left: 10 dumbbell bent-over rows + 30 s heavy farmers hold 2 × 35/53 lb."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 4, "versions": ["3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
