insert into public.workout_coach_notes (class_date, body) values ('2026-10-29', 'If there aren''t enough rowers and bikes, run the class in two waves: wave 1 does the intervals while wave 2 does the accessory strength, then swap at about minute 31; or send the overflow to the ''No machine free'' bodyweight rounds. The intervals have no outside version on purpose: Thursday is machine-only so weekly running volume stays as planned.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-30', 'Clean Technique + Press 4×8 + 15-12-9 Sprint', 'Clean + press · short workout · hard', 'Learn clean positions with a light bar, press volume, then a short, punchy finish.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["General (5 min): 3 min easy bike, 10 PVC pass-throughs, 10 PVC overhead squats.\nSpecific (7 min): barbell drills × 5 each: down-and-up, elbows high & fast, muscle clean, hang power clean; 10 empty-bar strict presses.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy bike, 10 PVC pass-throughs, 10 PVC overhead squats.\nSpecific (7 min): barbell drills × 5 each: down-and-up, elbows high & fast, muscle clean, hang power clean; 10 empty-bar strict presses.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy bike, 10 PVC pass-throughs, 10 PVC overhead squats.\nSpecific (7 min): barbell drills × 5 each: down-and-up, elbows high & fast, muscle clean, hang power clean; 10 empty-bar strict presses.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy bike, 10 PVC pass-throughs, 10 PVC overhead squats.\nSpecific (7 min): barbell drills × 5 each: down-and-up, elbows high & fast, muscle clean, hang power clean; 10 empty-bar strict presses.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "Power clean technique", "minutes": 8, "versions": ["Dumbbell clean technique, same clock (EMOM 8): one light dumbbell or kettlebell, hang clean it to your shoulder, then 1–2 goblet squats in place of each front squat.\nHalf the reps is fine. Stay at RPE 5–6; smooth reps only.", "Power clean technique: EMOM 8: 1 hang power clean + 2 front squats (empty bar → RPE 6).\nStay light: empty bar or light plates, and catch from the hang (above the knee) if the floor start feels rushed. Every rep fast and crisp; RPE 6 is plenty.", "Power clean technique: EMOM 8: 1 hang power clean + 2 front squats (empty bar → RPE 6).\nBuild by feel only: no percentages today. Every rep fast and crisp; stop adding weight when it slows down.", "Power clean technique: EMOM 8: 1 hang power clean + 2 front squats (empty bar → RPE 6).\nBuild by feel only: no percentages today. Every rep fast and crisp; stop adding weight when it slows down."]}, {"kind": "strength", "label": "Strength", "title": "Strict press 4×8 @ 65%", "minutes": 10, "lift": {"movement": "Strict press", "gentleMovement": "Dumbbell press", "mode": "percent", "sets": 4, "reps": 8, "pct": [null, 65, 65, 65], "note": "Build to the working weight in 2–3 lighter sets; rest 1:30–2:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Seated dumbbell press (light dumbbells, back against a bench): 4 × 8 at RPE 6–7 (3–4 reps left). Rest 1:30–2:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nBetween sets: 10 light dumbbell rear-delt flys.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Strict press: 4 × 8 @ 65% of your estimated max (e1RM). Rest 1:30–2:00.\nLoad = e1RM × 0.65, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Strict press: 4 × 8 @ 65% of your estimated max (e1RM). Rest 1:30–2:00.\nLoad = e1RM × 0.65, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Strict press: 4 × 8 @ 65% of your estimated max (e1RM). Rest 1:30–2:00.\nLoad = e1RM × 0.65, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "conditioning", "label": "Conditioning", "title": "15-12-9 Row/Wall Ball/Burpee", "minutes": 19, "versions": ["For time, 9-6-3:\ncal row\nwall balls 4/6 lb to a low target\nincline step-back burpees (hands on a box)\nKnees: wall balls to a lower target.\nNo machine free: replace each row calorie with 4 s of step-jacks (9 cal = about 0:36).\nCap 12:00 · Aim: finish under the cap; rest when you need to · Feel: gas · Pace: reach", "For time, 12-9-6:\ncal row\nwall balls 6/10 lb to a lower target\nstep-back burpees\nKnees: wall balls to a lower target.\nNo machine free: replace each row calorie with 4 jumping jacks (12 cal = 48 jumping jacks).\nCap 12:00 · Aim: finish under the cap, smooth · Feel: gas · Pace: reach", "For time, 15-12-9:\ncal row\nwall balls 10/14 lb to 9 ft\nburpees\nKnees: wall balls to a lower target.\nNo machine free: replace each row calorie with 8 single-unders (15 cal = 120 single-unders).\nCap 12:00 · Aim: finish under the cap · Feel: gas · Pace: reach", "For time, 15-12-9:\ncal row\nwall balls 14/20 lb to 9/10 ft\nburpees\nKnees: wall balls to a lower target.\nNo machine free: replace each row calorie with 8 single-unders (15 cal = 120 single-unders).\nCap 12:00 · Aim: 7:00–9:30 · Feel: gas · Pac