insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-02', 'Back Squat 5×6 + Bike/Burpee Intervals', 'Squat · intervals · hard', 'More squat volume at 70%, then short intervals with a built-in score.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["General (5 min): 2 rounds: 200 m easy row, 10 air squats, 10 band pull-aparts, 5 inchworms.\nSpecific (6 min): 10 goblet squats with 3 s pause, 10/side banded lateral walks, 10 empty-bar back squats, then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 2 rounds: 200 m easy row, 10 air squats, 10 band pull-aparts, 5 inchworms.\nSpecific (6 min): 10 goblet squats with 3 s pause, 10/side banded lateral walks, 10 empty-bar back squats, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 2 rounds: 200 m easy row, 10 air squats, 10 band pull-aparts, 5 inchworms.\nSpecific (6 min): 10 goblet squats with 3 s pause, 10/side banded lateral walks, 10 empty-bar back squats, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 2 rounds: 200 m easy row, 10 air squats, 10 band pull-aparts, 5 inchworms.\nSpecific (6 min): 10 goblet squats with 3 s pause, 10/side banded lateral walks, 10 empty-bar back squats, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "Back squat 5×6 @ 70%", "minutes": 20, "lift": {"movement": "Back squat", "gentleMovement": "Goblet squat", "mode": "percent", "sets": 5, "reps": 6, "pct": [null, 70, 70, 70], "note": "Ramp: empty bar × 10, 40% × 5, 50% × 3, 60% × 2, then working sets; rest 2:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Goblet box squat (light kettlebell or dumbbell at your chest, sit to a box at knee height, stand up tall): 5 × 6 at RPE 6–7 (3–4 reps left). Rest 2:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Back squat: 5 × 6 @ 70% of your estimated max (e1RM). Rest 2:00.\nLoad = e1RM × 0.7, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Back squat: 5 × 6 @ 70% of your estimated max (e1RM). Rest 2:00.\nLoad = e1RM × 0.7, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Back squat: 5 × 6 @ 70% of your estimated max (e1RM). Rest 2:00.\nLoad = e1RM × 0.7, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Bike/Burpee Intervals", "minutes": 15, "versions": ["4 rounds: 2:00 work / 1:00 rest (12:00).\nEach round: 5/6 cal air bike, then max incline step-back burpees (hands on a box) in the time left.\nScore = total reps.\nShoulder: burpees without the push-up.\nNo machine free: 5/6 cal air bike → 0:20 step-jacks or marching on the spot.\nCap 12:00 (fixed) · Aim: steady reps every round · Feel: gas · Pace: reach", "4 rounds: 2:00 work / 1:00 rest (12:00).\nEach round: 6/8 cal air bike, then max step-back burpees in the time left.\nScore = total burpees.\nShoulder: burpees without the push-up.\nNo machine free: 6/8 cal air bike → 30 jumping jacks.\nCap 12:00 (fixed) · Aim: steady burpees every round · Feel: gas · Pace: reach", "4 rounds: 2:00 work / 1:00 rest (12:00).\nEach round: 8/10 cal air bike, then max burpees in the time left.\nScore = total burpees.\nShoulder: burpees without the push-up.\nNo machine free: 8/10 cal air bike → 70 single-unders.\nCap 12:00 (fixed) · Aim: steady burpees every round · Feel: gas · Pace: reach", "4 rounds: 2:00 work / 1:00 rest (12:00).\nEach round: 9/12 cal air bike, then max burpees in the time left.\nScore = total burpees.\nShoulder: burpees without the push-up.\nNo machine free: 9/12 cal air bike → 80 single-unders.\nCap 12:00 (fixed) · Aim: 10–14 burpees per round, steady across all 4 · Feel: gas · Pace: reach"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory superset", "minutes": 5, "versions": ["Superset, 3 rounds, 3–4 reps left: 6/side split squats holding the rig, short range + 10 two-leg glute bridges.", "Superset, 3 rounds, 3 reps left: 8/side bodyweight split squats (hold the rig) + 10/side single-leg glute bridges.", "Superset, 3 rounds, 3 reps left: 8/side dumbbell Bulgarian split squats + 10/side single-leg glute bridges.", "Superset, 3 rounds, 3 reps left: 8/side dumbbell Bulgarian split squats + 10/side single-leg glute bridges."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump ro