insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-04', 'Deadlift 4×6 + Station Threshold 3×7', 'Deadlift · station threshold · sustain', 'Deadlift volume at 70%, then three identical threshold efforts on stations.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["General (5 min): 2 rounds: 250 m easy row, 10 PVC good mornings, 10 bird dogs, 5 push-ups.\nSpecific (6 min): 10 KB deadlifts, 8 empty-bar RDLs, then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 2 rounds: 250 m easy row, 10 PVC good mornings, 10 bird dogs, 5 push-ups.\nSpecific (6 min): 10 KB deadlifts, 8 empty-bar RDLs, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 2 rounds: 250 m easy row, 10 PVC good mornings, 10 bird dogs, 5 push-ups.\nSpecific (6 min): 10 KB deadlifts, 8 empty-bar RDLs, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 2 rounds: 250 m easy row, 10 PVC good mornings, 10 bird dogs, 5 push-ups.\nSpecific (6 min): 10 KB deadlifts, 8 empty-bar RDLs, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "Deadlift 4×6 @ 70%", "minutes": 16, "lift": {"movement": "Deadlift", "gentleMovement": "Kettlebell deadlift", "mode": "percent", "sets": 4, "reps": 6, "pct": [null, 70, 70, 70], "note": "Ramp: 40% × 5, 50% × 3, 60% × 2; reset every rep, no bouncing; rest 2:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Kettlebell deadlift (one light kettlebell between your feet; stand it on a low step if the floor is too far): 4 × 6 at RPE 6–7 (3–4 reps left). Rest 2:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Deadlift: 4 × 6 @ 70% of your estimated max (e1RM). Rest 2:00.\nLoad = e1RM × 0.7, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Deadlift: 4 × 6 @ 70% of your estimated max (e1RM). Rest 2:00.\nLoad = e1RM × 0.7, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Deadlift: 4 × 6 @ 70% of your estimated max (e1RM). Rest 2:00.\nLoad = e1RM × 0.7, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Station Threshold 3×7", "minutes": 22, "versions": ["3 × 7:00 AMRAP / 1:00 rest, at threshold effort (about 7/10):\n150 m row\n8 step-ups to a low step (total)\n4 incline step-back burpees (hands on a box), each followed by 2 long strides\nKnees: step-ups instead of lunges.\nNo machine free: 150 m row → 0:40 step-jacks or marching on the spot.\nCap 23:00 · Aim: steady effort in all three; rounds don''t have to match · Feel: cardio · Pace: sustain", "3 × 7:00 AMRAP / 1:00 rest, at threshold effort (about 7/10):\n200 m row\n12 lunges, bodyweight or sandbag 13/22 lb (total)\n6 step-back burpees, each followed by a broad jump\nKnees: step-ups instead of lunges.\nNo machine free: 200 m row → 50 jumping jacks.\nCap 23:00 · Aim: the same score (±1 round) in all three · Feel: cardio · Pace: sustain", "3 × 7:00 AMRAP / 1:00 rest, at threshold effort (about 7/10):\n250 m row\n12 sandbag lunges 22/33 lb (total)\n6 burpee broad jumps\nKnees: step-ups instead of lunges.\nNo machine free: 250 m row → 120 single-unders.\nCap 23:00 · Aim: the same score (±1 round) in all three · Feel: cardio · Pace: sustain", "3 × 7:00 AMRAP / 1:00 rest, at threshold effort (about 7/10):\n250 m row\n12 sandbag lunges 22/44 lb (total)\n6 burpee broad jumps\nKnees: step-ups instead of lunges.\nNo machine free: 250 m row → 120 single-unders.\nCap 23:00 · Aim: the same score (±1 round) in all three · Feel: cardio · Pace: sustain"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory superset", "minutes": 4, "versions": ["Superset, 3 rounds, 3–4 reps left: 8 ring rows on a high bar, body nearly upright + 20 m/side light kettlebell suitcase carry.", "Superset, 3 rounds, 2–3 reps left: 10 ring rows + 40 m/side kettlebell suitcase carry.", "Superset, 3 rounds, 2–3 reps left: 10 ring rows (or 5 strict chin-up negatives) + 40 m/side heavy kettlebell suitcase carry.", "Superset, 3 rounds, 2–3 reps left: 5 strict chin-up negatives (5 s down) + 40 m/side heavy kettlebell suitcase carry."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 4, "versions": ["3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
