insert into public.workout_coach_notes (class_date, body) values ('2026-11-05', 'If there aren''t enough rowers and bikes, run the class in two waves: wave 1 does the intervals while wave 2 does the accessory strength, then swap at about minute 31; or send the overflow to the ''No machine free'' bodyweight rounds. The intervals have no outside version on purpose: Thursday is machine-only so weekly running volume stays as planned.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-06', 'Clean + Press 5×6 + 10-min AMRAP', 'Clean + press · short workout · hard', 'More clean technique reps, press volume, and this block''s skill in a short workout.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["General (5 min): 3 min easy bike, 10 PVC pass-throughs, 10 PVC overhead squats.\nSpecific (7 min): barbell drills × 5 each: down-and-up, elbows high & fast, muscle clean, hang power clean; 10 empty-bar strict presses.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy bike, 10 PVC pass-throughs, 10 PVC overhead squats.\nSpecific (7 min): barbell drills × 5 each: down-and-up, elbows high & fast, muscle clean, hang power clean; 10 empty-bar strict presses.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy bike, 10 PVC pass-throughs, 10 PVC overhead squats.\nSpecific (7 min): barbell drills × 5 each: down-and-up, elbows high & fast, muscle clean, hang power clean; 10 empty-bar strict presses.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy bike, 10 PVC pass-throughs, 10 PVC overhead squats.\nSpecific (7 min): barbell drills × 5 each: down-and-up, elbows high & fast, muscle clean, hang power clean; 10 empty-bar strict presses.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "Power clean technique", "minutes": 8, "versions": ["Dumbbell clean technique, same clock (EMOM 10): one light dumbbell or kettlebell, hang clean it to your shoulder, then 1–2 goblet squats in place of each front squat.\nHalf the reps is fine. Stay at RPE 5–6; smooth reps only.", "Power clean technique: EMOM 10: 2 hang power cleans + 1 front squat (RPE 6–7).\nStay light: empty bar or light plates, and catch from the hang (above the knee) if the floor start feels rushed. Every rep fast and crisp; RPE 6 is plenty.", "Power clean technique: EMOM 10: 2 hang power cleans + 1 front squat (RPE 6–7).\nBuild by feel only: no percentages today. Every rep fast and crisp; stop adding weight when it slows down.", "Power clean technique: EMOM 10: 2 hang power cleans + 1 front squat (RPE 6–7).\nBuild by feel only: no percentages today. Every rep fast and crisp; stop adding weight when it slows down."]}, {"kind": "strength", "label": "Strength", "title": "Strict press 5×6 @ 70%", "minutes": 10, "lift": {"movement": "Strict press", "gentleMovement": "Dumbbell press", "mode": "percent", "sets": 5, "reps": 6, "pct": [null, 70, 70, 70], "note": "Build to the working weight in 2–3 lighter sets; rest 1:30–2:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Seated dumbbell press (light dumbbells, back against a bench): 5 × 6 at RPE 6–7 (3–4 reps left). Rest 1:30–2:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nBetween sets: 10 light dumbbell rear-delt flys.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Strict press: 5 × 6 @ 70% of your estimated max (e1RM). Rest 1:30–2:00.\nLoad = e1RM × 0.7, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Strict press: 5 × 6 @ 70% of your estimated max (e1RM). Rest 1:30–2:00.\nLoad = e1RM × 0.7, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Strict press: 5 × 6 @ 70% of your estimated max (e1RM). Rest 1:30–2:00.\nLoad = e1RM × 0.7, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "conditioning", "label": "Conditioning", "title": "10-min Dumbbell/T2B/Row AMRAP", "minutes": 19, "versions": ["AMRAP 10:00:\n4 alternating dumbbell hang clean & presses 10/15 lb\n6 lying bent-knee raises\n5/6 cal row\nBreak the core work early: under 1:00 a round.\nNo machine free: 5/6 cal row → 0:20 step-jacks or marching on the spot.\nCap 10:00 · Aim: steady rounds; rest when you need to · Feel: cardio · Pace: reach", "AMRAP 10:00:\n6 alternating dumbbell hang clean & jerks 15/20 lb\n8 lying leg raises\n6/8 cal row\nBreak the core work early: under 1:00 a round.\nNo machine free: 6/8 cal row → 30 jumping jacks.\nCap 10:00 · Aim: steady rounds · Feel: cardio · Pace: reach", "AMRAP 10:00:\n6 alternating dumbbell hang clean & jerks 25/35 lb\n8 hanging knee raises\n8/10 cal row\nBreak the hanging work early: under 1:00 a round.\nNo machine free: 8/10 cal row → 70 single-unders.\nCap 10:00 · Aim: steady rounds · Feel: cardio · Pace: reach", "AMRAP 10:00:\n6 alternating dumbbell hang clean & jerks 35/50 lb\n8 toes-to-bar\n8/10 cal row\nBreak the hanging work early: under 1:00 a round.\nNo machine free: 8/10 cal row → 70 single-unders.\nCap 10:00 · Aim: 6–8 rounds · Feel: cardio · Pace: reach"]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 8, "versions": ["3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
