insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-09', 'Back Squat 5×5 + Row/Press Intervals', 'Squat · intervals · hard', 'The heaviest Base squat week, then short, repeatable intervals.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["General (5 min): 3 min easy bike, then 2 rounds: 8/side Cossack squats, 10 glute bridges, 10 scap push-ups.\nSpecific (6 min): 2 × 5 pause back squats (empty bar), 3 low box jumps, then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy bike, then 2 rounds: 8/side Cossack squats, 10 glute bridges, 10 scap push-ups.\nSpecific (6 min): 2 × 5 pause back squats (empty bar), 3 low box jumps, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy bike, then 2 rounds: 8/side Cossack squats, 10 glute bridges, 10 scap push-ups.\nSpecific (6 min): 2 × 5 pause back squats (empty bar), 3 low box jumps, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy bike, then 2 rounds: 8/side Cossack squats, 10 glute bridges, 10 scap push-ups.\nSpecific (6 min): 2 × 5 pause back squats (empty bar), 3 low box jumps, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "Back squat 5×5 @ 75%", "minutes": 20, "lift": {"movement": "Back squat", "gentleMovement": "Goblet squat", "mode": "percent", "sets": 5, "reps": 5, "pct": [null, 75, 75, 75], "note": "Ramp: empty bar × 10, 40% × 5, 50% × 3, 60% × 2, then working sets; rest 2:30. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Goblet box squat (light kettlebell or dumbbell at your chest, sit to a box at knee height, stand up tall): 5 × 5 at RPE 6–7 (3–4 reps left). Rest 2:30.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Back squat: 5 × 5 @ 75% of your estimated max (e1RM). Rest 2:30.\nLoad = e1RM × 0.75, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Back squat: 5 × 5 @ 75% of your estimated max (e1RM). Rest 2:30.\nLoad = e1RM × 0.75, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Back squat: 5 × 5 @ 75% of your estimated max (e1RM). Rest 2:30.\nLoad = e1RM × 0.75, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Row/Press Intervals", "minutes": 15, "versions": ["Every 2:00 × 6 (12:00):\n5/6 cal row\n6 dumbbell push press, 2 × 5 lb\nRest for the rest of each 2:00.\nShoulder: single-arm landmine press instead.\nNo machine free: 5/6 cal row → 0:20 step-jacks or marching on the spot.\nCap 12:00 (fixed) · Aim: each round under 1:30 · Feel: gas · Pace: reach", "Every 2:00 × 6 (12:00):\n7/10 cal row\n8 dumbbell push press, 2 × 10 lb\nRest for the rest of each 2:00.\nShoulder: single-arm landmine press instead.\nNo machine free: 7/10 cal row → 35 jumping jacks.\nCap 12:00 (fixed) · Aim: each round under 1:10 · Feel: gas · Pace: reach", "Every 2:00 × 6 (12:00):\n9/12 cal row\n8 dumbbell push press, 2 × 15/20 lb\nRest for the rest of each 2:00.\nShoulder: single-arm landmine press instead.\nNo machine free: 9/12 cal row → 80 single-unders.\nCap 12:00 (fixed) · Aim: each round under 1:10 · Feel: gas · Pace: reach", "Every 2:00 × 6 (12:00):\n11/14 cal row\n8 dumbbell push press, 2 × 25/35 lb\nRest for the rest of each 2:00.\nShoulder: single-arm landmine press instead.\nNo machine free: 11/14 cal row → 100 single-unders.\nCap 12:00 (fixed) · Aim: each round under 1:10 · Feel: gas · Pace: reach"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory superset", "minutes": 5, "versions": ["Superset, 3 rounds, 3–4 reps left: 6/side side lunges holding the rig, short range + 20 s/side light Pallof hold.", "Superset, 3 rounds, 3 reps left: 8/side bodyweight Cossack squats (to a box if needed) + 30 s/side Pallof hold.", "Superset, 3 rounds, 3 reps left: 8/side goblet Cossack squats + 30 s/side Pallof hold.", "Superset, 3 rounds, 3 reps left: 8/side goblet Cossack squats + 30 s/side Pallof hold."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
