insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-10', 'T2B Kipping Knee Raise + Aerobic Every 8:00', 'Toes-to-bar · aerobic intervals · moderate', 'Link the kip swing to the knee raise, then steady aerobic intervals.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["General (5 min): 2 min easy jump rope, 200 m jog, high knees and butt kicks.\nSpecific (6 min): 10 scap pull-ups, 2 × 10 hollow-to-arch swings on the bar, 5 kipping knee raises, 2 × 100 m strides.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.", "General (5 min): 2 min easy jump rope, 200 m jog, high knees and butt kicks.\nSpecific (6 min): 10 scap pull-ups, 2 × 10 hollow-to-arch swings on the bar, 5 kipping knee raises, 2 × 100 m strides.", "General (5 min): 2 min easy jump rope, 200 m jog, high knees and butt kicks.\nSpecific (6 min): 10 scap pull-ups, 2 × 10 hollow-to-arch swings on the bar, 5 kipping knee raises, 2 × 100 m strides.", "General (5 min): 2 min easy jump rope, 200 m jog, high knees and butt kicks.\nSpecific (6 min): 10 scap pull-ups, 2 × 10 hollow-to-arch swings on the bar, 5 kipping knee raises, 2 × 100 m strides."]}, {"kind": "skill", "label": "Skill", "title": "Toes-to-bar level 3: kipping knee raise", "minutes": 13, "versions": ["Toes-to-bar level 3, EMOM 10:\nOdd minutes: 6 lying bent-knee raises\nEven minutes: 15 s tuck hollow hold", "Toes-to-bar level 3, EMOM 10:\nOdd minutes: 5 hanging knee raises (any height)\nEven minutes: 8 lying leg raises", "Toes-to-bar level 3, EMOM 10:\nOdd minutes: 3–5 kipping knee raises (knees above hips)\nEven minutes: 3–5 kipping knee raises", "Toes-to-bar level 3, EMOM 10:\nOdd minutes: 3–5 kipping knee raises (knees above hips)\nEven minutes: 3 kip swings + 2–3 toes-to-bar singles (if ready; otherwise knee raises)"]}, {"kind": "conditioning", "label": "Conditioning", "title": "Row Every 8:00", "minutes": 28, "versions": ["Every 8:00 × 4 (32:00), RPE 6:\n400 m row\n8 wall balls 4/6 lb to a low target\n5/6 cal air bike, easy\nRest for the rest of each 8:00.\nNo machine free: 400 m row → 1:40 step-jacks or marching on the spot; 5/6 cal air bike → 0:20 step-jacks or marching on the spot.\nCap 32:00 (fixed) · Aim: row splits within 5 s; 2–3 min rest each round · Feel: cardio · Pace: sustain", "Every 8:00 × 4 (32:00), RPE 6:\n500 m row\n10 wall balls 6/10 lb\n8/10 cal air bike, easy\nRest for the rest of each 8:00.\nNo machine free: 500 m row → 125 jumping jacks; 8/10 cal air bike → 35 jumping jacks.\nCap 32:00 (fixed) · Aim: row splits within 5 s; 2–3 min rest each round · Feel: cardio · Pace: sustain", "Every 8:00 × 4 (32:00), RPE 6:\n600 m row\n15 wall balls 6/10 lb\n8/10 cal air bike, easy\nRest for the rest of each 8:00.\nNo machine free: 600 m row → 300 single-unders; 8/10 cal air bike → 70 single-unders.\nCap 32:00 (fixed) · Aim: row splits within 5 s; 2–3 min rest each round · Feel: cardio · Pace: sustain", "Every 8:00 × 4 (32:00), RPE 6:\n750 m row\n15 wall balls 10/14 lb\n8/10 cal air bike, easy\nRest for the rest of each 8:00.\nNo machine free: 750 m row → 380 single-unders; 8/10 cal air bike → 70 single-unders.\nCap 32:00 (fixed) · Aim: row splits within 5 s; 2–3 min rest each round · Feel: cardio · Pace: sustain"], "outdoor": {"title": "Run Every 8:00", "versions": ["Every 8:00 × 4 (32:00), RPE 6:\n300 m walk/jog\n8 wall balls 4/6 lb to a low target\n5/6 cal air bike, easy\nRest for the rest of each 8:00.\nNo machine free: 5/6 cal air bike → 100 m walk/jog.\nCap 32:00 (fixed) · Aim: run splits within 10 s; 2–3 min rest each round · Feel: cardio · Pace: sustain", "Every 8:00 × 4 (32:00), RPE 6:\n400 m run/walk\n10 wall balls 6/10 lb\n8/10 cal air bike, easy\nRest for the rest of each 8:00.\nNo machine free: 8/10 cal air bike → 200 m run.\nCap 32:00 (fixed) · Aim: run splits within 10 s; 2–3 min rest each round · Feel: cardio · Pace: sustain", "Every 8:00 × 4 (32:00), RPE 6:\n500 m run\n15 wall balls 6/10 lb\n8/10 cal air bike, easy\nRest for the rest of each 8:00.\nNo machine free: 8/10 cal air bike → 200 m run.\nCap 32:00 (fixed) · Aim: run splits within 10 s; 2–3 min rest each round · Feel: cardio · Pace: sustain", "Every 8:00 × 4 (32:00), RPE 6:\n600 m run\n15 wall balls 10/14 lb\n8/10 cal air bike, easy\nRest for the rest of each 8:00.\nNo machine free: 8/10 cal air bike → 200 m run.\nCap 32:00 (fixed) · Aim: run splits within 10 s; 2–3 min rest each round · Feel: cardio · Pace: sustain"]}}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min."]}]'::jsonb, 'published', null)
