insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-11', 'Deadlift 4×5 + 25-min Row Threshold + Stations', 'Deadlift · threshold · sustain', 'The heaviest Base deadlift, then threshold rowing that alternates with stations.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["General (5 min): 3 min easy row, then 2 rounds: 10 banded hip hinges, 10/side dead bugs, 10 ring rows.\nSpecific (6 min): 5 slow RDLs + 3 deadlifts at 40–50%, then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy row, then 2 rounds: 10 banded hip hinges, 10/side dead bugs, 10 ring rows.\nSpecific (6 min): 5 slow RDLs + 3 deadlifts at 40–50%, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy row, then 2 rounds: 10 banded hip hinges, 10/side dead bugs, 10 ring rows.\nSpecific (6 min): 5 slow RDLs + 3 deadlifts at 40–50%, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy row, then 2 rounds: 10 banded hip hinges, 10/side dead bugs, 10 ring rows.\nSpecific (6 min): 5 slow RDLs + 3 deadlifts at 40–50%, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "Deadlift 4×5 @ 75%", "minutes": 15, "lift": {"movement": "Deadlift", "gentleMovement": "Kettlebell deadlift", "mode": "percent", "sets": 4, "reps": 5, "pct": [null, 75, 75, 75], "note": "Ramp: 40% × 5, 50% × 3, 60% × 2; reset every rep, no bouncing; rest 2:30. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Kettlebell deadlift (one light kettlebell between your feet; stand it on a low step if the floor is too far): 4 × 5 at RPE 6–7 (3–4 reps left). Rest 2:30.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Deadlift: 4 × 5 @ 75% of your estimated max (e1RM). Rest 2:30.\nLoad = e1RM × 0.75, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Deadlift: 4 × 5 @ 75% of your estimated max (e1RM). Rest 2:30.\nLoad = e1RM × 0.75, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Deadlift: 4 × 5 @ 75% of your estimated max (e1RM). Rest 2:30.\nLoad = e1RM × 0.75, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Row Threshold + Stations", "minutes": 26, "versions": ["25:00 in alternating 5:00 blocks (5 blocks):\nOdd blocks (3): row at a steady pace, about 6/10 effort: you can still say a sentence. Score metres.\nEven blocks (2): as many rounds as possible of\n8 wall balls 4/6 lb to a low target\n20 m farmers carry 2 × 13/18 lb\n8 step-ups to a low step\nKnees: step-ups instead of lunges.\nNo machine free: each row block → 5:00 of step-ups to a low step and marching, switching every minute; score total step-ups.\nCap 25:00 (fixed) · Aim: row metres within 50 m across the 3 row blocks · Feel: cardio · Pace: sustain", "25:00 in alternating 5:00 blocks (5 blocks):\nOdd blocks (3): row at threshold pace, about 7/10 effort: breathing hard but controlled, a few words at a time. Score metres.\nEven blocks (2): as many rounds as possible of\n10 wall balls 6/10 lb\n20 m farmers carry 2 × 18/26 lb\n10 bodyweight lunges\nKnees: step-ups instead of lunges.\nNo machine free: each row block → 5:00 of jumping jacks and air squats, switching every minute; score total reps.\nCap 25:00 (fixed) · Aim: row metres within 50 m across the 3 row blocks · Feel: cardio · Pace: sustain", "25:00 in alternating 5:00 blocks (5 blocks):\nOdd blocks (3): row at threshold pace, about 7/10 effort: breathing hard but controlled, a few words at a time. Score metres.\nEven blocks (2): as many rounds as possible of\n10 wall balls 6/10 lb\n20 m farmers carry 2 × 26/35 lb\n10 sandbag lunges 22/33 lb\nKnees: step-ups instead of lunges.\nNo machine free: each row block → 5:00 of single-unders and air squats, switching every minute; score total reps.\nCap 25:00 (fixed) · Aim: row metres within 50 m across the 3 row blocks · Feel: cardio · Pace: sustain", "25:00 in alternating 5:00 blocks (5 blocks):\nOdd blocks (3): row at threshold pace, about 7/10 effort: breathing hard but controlled, a few words at a time. Score metres.\nEven blocks (2): as many rounds as possible of\n10 wall balls 10/14 lb\n20 m farmers carry 2 × 35/53 lb\n10 sandbag lunges 22/44 lb\nKnees: step-ups instead of lunges.\nNo machine free: each row block → 5:00 of single-unders and air squats, switching every minute; score total reps.\nCap 25:00 (fixed) · Aim: row metres within 50 m across the 3 row blocks · Feel: cardio · Pace: sustain"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory superset", "minutes": 2, "versions": ["Superset, 2 rounds, 3–4 reps left: 8 light chest-supported dumbbell rows + 15 m/side light kettlebell suitcase carry.", "Superset, 2 rounds, 2–3 reps left: 10 light chest-supported dumbbell rows + 20 m/side kettlebell suitcase carry.", "Superset, 2 rounds, 2–3 reps left: 10 chest-supported dumbbell rows + 20 m/side heavy kettlebell suitcase carry.", "Superset, 2 rounds, 2–3 reps left: 10 chest-supported dumbbell rows + 20 m/side heavy kettlebell suitcase carry."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 3, "versions": ["3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
