insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-12', 'Accessory Strength + Easy Row/Bike Intervals', 'Accessory strength · easy intervals · easy', 'The easy day: strength work for joints and posture, then easy intervals with set work and rest. Nobody should breathe hard today.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 7, "versions": ["General (4 min): 2 min easy row, 10 cat-cows, 10/side couch-stretch rocks.\nSpecific (3 min): 5/side bodyweight step-ups, 10 scap pull-ups, 10 wall slides.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (4 min): 2 min easy row, 10 cat-cows, 10/side couch-stretch rocks.\nSpecific (3 min): 5/side bodyweight step-ups, 10 scap pull-ups, 10 wall slides.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (4 min): 2 min easy row, 10 cat-cows, 10/side couch-stretch rocks.\nSpecific (3 min): 5/side bodyweight step-ups, 10 scap pull-ups, 10 wall slides.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (4 min): 2 min easy row, 10 cat-cows, 10/side couch-stretch rocks.\nSpecific (3 min): 5/side bodyweight step-ups, 10 scap pull-ups, 10 wall slides.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "skill", "label": "Accessory", "title": "Accessory strength + core", "minutes": 21, "versions": ["3 rounds, 3–4 reps left on every set (1:00 rest after each round):\nA1) 6/side bodyweight step-ups to a low step, holding the rig\nA2) 8 ring rows on a high bar, body nearly upright\nA3) 15 s/side side plank from the knees + 10 seated tibialis raises", "3 rounds, 2–3 reps left on every set (1:00 rest after each round):\nA1) 8/side bodyweight step-ups to a low box\nA2) 10 ring rows with your body more upright\nA3) 20 s/side side plank from the knees + 15 tibialis raises", "3 rounds, 2–3 reps left on every set (1:00 rest after each round):\nA1) 8/side dumbbell step-ups to a knee-height box\nA2) 10 ring rows\nA3) 20 s/side short-lever Copenhagen plank + 15 tibialis raises", "3 rounds, 2–3 reps left on every set (1:00 rest after each round):\nA1) 8/side dumbbell step-ups to a knee-height box\nA2) 10 ring rows\nA3) 20 s/side short-lever Copenhagen plank + 15 tibialis raises"]}, {"kind": "conditioning", "label": "Easy intervals", "title": "Easy row/bike intervals", "minutes": 21, "versions": ["3 × 6:00 easy / 1:00 rest (20:00), alternating row and air bike each round.\nEffort: RPE 3–4 (very easy). Air bike or row; each round can be 1:00–2:00 shorter, and slow pedalling is fine.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: marching on the spot, step-ups to a low step, wall push-ups; repeat until the work time ends.\nCap 20:00 (fixed) · Aim: same easy pace every round; you could keep going · Feel: cardio (easy) · Pace: sustain", "3 × 6:00 easy / 1:00 rest (20:00), alternating row and air bike each round.\nEffort: RPE 4 (easy, chatty). Air bike or row. Rounds can be 1:00 shorter.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: step-ups to a low box, jumping jacks, air squats; repeat until the work time ends.\nCap 20:00 (fixed) · Aim: same pace every round: row split 0:15–0:25 per 500 m slower than your 1 km test split; bike, same calories each round (±1) · Feel: cardio (easy) · Pace: sustain", "3 × 6:00 easy / 1:00 rest (20:00), alternating row and air bike each round.\nEffort: RPE 4–5. Row or air bike.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: step-ups, jumping jacks, air squats, easy single-unders; repeat until the work time ends.\nCap 20:00 (fixed) · Aim: same pace every round: row split 0:15–0:25 per 500 m slower than your 1 km test split; bike, same calories each round (±1) · Feel: cardio (easy) · Pace: sustain", "3 × 6:00 easy / 1:00 rest (20:00), alternating row and air bike each round.\nEffort: RPE 5. Row or air bike.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: step-ups, jumping jacks, air squats, easy single-unders; repeat until the work time ends.\nCap 20:00 (fixed) · Aim: same pace every round: row split 0:15–0:25 per 500 m slower than your 1 km test split; bike, same calories each round (±1) · Feel: cardio (easy) · Pace: sustain"]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + mobility", "minutes": 8, "versions": ["3 min easy row; pigeon stretch 1 min/side; shoulder stretch on a bench 1 min; 1 min dead hang.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; shoulder stretch on a bench 1 min; 1 min dead hang.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; shoulder stretch on a bench 1 min; 1 min dead hang.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; shoulder stretch on a bench 1 min; 1 min dead hang.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
