insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-13', 'Clean Complex + Press 5×5 + CINDY', 'Clean + press · Cindy benchmark · hard', 'Benchmark Friday: Cindy, a classic bodyweight test of steady effort. Log it to see your mid-block progress.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["General (5 min): 300 m easy row, 10 scap push-ups, 10 air squats.\nSpecific (7 min): clean pull from knee × 5, high-hang power clean × 5, front squat × 5 (empty bar); 2 × 8 band presses.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 300 m easy row, 10 scap push-ups, 10 air squats.\nSpecific (7 min): clean pull from knee × 5, high-hang power clean × 5, front squat × 5 (empty bar); 2 × 8 band presses.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 300 m easy row, 10 scap push-ups, 10 air squats.\nSpecific (7 min): clean pull from knee × 5, high-hang power clean × 5, front squat × 5 (empty bar); 2 × 8 band presses.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 300 m easy row, 10 scap push-ups, 10 air squats.\nSpecific (7 min): clean pull from knee × 5, high-hang power clean × 5, front squat × 5 (empty bar); 2 × 8 band presses.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "Power clean technique", "minutes": 9, "versions": ["Dumbbell clean technique, same clock (Every 1): one light dumbbell or kettlebell, hang clean it to your shoulder, then 1–2 goblet squats in place of each front squat.\nHalf the reps is fine. Stay at RPE 5–6; smooth reps only.", "Power clean technique: Every 1:30 × 6 (9 min): power clean + hang power clean + front squat, build to RPE 7.\nStay light: empty bar or light plates, and catch from the hang (above the knee) if the floor start feels rushed. Every rep fast and crisp; RPE 6 is plenty.", "Power clean technique: Every 1:30 × 6 (9 min): power clean + hang power clean + front squat, build to RPE 7.\nBuild by feel only: no percentages today. Every rep fast and crisp; stop adding weight when it slows down.", "Power clean technique: Every 1:30 × 6 (9 min): power clean + hang power clean + front squat, build to RPE 7.\nBuild by feel only: no percentages today. Every rep fast and crisp; stop adding weight when it slows down."]}, {"kind": "strength", "label": "Strength", "title": "Strict press 5×5 @ 75%", "minutes": 9, "lift": {"movement": "Strict press", "gentleMovement": "Dumbbell press", "mode": "percent", "sets": 5, "reps": 5, "pct": [null, 75, 75, 75], "note": "Build to the working weight in 2–3 lighter sets; rest 1:30–2:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Seated dumbbell press (light dumbbells, back against a bench): 5 × 5 at RPE 6–7 (3–4 reps left). Rest 1:30–2:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Strict press: 5 × 5 @ 75% of your estimated max (e1RM). Rest 1:30–2:00.\nLoad = e1RM × 0.75, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Strict press: 5 × 5 @ 75% of your estimated max (e1RM). Rest 1:30–2:00.\nLoad = e1RM × 0.75, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Strict press: 5 × 5 @ 75% of your estimated max (e1RM). Rest 1:30–2:00.\nLoad = e1RM × 0.75, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "conditioning", "label": "Benchmark", "title": "CINDY", "minutes": 20, "versions": ["CINDY: AMRAP 20:00:\n5 ring rows on a high bar, body nearly upright\n10 wall push-ups\n10 squats to a high box\nKeep pull-up sets unbroken: scale before you break them into singles.\nCap 20:00 · Aim: 8–12 rounds · Feel: cardio · Pace: sustain\nRecord: rounds + reps and level.", "CINDY: AMRAP 20:00:\n5 ring rows\n10 incline push-ups\n15 box squats\nKeep pull-up sets unbroken: scale before you break them into singles.\nCap 20:00 · Aim: 10–14 rounds · Feel: cardio · Pace: sustain\nRecord: rounds + reps and level.", "CINDY: AMRAP 20:00:\n5 banded or jumping pull-ups\n10 push-ups (hands on a box if needed)\n15 air squats\nKeep pull-up sets unbroken: scale before you break them into singles.\nCap 20:00 · Aim: 12–16 rounds · Feel: cardio · Pace: sustain\nRecord: rounds + reps and level.", "CINDY: AMRAP 20:00:\n5 pull-ups (kipping OK)\n10 push-ups\n15 air squats\nKeep pull-up sets unbroken: scale before you break them into singles.\nCap 20:00 · Aim: 15–20 rounds · Feel: cardio · Pace: sustain\nRecord: rounds + reps and level."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 7, "versions": ["3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
