insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-16', 'Back Squat 5×3 + Row/Wall Ball Intervals', 'Squat · intervals · hard', 'Heavier triples. The intervals get harder, with longer rests.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["General (5 min): 3 min easy bike, then 2 rounds: 8/side Cossack squats, 10 glute bridges, 10 scap push-ups.\nSpecific (6 min): 2 × 5 pause back squats (empty bar), 3 low box jumps, then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy bike, then 2 rounds: 8/side Cossack squats, 10 glute bridges, 10 scap push-ups.\nSpecific (6 min): 2 × 5 pause back squats (empty bar), 3 low box jumps, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy bike, then 2 rounds: 8/side Cossack squats, 10 glute bridges, 10 scap push-ups.\nSpecific (6 min): 2 × 5 pause back squats (empty bar), 3 low box jumps, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy bike, then 2 rounds: 8/side Cossack squats, 10 glute bridges, 10 scap push-ups.\nSpecific (6 min): 2 × 5 pause back squats (empty bar), 3 low box jumps, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "Back squat 5×3 @ 80%", "minutes": 20, "lift": {"movement": "Back squat", "gentleMovement": "Goblet squat", "mode": "percent", "sets": 5, "reps": 3, "pct": [null, 80, 80, 80], "note": "Ramp: empty bar × 10, 40% × 5, 50% × 3, 60% × 2, then working sets; rest 2:30. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Goblet box squat (light kettlebell or dumbbell at your chest, sit to a box at knee height, stand up tall): 5 × 3 at RPE 6–7 (3–4 reps left). Rest 2:30.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Back squat: 5 × 3 @ 80% of your estimated max (e1RM). Rest 2:30.\nLoad = e1RM × 0.8, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Back squat: 5 × 3 @ 80% of your estimated max (e1RM). Rest 2:30.\nLoad = e1RM × 0.8, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Back squat: 5 × 3 @ 80% of your estimated max (e1RM). Rest 2:30.\nLoad = e1RM × 0.8, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Row/Wall Ball Intervals", "minutes": 15, "versions": ["Every 3:00 × 4 (12:00):\n6/8 cal row\n6 wall balls 4/6 lb to a low target\nRest for the rest of each 3:00.\nSore knees after squats: wall balls to a box target.\nNo machine free: 6/8 cal row → 0:30 step-jacks or marching on the spot.\nCap 12:00 (fixed) · Aim: each round under 2:00 · Feel: gas · Pace: reach", "Every 3:00 × 4 (12:00):\n8/10 cal row\n8 wall balls 6/10 lb\nRest for the rest of each 3:00.\nSore knees after squats: wall balls to a box target.\nNo machine free: 8/10 cal row → 35 jumping jacks.\nCap 12:00 (fixed) · Aim: each round under 1:40 · Feel: gas · Pace: reach", "Every 3:00 × 4 (12:00):\n10/13 cal row\n10 wall balls 10/14 lb\nRest for the rest of each 3:00.\nSore knees after squats: wall balls to a box target.\nNo machine free: 10/13 cal row → 90 single-unders.\nCap 12:00 (fixed) · Aim: each round under 1:40 · Feel: gas · Pace: reach", "Every 3:00 × 4 (12:00):\n12/15 cal row\n10 wall balls 14/20 lb\nRest for the rest of each 3:00.\nSore knees after squats: wall balls to a box target.\nNo machine free: 12/15 cal row → 110 single-unders.\nCap 12:00 (fixed) · Aim: each round under 1:40 · Feel: gas · Pace: reach"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory superset", "minutes": 5, "versions": ["Superset, 3 rounds, 3–4 reps left: 6/side split squats holding the rig, short range + 10 two-leg glute bridges.", "Superset, 3 rounds, 2–3 reps left: 8/side bodyweight split squats + 10/side single-leg glute bridges.", "Superset, 3 rounds, 2–3 reps left: 8/side rear-foot-elevated split squats + 10 back extensions.", "Superset, 3 rounds, 2–3 reps left: 8/side rear-foot-elevated split squats + 10 back extensions."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
