insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-17', 'T2B Singles to Small Sets + Aerobic Intervals', 'Toes-to-bar · aerobic intervals · moderate', 'Turn toes-to-bar singles into small sets, then aerobic intervals that keep building.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["General (5 min): 2 min easy jump rope, 200 m jog, high knees and butt kicks.\nSpecific (6 min): 10 scap pull-ups, 2 × 10 hollow-to-arch swings on the bar, 5 kipping knee raises, 2 × 100 m strides.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.", "General (5 min): 2 min easy jump rope, 200 m jog, high knees and butt kicks.\nSpecific (6 min): 10 scap pull-ups, 2 × 10 hollow-to-arch swings on the bar, 5 kipping knee raises, 2 × 100 m strides.", "General (5 min): 2 min easy jump rope, 200 m jog, high knees and butt kicks.\nSpecific (6 min): 10 scap pull-ups, 2 × 10 hollow-to-arch swings on the bar, 5 kipping knee raises, 2 × 100 m strides.", "General (5 min): 2 min easy jump rope, 200 m jog, high knees and butt kicks.\nSpecific (6 min): 10 scap pull-ups, 2 × 10 hollow-to-arch swings on the bar, 5 kipping knee raises, 2 × 100 m strides."]}, {"kind": "skill", "label": "Skill", "title": "Toes-to-bar level 4: small sets", "minutes": 13, "versions": ["Toes-to-bar level 4, every 1:30 × 6:\n5 lying leg raises (bent knees OK) + 10 s tuck hollow hold", "Toes-to-bar level 4, every 1:30 × 6:\n5 tucked hanging knee raises", "Toes-to-bar level 4, every 1:30 × 6:\n3–5 kipping knee raises + 1 toes-to-bar attempt", "Toes-to-bar level 4, every 1:30 × 6:\n2–4 toes-to-bar in a row. Stop before the kip falls apart."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Row/Step-up/Bike Every 7:00", "minutes": 28, "versions": ["Every 7:00 × 4 (28:00), RPE 6:\n250 m row\n8 step-ups to a low step\n6/8 cal air bike\nRest for the rest of each 7:00.\nNo machine free: 250 m row → 1:00 step-jacks or marching on the spot; 6/8 cal air bike → 0:30 step-jacks or marching on the spot.\nCap 28:00 (fixed) · Aim: row splits within 5 s · Feel: cardio · Pace: sustain", "Every 7:00 × 4 (28:00), RPE 6:\n400 m row\n10 step-ups to a low box\n8/10 cal air bike\nRest for the rest of each 7:00.\nNo machine free: 400 m row → 100 jumping jacks; 8/10 cal air bike → 35 jumping jacks.\nCap 28:00 (fixed) · Aim: row splits within 5 s · Feel: cardio · Pace: sustain", "Every 7:00 × 4 (28:00), RPE 6:\n500 m row\n12 bodyweight step-ups\n10/12 cal air bike\nRest for the rest of each 7:00.\nNo machine free: 500 m row → 250 single-unders; 10/12 cal air bike → 90 single-unders.\nCap 28:00 (fixed) · Aim: row splits within 5 s · Feel: cardio · Pace: sustain", "Every 7:00 × 4 (28:00), RPE 6:\n500 m row\n12 dumbbell step-ups, 2 × 15/20 lb\n11/14 cal air bike\nRest for the rest of each 7:00.\nNo machine free: 500 m row → 250 single-unders; 11/14 cal air bike → 100 single-unders.\nCap 28:00 (fixed) · Aim: row splits within 5 s · Feel: cardio · Pace: sustain"], "outdoor": {"title": "Run/Step-up/Bike Every 7:00", "versions": ["Every 7:00 × 4 (28:00), RPE 6:\n200 m walk/jog\n8 step-ups to a low step\n6/8 cal air bike\nRest for the rest of each 7:00.\nNo machine free: 6/8 cal air bike → 150 m walk/jog.\nCap 28:00 (fixed) · Aim: run splits within 10 s · Feel: cardio · Pace: sustain", "Every 7:00 × 4 (28:00), RPE 6:\n300 m run/walk\n10 step-ups to a low box\n8/10 cal air bike\nRest for the rest of each 7:00.\nNo machine free: 8/10 cal air bike → 200 m run.\nCap 28:00 (fixed) · Aim: run splits within 10 s · Feel: cardio · Pace: sustain", "Every 7:00 × 4 (28:00), RPE 6:\n400 m run\n12 bodyweight step-ups\n10/12 cal air bike\nRest for the rest of each 7:00.\nNo machine free: 10/12 cal air bike → 200 m run.\nCap 28:00 (fixed) · Aim: run splits within 10 s · Feel: cardio · Pace: sustain", "Every 7:00 × 4 (28:00), RPE 6:\n400 m run\n12 dumbbell step-ups, 2 × 15/20 lb\n11/14 cal air bike\nRest for the rest of each 7:00.\nNo machine free: 11/14 cal air bike → 250 m run.\nCap 28:00 (fixed) · Aim: run splits within 10 s · Feel: cardio · Pace: sustain"]}}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min."]}]'::jsonb, 'published', null)
