insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-18', 'Deadlift 4×3 + Compromised Running 5s', 'Deadlift · compromised running · sustain', 'Heavier deadlift triples, then our first compromised running: run straight off a station and settle into your pace within 100 m.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["General (5 min): 3 min easy row, then 2 rounds: 10 banded hip hinges, 10/side dead bugs, 10 ring rows.\nSpecific (6 min): 5 slow RDLs + 3 deadlifts at 40–50%, then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy row, then 2 rounds: 10 banded hip hinges, 10/side dead bugs, 10 ring rows.\nSpecific (6 min): 5 slow RDLs + 3 deadlifts at 40–50%, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy row, then 2 rounds: 10 banded hip hinges, 10/side dead bugs, 10 ring rows.\nSpecific (6 min): 5 slow RDLs + 3 deadlifts at 40–50%, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy row, then 2 rounds: 10 banded hip hinges, 10/side dead bugs, 10 ring rows.\nSpecific (6 min): 5 slow RDLs + 3 deadlifts at 40–50%, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "Deadlift 4×3 @ 80%", "minutes": 14, "lift": {"movement": "Deadlift", "gentleMovement": "Kettlebell deadlift", "mode": "percent", "sets": 4, "reps": 3, "pct": [null, 80, 80, 80], "note": "Ramp: 40% × 5, 50% × 3, 60% × 2; reset every rep, no bouncing; rest 2:30. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Kettlebell deadlift (one light kettlebell between your feet; stand it on a low step if the floor is too far): 4 × 3 at RPE 6–7 (3–4 reps left). Rest 2:30.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Deadlift: 4 × 3 @ 80% of your estimated max (e1RM). Rest 2:30.\nLoad = e1RM × 0.8, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Deadlift: 4 × 3 @ 80% of your estimated max (e1RM). Rest 2:30.\nLoad = e1RM × 0.8, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Deadlift: 4 × 3 @ 80% of your estimated max (e1RM). Rest 2:30.\nLoad = e1RM × 0.8, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Bike-off-Station 5s", "minutes": 26, "versions": ["5 rounds for quality, RPE 6 (about 20 min). Each round: 5/6 cal air bike at a steady effort straight into the next station, in order:\n1) 150 m row\n2) 25 m sled push (empty sled or 1 light plate)\n3) 10 wall balls 4/6 lb to a low target\n4) 50 m farmers carry 2 × 13/18 lb\n5) 10 step-ups to a low step (total)\nStart on the station your coach gives you and go in order from there.\nNo free sled: 20 m light plate push on turf or 20 bodyweight walking lunges.\nNo machine free: 150 m row → 0:40 step-jacks or marching on the spot; 5/6 cal air bike → 0:20 step-jacks or marching on the spot.\nCap 24:00 · Aim: finish under the cap · Feel: cardio · Pace: sustain", "5 rounds for quality, RPE 7 (about 20 min). Each round: 6/8 cal air bike at threshold effort straight into the next station, in order:\n1) 200 m row\n2) 25 m sled push (sled + light plates)\n3) 15 wall balls 6/10 lb\n4) 50 m farmers carry 2 × 18/26 lb\n5) 16 lunges, sandbag 13/22 lb or none (total)\nStart on the station your coach gives you and go in order from there.\nNo free sled: 20 m heavy plate push on turf or 20 heavy DB walking lunges.\nNo machine free: 200 m row → 50 jumping jacks; 6/8 cal air bike → 30 jumping jacks.\nCap 24:00 · Aim: finish under the cap · Feel: cardio · Pace: sustain", "5 rounds for quality, RPE 7 (about 20 min). Each round: 8/10 cal air bike at threshold effort straight into the next station, in order:\n1) 250 m row\n2) 25 m sled push (about 25% lighter than Full)\n3) 20 wall balls 6/10 lb\n4) 50 m farmers carry 2 × 26/35 lb\n5) 16 sandbag lunges 22/33 lb (total)\nStart on the station your coach gives you and go in order from there.\nNo free sled: 20 m heavy plate push on turf or 20 heavy DB walking lunges.\nNo machine free: 250 m row → 120 single-unders; 8/10 cal air bike → 70 single-unders.\nCap 24:00 · Aim: same bike pace every round · Feel: cardio · Pace: sustain", "5 rounds for quality, RPE 7 (about 20 min). Each round: 8/10 cal air bike at threshold effort straight into the next station, in order:\n1) 250 m row\n2) 25 m sled push (heavy, but moving without stopping for 12.5 m)\n3) 20 wall balls 10/14 lb\n4) 50 m farmers carry 2 × 35/53 lb\n5) 16 sandbag lunges 22/44 lb (total)\nStart on the station your coach gives you and go in order from there.\nNo free sled: 20 m heavy plate push on turf or 20 heavy DB walking lunges.\nNo machine free: 250 m row → 120 single-unders; 8/10 cal air bike → 70 single-unders.\nCap 24:00 · Aim: 16:00–20:00; same bike pace every round · Feel: cardio · Pace: sustain"], "outdoor": {"title": "Compromised Running 5s", "versions": ["5 rounds for quality, RPE 6 (about 20 min). Each round: 100 m walk/jog straight into the next station, in order:\n1) 150 m row\n2) 25 m sled push (empty sled or 1 light plate)\n3) 10 wall balls 4/6 lb to a low target\n4) 50 m farmers carry 2 × 13/18 lb\n5) 10 step-ups to a low step (total)\nStart on the station your coach gives you and go in order from there.\nNo free sled: 20 m light plate push on turf or 20 bodyweight walking lunges.\nNo machine free: 150 m row → 100 m walk/jog.\nCap 24:00 · Aim: finish under the cap; walking between stations is fine · Feel: cardio · Pace: sustain", "5 rounds for quality, RPE 7 (about 20 min). Each round: 150 m run/walk straight into the next station, in order:\n1) 200 m row\n2) 25 m sled push (sled + light plates)\n3) 15 wall balls 6/10 lb\n4) 50 m farmers carry 2 × 18/26 lb\n5) 16 lunges, sandbag 13/22 lb or none (total)\nStart on the station your coach gives you and go in order from there.\nNo free sled: 20 m heavy plate push on turf or 20 heavy DB walking lunges.\nNo machine free: 200 m row → 150 m run.\nCap 24:00 · Aim: finish under the cap; every run at the same easy-hard pace · Feel: cardio · Pace: sustain", "5 rounds for quality, RPE 7 (about 20 min). Each round: 200 m run straight into the next station, in order:\n1) 250 m row\n2) 25 m sled push (about 25% lighter than Full)\n3) 20 wall balls 6/10 lb\n4) 50 m farmers carry 2 × 26/35 lb\n5) 16 sandbag lunges 22/33 lb (total)\nStart on the station your coach gives you and go in order from there.\nNo free sled: 20 m heavy plate push on turf or 20 heavy DB walking lunges.\nNo machine free: 250 m row → 200 m run.\nCap 24:00 · Aim: every 200 m at the same pace · Feel: cardio · Pace: sustain", "5 rounds for quality, RPE 7 (about 20 min). Each round: 200 m run straight into the next station, in order:\n1) 250 m row\n2) 25 m sled push (heavy, but moving without stopping for 12.5 m)\n3) 20 wall balls 10/14 lb\n4) 50 m farmers carry 2 × 35/53 lb\n5) 16 sandbag lunges 22/44 lb (total)\nStart on the station your coach gives you and go in order from there.\nNo free sled: 20 m heavy plate push on turf or 20 heavy DB walking lunges.\nNo machine free: 250 m row → 200 m run.\nCap 24:00 · Aim: 16:00–20:00; every 200 m at threshold pace (1 km test pace + 0:40–0:50 per km) · Feel: cardio · Pace: sustain"]}}, {"kind": "skill", "label": "Accessory", "title": "Accessory superset", "minutes": 3, "versions": ["Superset, 2 rounds, 3–4 reps left: 6 ring rows on a high bar, body nearly upright + 15 s tuck hollow hold.", "Superset, 2 rounds, 2–3 reps left: 8 ring rows + 30 s tuck hollow hold.", "Superset, 2 rounds, 2–3 reps left: 6–8 strict pull-ups (band if needed) + 30 s hollow hold.", "Superset, 2 rounds, 2–3 reps left: 6–8 strict pull-ups (band if needed) + 30 s hollow hold."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 3, "versions": ["3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
