insert into public.workout_coach_notes (class_date, body) values ('2026-11-18', 'Stagger the start: give each member a different starting station and have them go in order from there, so only 1–2 people use the sled at a time. Use the sled substitute (plate push or heavy DB walking lunges) when the sled is busy, and the ''No machine free'' swap when rowers or bikes run out.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-19', 'Accessory Strength + Easy Row/Bike Intervals', 'Accessory strength · easy intervals · easy', 'The easy day: strength work for joints and posture, then easy intervals with set work and rest. Nobody should breathe hard today.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 7, "versions": ["General (4 min): 2 min easy row, 10 cat-cows, 10/side couch-stretch rocks.\nSpecific (3 min): 5/side bodyweight step-ups, 10 scap pull-ups, 10 wall slides.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (4 min): 2 min easy row, 10 cat-cows, 10/side couch-stretch rocks.\nSpecific (3 min): 5/side bodyweight step-ups, 10 scap pull-ups, 10 wall slides.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (4 min): 2 min easy row, 10 cat-cows, 10/side couch-stretch rocks.\nSpecific (3 min): 5/side bodyweight step-ups, 10 scap pull-ups, 10 wall slides.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (4 min): 2 min easy row, 10 cat-cows, 10/side couch-stretch rocks.\nSpecific (3 min): 5/side bodyweight step-ups, 10 scap pull-ups, 10 wall slides.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "skill", "label": "Accessory", "title": "Accessory strength + core", "minutes": 21, "versions": ["3 rounds, 3–4 reps left on every set (1:00 rest after each round):\nA1) 6/side bodyweight step-ups to a low step, holding the rig\nA2) 8 ring rows on a high bar, body nearly upright\nA3) 15 s/side side plank from the knees + 10 seated tibialis raises", "3 rounds, 2–3 reps left on every set (1:00 rest after each round):\nA1) 8/side bodyweight step-ups to a low box\nA2) 10 ring rows with your body more upright\nA3) 20 s/side side plank from the knees + 15 tibialis raises", "3 rounds, 2–3 reps left on every set (1:00 rest after each round):\nA1) 8/side dumbbell step-ups to a knee-height box\nA2) 10 ring rows\nA3) 20 s/side short-lever Copenhagen plank + 15 tibialis raises", "3 rounds, 2–3 reps left on every set (1:00 rest after each round):\nA1) 8/side dumbbell step-ups to a knee-height box\nA2) 10 ring rows\nA3) 20 s/side short-lever Copenhagen plank + 15 tibialis raises"]}, {"kind": "conditioning", "label": "Easy intervals", "title": "Easy row/bike intervals", "minutes": 21, "versions": ["2 × 9:00 easy / 1:00 rest (19:00), alternating row and air bike each round.\nEffort: RPE 3–4 (very easy). Air bike or row; each round can be 1:00–2:00 shorter, and slow pedalling is fine.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: marching on the spot, step-ups to a low step, wall push-ups; repeat until the work time ends.\nCap 19:00 (fixed) · Aim: same easy pace every round; you could keep going · Feel: cardio (easy) · Pace: sustain", "2 × 9:00 easy / 1:00 rest (19:00), alternating row and air bike each round.\nEffort: RPE 4 (easy, chatty). Air bike or row. Rounds can be 1:00 shorter.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: step-ups to a low box, jumping jacks, air squats; repeat until the work time ends.\nCap 19:00 (fixed) · Aim: same pace every round: row split 0:15–0:25 per 500 m slower than your 1 km test split; bike, same calories each round (±1) · Feel: cardio (easy) · Pace: sustain", "2 × 9:00 easy / 1:00 rest (19:00), alternating row and air bike each round.\nEffort: RPE 4–5. Row or air bike.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: step-ups, jumping jacks, air squats, easy single-unders; repeat until the work time ends.\nCap 19:00 (fixed) · Aim: same pace every round: row split 0:15–0:25 per 500 m slower than your 1 km test split; bike, same calories each round (±1) · Feel: cardio (easy) · Pace: sustain", "2 × 9:00 easy / 1:00 rest (19:00), alternating row and air bike each round.\nEffort: RPE 5. Row or air bike.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: step-ups, jumping jacks, air squats, easy single-unders; repeat until the work time ends.\nCap 19:00 (fixed) · Aim: same pace every round: row split 0:15–0:25 per 500 m slower than your 1 km test split; bike, same calories each round (±1) · Feel: cardio (easy) · Pace: sustain"]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + mobility", "minutes": 8, "versions": ["3 min easy row; pigeon stretch 1 min/side; shoulder stretch on a bench 1 min; 1 min dead hang.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; shoulder stretch on a bench 1 min; 1 min dead hang.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; shoulder stretch on a bench 1 min; 1 min dead hang.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; shoulder stretch on a bench 1 min; 1 min dead hang.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
on conflict (class_date) do update set title = excluded.title, focus = excluded.focus, why = excluded.why, parts = excluded.parts, status = excluded.status, updated_at = now();
insert into public.workout_coach_notes (class_date, body) values ('2026-11-19', 'If there aren''t enough rowers and bikes, run the class in two waves: wave 1 does the intervals while wave 2 does the accessory strength, then swap at about minute 31; or send the overflow to the ''No machine free'' bodyweight rounds. The intervals have no outside version on purpose: Thursday is machine-only so weekly running volume stays as planned.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-20', 'Power Clean + Press 5×3 + 3 Rounds', 'Clean + press · short workout · hard', 'Heavier power cleans, heavier press triples, then a short sprint with a light-moderate dumbbell.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["General (5 min): 300 m easy row, 10 scap push-ups, 10 air squats.\nSpecific (7 min): clean pull from knee × 5, high-hang power clean × 5, front squat × 5 (empty bar); 2 × 8 band presses.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 300 m easy row, 10 scap push-ups, 10 air squats.\nSpecific (7 min): clean pull from knee × 5, high-hang power clean × 5, front squat × 5 (empty bar); 2 × 8 band presses.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 300 m easy row, 10 scap push-ups, 10 air squats.\nSpecific (7 min): clean pull from knee × 5, high-hang power clean × 5, front squat × 5 (empty bar); 2 × 8 band presses.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 300 m easy row, 10 scap push-ups, 10 air squats.\nSpecific (7 min): clean pull from knee × 5, high-hang power clean × 5, front squat × 5 (empty bar); 2 × 8 band presses.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "Power clean technique", "minutes": 8, "versions": ["Dumbbell clean technique, same clock (Every 2): one light dumbbell or kettlebell, hang clean it to your shoulder, then 1–2 goblet squats in place of each front squat.\nHalf the reps is fine. Stay at RPE 5–6; smooth reps only.", "Power clean technique: Every 2:00 × 6: 2 power cleans, build to RPE 8.\nStay light: empty bar or light plates, and catch from the hang (above the knee) if the floor start feels rushed. Every rep fast and crisp; RPE 6 is plenty.", "Power clean technique: Every 2:00 × 6: 2 power cleans, build to RPE 8.\nBuild by feel only: no percentages today. Every rep fast and crisp; stop adding weight when it slows down.", "Power clean technique: Every 2:00 × 6: 2 power cleans, build to RPE 8.\nBuild by feel only: no percentages today. Every rep fast and crisp; stop adding weight when it slows down."]}, {"kind": "strength", "label": "Strength", "title": "Strict press 5×3 @ 77.5%", "minutes": 10, "lift": {"movement": "Strict press", "gentleMovement": "Dumbbell press", "mode": "percent", "sets": 5, "reps": 3, "pct": [null, 77.5, 77.5, 77.5], "note": "Build to the working weight in 2–3 lighter sets; rest 1:30–2:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Seated dumbbell press (light dumbbells, back against a bench): 5 × 3 at RPE 6–7 (3–4 reps left). Rest 1:30–2:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nBetween sets: 10 light dumbbell rear-delt flys.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Strict press: 5 × 3 @ 77.5% of your estimated max (e1RM). Rest 1:30–2:00.\nLoad = e1RM × 0.775, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Strict press: 5 × 3 @ 77.5% of your estimated max (e1RM). Rest 1:30–2:00.\nLoad = e1RM × 0.775, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Strict press: 5 × 3 @ 77.5% of your estimated max (e1RM). Rest 1:30–2:00.\nLoad = e1RM × 0.775, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "conditioning", "label": "Conditioning", "title": "3 Rounds Row/Snatch/Burpee", "minutes": 19, "versions": ["3 rounds for time:\n150 m row\n8 alternating dumbbell hang snatches 10/15 lb\n6 incline step-back burpees (hands on a box)\nShoulder: dumbbell hang clean instead of the snatch.\nNo machine free: 150 m row → 0:40 step-jacks or marching on the spot.\nCap 12:00 · Aim: finish under the cap; rest when you need to · Feel: gas · Pace: reach", "3 rounds for time:\n200 m row\n12 alternating dumbbell snatches 15/20 lb\n9 step-back burpees\nShoulder: dumbbell hang clean instead of the snatch.\nNo machine free: 200 m row → 50 jumping jacks.\nCap 12:00 · Aim: finish under the cap · Feel: gas · Pace: reach", "3 rounds for time:\n250 m row\n12 alternating dumbbell snatches 25/35 lb\n9 bar-facing burpees\nShoulder: dumbbell hang clean instead of the snatch.\nNo machine free: 250 m row → 120 single-unders.\nCap 12:00 · Aim: finish under the cap · Feel: gas · Pace: reach", "3 rounds for time:\n250 m row\n12 alternating dumbbell snatches 35/50 lb\n9 bar-facing burpees\nShoulder: dumbbell hang clean instead of the snatch.\nNo machine free: 250 m row → 120 single-unders.\nCap 12:00 · Aim: 7:00–9:00 · Feel: gas · Pace: reach"]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 8, "versions": ["3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
