insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-23', 'Back Squat Triples to 85% + Bike/Burpee', 'Squat · intervals · hard', 'The heaviest squat triples of the block, then short hard repeats.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["General (5 min): 3 min easy bike, then 2 rounds: 8/side Cossack squats, 10 glute bridges, 10 scap push-ups.\nSpecific (6 min): 2 × 5 pause back squats (empty bar), 3 low box jumps, then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy bike, then 2 rounds: 8/side Cossack squats, 10 glute bridges, 10 scap push-ups.\nSpecific (6 min): 2 × 5 pause back squats (empty bar), 3 low box jumps, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy bike, then 2 rounds: 8/side Cossack squats, 10 glute bridges, 10 scap push-ups.\nSpecific (6 min): 2 × 5 pause back squats (empty bar), 3 low box jumps, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy bike, then 2 rounds: 8/side Cossack squats, 10 glute bridges, 10 scap push-ups.\nSpecific (6 min): 2 × 5 pause back squats (empty bar), 3 low box jumps, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength · ramp", "title": "Back squat 1×3 @ 80%", "minutes": 6, "lift": {"movement": "Back squat", "gentleMovement": "Goblet squat", "mode": "percent", "sets": 1, "reps": 3, "pct": [null, 80, 80, 80], "note": "Ramp: empty bar × 10, 40% × 5, 50% × 3, 60% × 2, then working sets; rest 2:30–3:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Goblet box squat (light kettlebell or dumbbell at your chest, sit to a box at knee height, stand up tall): 1 × 3 at RPE 6–7 (3–4 reps left). These are the lighter ramp sets before today''s top sets. Rest 2:30–3:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Back squat: 1 × 3 @ 80% of your estimated max (e1RM). Rest 2:30–3:00. These are the lighter ramp sets before today''s top sets.\nLoad = e1RM × 0.8, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Back squat: 1 × 3 @ 80% of your estimated max (e1RM). Rest 2:30–3:00. These are the lighter ramp sets before today''s top sets.\nLoad = e1RM × 0.8, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Back squat: 1 × 3 @ 80% of your estimated max (e1RM). Rest 2:30–3:00. These are the lighter ramp sets before today''s top sets.\nLoad = e1RM × 0.8, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "strength", "label": "Strength · top sets", "title": "Back squat 3×3 @ 85%", "minutes": 14, "lift": {"movement": "Back squat", "gentleMovement": "Goblet squat", "mode": "percent", "sets": 3, "reps": 3, "pct": [null, 85, 85, 85], "note": "Ramp: empty bar × 10, 40% × 5, 50% × 3, 60% × 2, then working sets; rest 2:30–3:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Goblet box squat (light kettlebell or dumbbell at your chest, sit to a box at knee height, stand up tall): 3 × 3 at RPE 6–7 (3–4 reps left). Top sets, after the ramp sets. Rest 2:30–3:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Back squat: 3 × 3 @ 85% of your estimated max (e1RM). Rest 2:30–3:00. Top sets, after the ramp sets.\nLoad = e1RM × 0.85, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Back squat: 3 × 3 @ 85% of your estimated max (e1RM). Rest 2:30–3:00. Top sets, after the ramp sets.\nLoad = e1RM × 0.85, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Back squat: 3 × 3 @ 85% of your estimated max (e1RM). Rest 2:30–3:00. Top sets, after the ramp sets.\nLoad = e1RM × 0.85, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Bike/Burpee Rounds", "minutes": 15, "versions": ["3 rounds (12:00):\n1:00 max cal air bike\n1:00 rest\n1:00 max incline step-back burpees (hands on a box)\n1:00 rest\nEffort: RPE 6. Score = total calories + reps.\nKnees or back: step-back burpees.\nNo machine free: 1:00 max cal air bike → 1:00 fast marching or step-jacks (score the reps).\nCap 12:00 (fixed) · Aim: steady effort every round · Feel: gas · Pace: reach", "3 rounds (12:00):\n1:00 max cal air bike\n1:00 rest\n1:00 max step-back burpees\n1:00 rest\nEffort: RPE 7. Score = total calories + reps.\nKnees or back: step-back burpees.\nNo machine free: 1:00 max cal air bike → 1:00 max jumping jacks (score the reps).\nCap 12:00 (fixed) · Aim: steady effort every round · Feel: gas · Pace: reach", "3 rounds (12:00):\n1:00 max cal air bike\n1:00 rest\n1:00 max burpees\n1:00 rest\nEffort: RPE 8. Score = total calories + reps.\nKnees or back: step-back burpees.\nNo machine free: 1:00 max cal air bike → 1:00 max single-unders (score the reps).\nCap 12:00 (fixed) · Aim: steady effort every round · Feel: gas · Pace: reach", "3 rounds (12:00):\n1:00 max cal air bike\n1:00 rest\n1:00 max burpees\n1:00 rest\nEffort: RPE 9. Score = total calories + reps.\nKnees or back: step-back burpees.\nNo machine free: 1:00 max cal air bike → 1:00 max single-unders (score the reps).\nCap 12:00 (fixed) · Aim: 100+ total · Feel: gas · Pace: reach"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory superset", "minutes": 5, "versions": ["Superset, 3 rounds, 3–4 reps left: 6/side bodyweight walking lunges, short steps + 15 s/side side plank from the knees.", "Superset, 3 rounds, 2–3 reps left: 10/side bodyweight walking lunges + 20 s/side side plank from the knees.", "Superset, 3 rounds, 2–3 reps left: 10/side dumbbell walking lunges 15/20 lb + 20 s/side short-lever Copenhagen plank.", "Superset, 3 rounds, 2–3 reps left: 10/side dumbbell walking lunges 15/20 lb + 20 s/side short-lever Copenhagen plank."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
