insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-24', 'T2B Under Fatigue + Aerobic Rounds', 'Toes-to-bar · aerobic rounds · moderate', 'Hold toes-to-bar quality while breathing hard, then steady aerobic rounds.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["General (5 min): 2 min easy jump rope, 200 m jog, high knees and butt kicks.\nSpecific (6 min): 10 scap pull-ups, 2 × 10 hollow-to-arch swings on the bar, 5 kipping knee raises, 2 × 100 m strides.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.", "General (5 min): 2 min easy jump rope, 200 m jog, high knees and butt kicks.\nSpecific (6 min): 10 scap pull-ups, 2 × 10 hollow-to-arch swings on the bar, 5 kipping knee raises, 2 × 100 m strides.", "General (5 min): 2 min easy jump rope, 200 m jog, high knees and butt kicks.\nSpecific (6 min): 10 scap pull-ups, 2 × 10 hollow-to-arch swings on the bar, 5 kipping knee raises, 2 × 100 m strides.", "General (5 min): 2 min easy jump rope, 200 m jog, high knees and butt kicks.\nSpecific (6 min): 10 scap pull-ups, 2 × 10 hollow-to-arch swings on the bar, 5 kipping knee raises, 2 × 100 m strides."]}, {"kind": "skill", "label": "Skill", "title": "Toes-to-bar level 5: under fatigue", "minutes": 13, "versions": ["Toes-to-bar level 5, EMOM 8:\nOdd minutes: 30 s easy row or bike\nEven minutes: 6 lying bent-knee raises\nNo machine free: odd minutes → 30 s marching or step-jacks.", "Toes-to-bar level 5, EMOM 8:\nOdd minutes: 30 s easy row or bike\nEven minutes: 6 hanging knee raises\nNo machine free: odd minutes → 30 s easy jumping jacks.", "Toes-to-bar level 5, EMOM 8:\nOdd minutes: 30 s easy row or bike\nEven minutes: kipping knee raises + toes-to-bar singles\nNo machine free: odd minutes → 30 s easy single-unders or jumping jacks.", "Toes-to-bar level 5, EMOM 8:\nOdd minutes: 30 s easy row or bike\nEven minutes: 4–6 toes-to-bar unbroken\nNo machine free: odd minutes → 30 s easy single-unders or jumping jacks."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Row/Bike Aerobic Rounds", "minutes": 28, "versions": ["3 rounds, not for time, RPE 6 (about 28:00):\n250 m row\n6/8 cal row\n10 crunches\n5/6 cal air bike\nNo machine free: 250 m row → 1:00 step-jacks or marching on the spot; 6/8 cal row → 0:30 step-jacks or marching on the spot; 5/6 cal air bike → 0:20 step-jacks or marching on the spot.\nCap 30:00 · Aim: even pace; you can talk in short sentences · Feel: cardio · Pace: sustain", "3 rounds, not for time, RPE 6 (about 28:00):\n400 m row\n12/15 cal row\n15 sit-ups\n10/12 cal air bike\nNo machine free: 400 m row → 100 jumping jacks; 12/15 cal row → 55 jumping jacks; 10/12 cal air bike → 45 jumping jacks.\nCap 30:00 · Aim: even pace; you can talk in short sentences · Feel: cardio · Pace: sustain", "3 rounds, not for time, RPE 6 (about 28:00):\n500 m row\n12/15 cal row\n15 sit-ups\n10/12 cal air bike\nNo machine free: 500 m row → 250 single-unders; 12/15 cal row → 110 single-unders; 10/12 cal air bike → 90 single-unders.\nCap 30:00 · Aim: even pace; you can talk in short sentences · Feel: cardio · Pace: sustain", "3 rounds, not for time, RPE 6 (about 28:00):\n500 m row\n12/15 cal row\n15 sit-ups\n10/12 cal air bike\nNo machine free: 500 m row → 250 single-unders; 12/15 cal row → 110 single-unders; 10/12 cal air bike → 90 single-unders.\nCap 30:00 · Aim: even pace; you can talk in short sentences · Feel: cardio · Pace: sustain"], "outdoor": {"title": "Run/Row/Bike Aerobic Rounds", "versions": ["3 rounds, not for time, RPE 6 (about 28:00):\n200 m walk/jog\n6/8 cal row\n10 crunches\n5/6 cal air bike\nNo machine free: 6/8 cal row → 150 m walk/jog; 5/6 cal air bike → 100 m walk/jog.\nCap 30:00 · Aim: even run splits; you can talk in short sentences · Feel: cardio · Pace: sustain", "3 rounds, not for time, RPE 6 (about 28:00):\n300 m run/walk\n12/15 cal row\n15 sit-ups\n10/12 cal air bike\nNo machine free: 12/15 cal row → 250 m run; 10/12 cal air bike → 200 m run.\nCap 30:00 · Aim: even run splits; you can talk in short sentences · Feel: cardio · Pace: sustain", "3 rounds, not for time, RPE 6 (about 28:00):\n400 m run\n12/15 cal row\n15 sit-ups\n10/12 cal air bike\nNo machine free: 12/15 cal row → 250 m run; 10/12 cal air bike → 200 m run.\nCap 30:00 · Aim: even run splits; you can talk in short sentences · Feel: cardio · Pace: sustain", "3 rounds, not for time, RPE 6 (about 28:00):\n400 m run\n12/15 cal row\n15 sit-ups\n10/12 cal air bike\nNo machine free: 12/15 cal row → 250 m run; 10/12 cal air bike → 200 m run.\nCap 30:00 · Aim: even run splits; you can talk in short sentences · Feel: cardio · Pace: sustain"]}}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min."]}]'::jsonb, 'published', null)
