insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-25', 'Deadlift Triples to 85% + Station Doubles', 'Deadlift · compromised running · sustain', 'The heaviest deadlift triples, then two stations back to back after each short run: the hardest compromised-running piece of the block.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["General (5 min): 3 min easy row, then 2 rounds: 10 banded hip hinges, 10/side dead bugs, 10 ring rows.\nSpecific (6 min): 5 slow RDLs + 3 deadlifts at 40–50%, then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy row, then 2 rounds: 10 banded hip hinges, 10/side dead bugs, 10 ring rows.\nSpecific (6 min): 5 slow RDLs + 3 deadlifts at 40–50%, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy row, then 2 rounds: 10 banded hip hinges, 10/side dead bugs, 10 ring rows.\nSpecific (6 min): 5 slow RDLs + 3 deadlifts at 40–50%, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 3 min easy row, then 2 rounds: 10 banded hip hinges, 10/side dead bugs, 10 ring rows.\nSpecific (6 min): 5 slow RDLs + 3 deadlifts at 40–50%, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength · ramp", "title": "Deadlift 1×3 @ 80%", "minutes": 5, "lift": {"movement": "Deadlift", "gentleMovement": "Kettlebell deadlift", "mode": "percent", "sets": 1, "reps": 3, "pct": [null, 80, 80, 80], "note": "Ramp: 40% × 5, 50% × 3, 60% × 2; reset every rep, no bouncing; rest 2:30–3:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Kettlebell deadlift (one light kettlebell between your feet; stand it on a low step if the floor is too far): 1 × 3 at RPE 6–7 (3–4 reps left). These are the lighter ramp sets before today''s top sets. Rest 2:30–3:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Deadlift: 1 × 3 @ 80% of your estimated max (e1RM). Rest 2:30–3:00. These are the lighter ramp sets before today''s top sets.\nLoad = e1RM × 0.8, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Deadlift: 1 × 3 @ 80% of your estimated max (e1RM). Rest 2:30–3:00. These are the lighter ramp sets before today''s top sets.\nLoad = e1RM × 0.8, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Deadlift: 1 × 3 @ 80% of your estimated max (e1RM). Rest 2:30–3:00. These are the lighter ramp sets before today''s top sets.\nLoad = e1RM × 0.8, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "strength", "label": "Strength · top sets", "title": "Deadlift 2×3 @ 85%", "minutes": 11, "lift": {"movement": "Deadlift", "gentleMovement": "Kettlebell deadlift", "mode": "percent", "sets": 2, "reps": 3, "pct": [null, 85, 85, 85], "note": "Ramp: 40% × 5, 50% × 3, 60% × 2; reset every rep, no bouncing; rest 2:30–3:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Kettlebell deadlift (one light kettlebell between your feet; stand it on a low step if the floor is too far): 2 × 3 at RPE 6–7 (3–4 reps left). Top sets, after the ramp sets. Rest 2:30–3:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Deadlift: 2 × 3 @ 85% of your estimated max (e1RM). Rest 2:30–3:00. Top sets, after the ramp sets.\nLoad = e1RM × 0.85, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Deadlift: 2 × 3 @ 85% of your estimated max (e1RM). Rest 2:30–3:00. Top sets, after the ramp sets.\nLoad = e1RM × 0.85, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Deadlift: 2 × 3 @ 85% of your estimated max (e1RM). Rest 2:30–3:00. Top sets, after the ramp sets.\nLoad = e1RM × 0.85, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Bike-off-Station Doubles", "minutes": 24, "versions": ["4 rounds for quality, RPE 6. Each round: 5/6 cal air bike, then 2 stations back to back:\nR1: 25 m sled push (empty sled or 1 light plate) + 10 wall balls 4/6 lb to a low target\nR2: 150 m row + 4 incline step-back burpees (hands on a box)\nR3: 50 m farmers carry 2 × 13/18 lb + 10 step-ups to a low step\nR4: 25 m sled pull (empty sled or 1 light plate) + 10 wall balls 4/6 lb to a low target\nStart on the round your coach gives you and go in order from there.\nNo free sled: light plate push on turf, and 2 × 8 ring rows on a high bar for the pull.\nNo machine free: 150 m row → 0:40 step-jacks or marching on the spot; 5/6 cal air bike → 0:20 step-jacks or marching on the spot.\nCap 24:00 · Aim: finish under the cap · Feel: cardio / muscle · Pace: sustain", "4 rounds for quality, RPE 7. Each round: 6/8 cal air bike, then 2 stations back to back:\nR1: 25 m sled push (sled + light plates) + 15 wall balls 6/10 lb\nR2: 200 m row + 6 step-back burpees, each followed by a broad jump\nR3: 50 m farmers carry 2 × 18/26 lb + 16 lunges, sandbag 13/22 lb or none\nR4: 25 m sled pull (sled + light plates) + 15 wall balls 6/10 lb\nStart on the round your coach gives you and go in order from there.\nNo free sled: see the substitutes (plate push on turf, 2 × 10 heavy ring rows for the pull).\nNo machine free: 200 m row → 50 jumping jacks; 6/8 cal air bike → 30 jumping jacks.\nCap 24:00 · Aim: finish under the cap · Feel: cardio / muscle · Pace: sustain", "4 rounds for quality, RPE 7. Each round: 8/10 cal air bike, then 2 stations back to back:\nR1: 25 m sled push (about 25% lighter than Full) + 20 wall balls 6/10 lb\nR2: 250 m row + 6 burpee broad jumps\nR3: 50 m farmers carry 2 × 26/35 lb + 16 sandbag lunges 22/33 lb\nR4: 25 m sled pull (about 25% lighter than Full) + 20 wall balls 6/10 lb\nStart on the round your coach gives you and go in order from there.\nNo free sled: see the substitutes (plate push on turf, 2 × 10 heavy ring rows for the pull).\nNo machine free: 250 m row → 120 single-unders; 8/10 cal air bike → 70 single-unders.\nCap 24:00 · Aim: the last bike as fast as the first · Feel: cardio / muscle · Pace: sustain", "4 rounds for quality, RPE 7. Each round: 8/10 cal air bike, then 2 stations back to back:\nR1: 25 m sled push (heavy, but moving without stopping for 12.5 m) + 20 wall balls 10/14 lb\nR2: 250 m row + 6 burpee broad jumps\nR3: 50 m farmers carry 2 × 35/53 lb + 16 sandbag lunges 22/44 lb\nR4: 25 m sled pull (heavy, but moving without stopping for 12.5 m) + 20 wall balls 10/14 lb\nStart on the round your coach gives you and go in order from there.\nNo free sled: see the substitutes (plate push on turf, 2 × 10 heavy ring rows for the pull).\nNo machine free: 250 m row → 120 single-unders; 8/10 cal air bike → 70 single-unders.\nCap 24:00 · Aim: 16:00–21:00; the last bike as fast as the first · Feel: cardio / muscle · Pace: sustain"], "outdoor": {"title": "Station Doubles off Short Runs", "versions": ["4 rounds for quality, RPE 6. Each round: 100 m walk/jog, then 2 stations back to back:\nR1: 25 m sled push (empty sled or 1 light plate) + 10 wall balls 4/6 lb to a low target\nR2: 150 m row + 4 incline step-back burpees (hands on a box)\nR3: 50 m farmers carry 2 × 13/18 lb + 10 step-ups to a low step\nR4: 25 m sled pull (empty sled or 1 light plate) + 10 wall balls 4/6 lb to a low target\nStart on the round your coach gives you and go in order from there.\nNo free sled: light plate push on turf, and 2 × 8 ring rows on a high bar for the pull.\nNo machine free: 150 m row → 100 m walk/jog.\nCap 24:00 · Aim: finish under the cap · Feel: cardio / muscle · Pace: sustain", "4 rounds for quality, RPE 7. Each round: 150 m run/walk, then 2 stations back to back:\nR1: 25 m sled push (sled + light plates) + 15 wall balls 6/10 lb\nR2: 200 m row + 6 step-back burpees, each followed by a broad jump\nR3: 50 m farmers carry 2 × 18/26 lb + 16 lunges, sandbag 13/22 lb or none\nR4: 25 m sled pull (sled + light plates) + 15 wall balls 6/10 lb\nStart on the round your coach gives you and go in order from there.\nNo free sled: see the substitutes (plate push on turf, 2 × 10 heavy ring rows for the pull).\nNo machine free: 200 m row → 150 m run.\nCap 24:00 · Aim: finish under the cap · Feel: cardio / muscle · Pace: sustain", "4 rounds for quality, RPE 7. Each round: 200 m run, then 2 stations back to back:\nR1: 25 m sled push (about 25% lighter than Full) + 20 wall balls 6/10 lb\nR2: 250 m row + 6 burpee broad jumps\nR3: 50 m farmers carry 2 × 26/35 lb + 16 sandbag lunges 22/33 lb\nR4: 25 m sled pull (about 25% lighter than Full) + 20 wall balls 6/10 lb\nStart on the round your coach gives you and go in order from there.\nNo free sled: see the substitutes (plate push on turf, 2 × 10 heavy ring rows for the pull).\nNo machine free: 250 m row → 200 m run.\nCap 24:00 · Aim: the last run as fast as the first · Feel: cardio / muscle · Pace: sustain", "4 rounds for quality, RPE 7. Each round: 200 m run, then 2 stations back to back:\nR1: 25 m sled push (heavy, but moving without stopping for 12.5 m) + 20 wall balls 10/14 lb\nR2: 250 m row + 6 burpee broad jumps\nR3: 50 m farmers carry 2 × 35/53 lb + 16 sandbag lunges 22/44 lb\nR4: 25 m sled pull (heavy, but moving without stopping for 12.5 m) + 20 wall balls 10/14 lb\nStart on the round your coach gives you and go in order from there.\nNo free sled: see the substitutes (plate push on turf, 2 × 10 heavy ring rows for the pull).\nNo machine free: 250 m row → 200 m run.\nCap 24:00 · Aim: 16:00–21:00; the last run as fast as the first · Feel: cardio / muscle · Pace: sustain"]}}, {"kind": "skill", "label": "Accessory", "title": "Accessory superset", "minutes": 3, "versions": ["Superset, 2 rounds, 3–4 reps left: 6 ring rows on a high bar, body nearly upright + 15 m light sandbag bear-hug carry.", "Superset, 2 rounds, 2–3 reps left: 8 ring rows + 20 m light sandbag bear-hug carry.", "Superset, 2 rounds, 2–3 reps left: 6–8 feet-elevated ring rows + 20 m sandbag bear-hug carry.", "Superset, 2 rounds, 2–3 reps left: 6–8 strict chin-ups + 20 m sandbag bear-hug carry."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 3, "versions": ["3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
