insert into public.workout_coach_notes (class_date, body) values ('2026-11-26', 'If there aren''t enough rowers and bikes, run the class in two waves: wave 1 does the intervals while wave 2 does the accessory strength, then swap at about minute 31; or send the overflow to the ''No machine free'' bodyweight rounds. The intervals have no outside version on purpose: Thursday is machine-only so weekly running volume stays as planned.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-27', 'Clean + Front Squat + Press Triples + 2 Rounds', 'Clean + press · short workout · hard', 'Heavier clean and front squat work, the top press triples of the block, then a mixed sprint to finish.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["General (5 min): 300 m easy row, 10 scap push-ups, 10 air squats.\nSpecific (7 min): clean pull from knee × 5, high-hang power clean × 5, front squat × 5 (empty bar); 2 × 8 band presses.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 300 m easy row, 10 scap push-ups, 10 air squats.\nSpecific (7 min): clean pull from knee × 5, high-hang power clean × 5, front squat × 5 (empty bar); 2 × 8 band presses.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 300 m easy row, 10 scap push-ups, 10 air squats.\nSpecific (7 min): clean pull from knee × 5, high-hang power clean × 5, front squat × 5 (empty bar); 2 × 8 band presses.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 300 m easy row, 10 scap push-ups, 10 air squats.\nSpecific (7 min): clean pull from knee × 5, high-hang power clean × 5, front squat × 5 (empty bar); 2 × 8 band presses.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "Power clean technique", "minutes": 8, "versions": ["Dumbbell clean technique, same clock (Every 2): one light dumbbell or kettlebell, hang clean it to your shoulder, then 1–2 goblet squats in place of each front squat.\nHalf the reps is fine. Stay at RPE 5–6; smooth reps only.", "Power clean technique: Every 2:00 × 5: 1 power clean + 2 front squats, build to RPE 8.\nStay light: empty bar or light plates, and catch from the hang (above the knee) if the floor start feels rushed. Every rep fast and crisp; RPE 6 is plenty.", "Power clean technique: Every 2:00 × 5: 1 power clean + 2 front squats, build to RPE 8.\nBuild by feel only: no percentages today. Every rep fast and crisp; stop adding weight when it slows down.", "Power clean technique: Every 2:00 × 5: 1 power clean + 2 front squats, build to RPE 8.\nBuild by feel only: no percentages today. Every rep fast and crisp; stop adding weight when it slows down."]}, {"kind": "strength", "label": "Strength · ramp", "title": "Strict press 1×3 @ 80%", "minutes": 4, "lift": {"movement": "Strict press", "gentleMovement": "Dumbbell press", "mode": "percent", "sets": 1, "reps": 3, "pct": [null, 80, 80, 80], "note": "Build to the working weight in 2–3 lighter sets; rest 1:30–2:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Seated dumbbell press (light dumbbells, back against a bench): 1 × 3 at RPE 6–7 (3–4 reps left). These are the lighter ramp sets before today''s top sets. Rest 1:30–2:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nBetween sets: 10 light dumbbell rear-delt flys.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Strict press: 1 × 3 @ 80% of your estimated max (e1RM). Rest 1:30–2:00. These are the lighter ramp sets before today''s top sets.\nLoad = e1RM × 0.8, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Strict press: 1 × 3 @ 80% of your estimated max (e1RM). Rest 1:30–2:00. These are the lighter ramp sets before today''s top sets.\nLoad = e1RM × 0.8, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Strict press: 1 × 3 @ 80% of your estimated max (e1RM). Rest 1:30–2:00. These are the lighter ramp sets before today''s top sets.\nLoad = e1RM × 0.8, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "strength", "label": "Strength · top sets", "title": "Strict press 3×3 @ 82.5%", "minutes": 6, "lift": {"movement": "Strict press", "gentleMovement": "Dumbbell press", "mode": "percent", "sets": 3, "reps": 3, "pct": [null, 82.5, 82.5, 82.5], "note": "Build to the working weight in 2–3 lighter sets; rest 1:30–2:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Seated dumbbell press (light dumbbells, back against a bench): 3 × 3 at RPE 6–7 (3–4 reps left). Top sets, after the ramp sets. Rest 1:30–2:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nBetween sets: 10 light dumbbell rear-delt flys.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Strict press: 3 × 3 @ 82.5% of your estimated max (e1RM). Rest 1:30–2:00. Top sets, after the ramp sets.\nLoad = e1RM × 0.825, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Strict press: 3 × 3 @ 82.5% of your estimated max (e1RM). Rest 1:30–2:00. Top sets, after the ramp sets.\nLoad = e1RM × 0.825, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Strict press: 3 × 3 @ 82.5% of your estimated max (e1RM). Rest 1:30–2:00. Top sets, after the ramp sets.\nLoad = e1RM × 0.825, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "conditioning", "label": "Conditioning", "title": "2 Rounds Row/Swing/Push-up/Thruster", "minutes": 19, "versions": ["2 rounds for time:\n250 m row\n12 Russian KB swings to chest height 13/18 lb\n10 wall push-ups\n8 dumbbell thrusters, 2 × 5 lb\nNo machine free: 250 m row → 1:00 step-jacks or marching on the spot.\nCap 14:00 · Aim: finish under the cap · Feel: cardio · Pace: reach", "2 rounds for time:\n400 m row\n20 KB swings 18/26 lb\n15 incline push-ups\n10 dumbbell thrusters, 2 × 10 lb\nNo machine free: 400 m row → 100 jumping jacks.\nCap 14:00 · Aim: finish under the cap · Feel: cardio · Pace: reach", "2 rounds for time:\n500 m row\n20 KB swings 26/35 lb\n15 push-ups\n10 dumbbell thrusters, 2 × 15/20 lb\nNo machine free: 500 m row → 250 single-unders.\nCap 14:00 · Aim: finish under the cap · Feel: cardio · Pace: reach", "2 rounds for time:\n500 m row\n20 KB swings 35/53 lb\n15 push-ups\n10 dumbbell thrusters, 2 × 25/35 lb\nNo machine free: 500 m row → 250 single-unders.\nCap 14:00 · Aim: 9:00–11:00 · Feel: cardio · Pace: reach"], "outdoor": {"title": "2 Rounds Run/Swing/Push-up/Thruster", "versions": ["2 rounds for time:\n200 m walk/jog\n12 Russian KB swings to chest height 13/18 lb\n10 wall push-ups\n8 dumbbell thrusters, 2 × 5 lb\nCap 14:00 · Aim: finish under the cap · Feel: cardio · Pace: reach", "2 rounds for time:\n300 m run\n20 KB swings 18/26 lb\n15 incline push-ups\n10 dumbbell thrusters, 2 × 10 lb\nCap 14:00 · Aim: finish under the cap · Feel: cardio · Pace: reach", "2 rounds for time:\n400 m run\n20 KB swings 26/35 lb\n15 push-ups\n10 dumbbell thrusters, 2 × 15/20 lb\nCap 14:00 · Aim: finish under the cap · Feel: cardio · Pace: reach", "2 rounds for time:\n400 m run\n20 KB swings 35/53 lb\n15 push-ups\n10 dumbbell thrusters, 2 × 25/35 lb\nCap 14:00 · Aim: 9:00–11:00 · Feel: cardio · Pace: reach"]}}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 8, "versions": ["3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
