insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-30', 'Back Squat Primer + Row Sprints', 'Squat primer · row sprints · moderate', 'Two easy triples and one heavy double: feel heavy weight without the fatigue. Short row sprints to stay sharp.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["General (5 min): 400 m easy row or bike, 10 spiderman lunges with reach, 10 PVC pass-throughs.\nSpecific (6 min): 8 tempo goblet squats (3 s down), 3 squat jumps, then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row or bike, 10 spiderman lunges with reach, 10 PVC pass-throughs.\nSpecific (6 min): 8 tempo goblet squats (3 s down), 3 squat jumps, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row or bike, 10 spiderman lunges with reach, 10 PVC pass-throughs.\nSpecific (6 min): 8 tempo goblet squats (3 s down), 3 squat jumps, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row or bike, 10 spiderman lunges with reach, 10 PVC pass-throughs.\nSpecific (6 min): 8 tempo goblet squats (3 s down), 3 squat jumps, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength · ramp", "title": "Back squat 2×3 @ 75%", "minutes": 6, "lift": {"movement": "Back squat", "gentleMovement": "Goblet squat", "mode": "percent", "sets": 2, "reps": 3, "pct": [null, 75, 75, 75], "note": "Ramp: empty bar × 10, 40% × 5, 50% × 3, 60% × 2, then working sets; rest 2:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Goblet box squat (light kettlebell or dumbbell at your chest, sit to a box at knee height, stand up tall): 2 × 3 at RPE 6–7 (3–4 reps left). These are the lighter ramp sets before today''s top sets. Rest 2:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Back squat: 2 × 3 @ 75% of your estimated max (e1RM). Rest 2:00. These are the lighter ramp sets before today''s top sets.\nLoad = e1RM × 0.75, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Back squat: 2 × 3 @ 75% of your estimated max (e1RM). Rest 2:00. These are the lighter ramp sets before today''s top sets.\nLoad = e1RM × 0.75, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Back squat: 2 × 3 @ 75% of your estimated max (e1RM). Rest 2:00. These are the lighter ramp sets before today''s top sets.\nLoad = e1RM × 0.75, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "strength", "label": "Strength · top sets", "title": "Back squat 1×2 @ 85%", "minutes": 14, "lift": {"movement": "Back squat", "gentleMovement": "Goblet squat", "mode": "percent", "sets": 1, "reps": 2, "pct": [null, 85, 85, 85], "note": "Ramp: empty bar × 10, 40% × 5, 50% × 3, 60% × 2, then working sets; rest 2:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Goblet box squat (light kettlebell or dumbbell at your chest, sit to a box at knee height, stand up tall): 1 × 2 at RPE 6–7 (3–4 reps left). Top sets, after the ramp sets. Rest 2:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Back squat: 1 × 2 @ 85% of your estimated max (e1RM). Rest 2:00. Top sets, after the ramp sets.\nLoad = e1RM × 0.85, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Back squat: 1 × 2 @ 85% of your estimated max (e1RM). Rest 2:00. Top sets, after the ramp sets.\nLoad = e1RM × 0.85, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Back squat: 1 × 2 @ 85% of your estimated max (e1RM). Rest 2:00. Top sets, after the ramp sets.\nLoad = e1RM × 0.85, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Row Sprints", "minutes": 15, "versions": ["4 × 0:45 row sprint / 2:15 easy (12:00).\nSprint effort: RPE 7; each sprint can be 0:30. Score = total metres.\nMasters (40+): RPE 8.\nNo machine free: each 0:45 sprint → 0:45 fast marching or step-jacks; 2:15 easy → walk. Score = reps.\nCap 12:00 (fixed) · Aim: steady metres every sprint · Feel: gas · Pace: reach", "4 × 0:45 row sprint / 2:15 easy (12:00).\nSprint effort: RPE 8. Score = total metres.\nMasters (40+): RPE 8.\nNo machine free: each 0:45 sprint → 0:45 fast jumping jacks; 2:15 easy → walk. Score = reps.\nCap 12:00 (fixed) · Aim: steady metres every sprint · Feel: gas · Pace: reach", "4 × 0:45 row sprint / 2:15 easy (12:00).\nSprint effort: RPE 9. Score = total metres.\nMasters (40+): RPE 8.\nNo machine free: each 0:45 sprint → 0:45 fast single-unders or high knees; 2:15 easy → walk. Score = reps.\nCap 12:00 (fixed) · Aim: steady metres every sprint · Feel: gas · Pace: reach", "4 × 0:45 row sprint / 2:15 easy (12:00).\nSprint effort: max effort. Score = total metres.\nMasters (40+): RPE 8.\nNo machine free: each 0:45 sprint → 0:45 max single-unders or high knees; 2:15 easy → walk. Score = reps.\nCap 12:00 (fixed) · Aim: 230–280 m per sprint · Feel: gas · Pace: reach"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory superset", "minutes": 5, "versions": ["Superset, 2 rounds only, 3–4 reps left: 6/side split squats holding the rig, short range + 15 s/side side plank from the knees.", "Superset, 2 rounds only, 3 reps left: 8/side bodyweight split squats (hold the rig) + 20 s/side side plank from the knees.", "Superset, 2 rounds only, 3 reps left: 8/side split squats + 20 s/side side plank.", "Superset, 2 rounds only, 3 reps left: 8/side split squats + 20 s/side side plank."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
