insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-01', 'Light T2B Practice + Easy Aerobic', 'Toes-to-bar practice · easy aerobic · easy', 'Keep the skill ticking over, then easy aerobic work. Leave fresher than you came in.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["General (5 min): 400 m easy row or jog, 10 cat-cows, 10 PVC pass-throughs.\nSpecific (6 min): 20 s hollow hold, 10 arch rocks, 2 × 5 kip swings, 2 × 3 easy T2B or knee raises.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row or jog, 10 cat-cows, 10 PVC pass-throughs.\nSpecific (6 min): 20 s hollow hold, 10 arch rocks, 2 × 5 kip swings, 2 × 3 easy T2B or knee raises.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row or jog, 10 cat-cows, 10 PVC pass-throughs.\nSpecific (6 min): 20 s hollow hold, 10 arch rocks, 2 × 5 kip swings, 2 × 3 easy T2B or knee raises.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row or jog, 10 cat-cows, 10 PVC pass-throughs.\nSpecific (6 min): 20 s hollow hold, 10 arch rocks, 2 × 5 kip swings, 2 × 3 easy T2B or knee raises.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "skill", "label": "Skill", "title": "Toes-to-bar practice", "minutes": 13, "versions": ["Toes-to-bar practice, 8 min, no fatigue:\n3 × (10 s tuck hollow hold + 3 lying bent-knee raises), 1:30 rest.\nStop every set with reps in the tank.", "Toes-to-bar practice, 8 min, no fatigue:\n3 × (3 hanging knee raises + 3 lying leg raises), 1:30 rest.\nStop every set with reps in the tank.", "Toes-to-bar practice, 8 min, no fatigue:\n3 × (3 kip swings + 3 kipping knee raises), 1:30 rest.\nStop every set with reps in the tank.", "Toes-to-bar practice, 8 min, no fatigue:\n3 × (3 kip swings + 3 toes-to-bar), 1:30 rest.\nStop every set with reps in the tank."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Easy Bike/Row/Wall Ball", "minutes": 28, "versions": ["22:00 easy, RPE 5. 2 rounds:\n12/15 cal air bike\n300 m row\n8 light wall balls 4/6 lb\nNo machine free: 300 m row → 1:15 step-jacks or marching on the spot; 12/15 cal air bike → 0:55 step-jacks or marching on the spot.\nCap 22:00 · Aim: no score: keep it conversational · Feel: cardio (easy) · Pace: sustain", "22:00 easy, RPE 5. 2 rounds:\n16/20 cal air bike\n400 m row\n10 light wall balls 6/10 lb\nNo machine free: 400 m row → 100 jumping jacks; 16/20 cal air bike → 70 jumping jacks.\nCap 22:00 · Aim: no score: keep it conversational · Feel: cardio (easy) · Pace: sustain", "22:00 easy, RPE 5. 2 rounds:\n24/30 cal air bike\n400 m row\n10 light wall balls 6/10 lb\nNo machine free: 400 m row → 200 single-unders; 24/30 cal air bike → 220 single-unders.\nCap 22:00 · Aim: no score: keep it conversational · Feel: cardio (easy) · Pace: sustain", "22:00 easy, RPE 5. 2 rounds:\n32/40 cal air bike\n400 m row\n10 light wall balls 10/14 lb\nNo machine free: 400 m row → 200 single-unders; 32/40 cal air bike → 290 single-unders.\nCap 22:00 · Aim: no score: keep it conversational · Feel: cardio (easy) · Pace: sustain"], "outdoor": {"title": "Easy Run/Row/Wall Ball", "versions": ["22:00 easy, RPE 5. 2 rounds:\n300 m walk/jog\n300 m row\n8 light wall balls 4/6 lb\nNo machine free: 300 m row → 250 m walk/jog.\nCap 22:00 · Aim: no score: keep it conversational · Feel: cardio (easy) · Pace: sustain", "22:00 easy, RPE 5. 2 rounds:\n400 m run/walk\n400 m row\n10 light wall balls 6/10 lb\nNo machine free: 400 m row → 300 m run.\nCap 22:00 · Aim: no score: keep it conversational · Feel: cardio (easy) · Pace: sustain", "22:00 easy, RPE 5. 2 rounds:\n600 m run\n400 m row\n10 light wall balls 6/10 lb\nNo machine free: 400 m row → 300 m run.\nCap 22:00 · Aim: no score: keep it conversational · Feel: cardio (easy) · Pace: sustain", "22:00 easy, RPE 5. 2 rounds:\n800 m run\n400 m row\n10 light wall balls 10/14 lb\nNo machine free: 400 m row → 300 m run.\nCap 22:00 · Aim: no score: keep it conversational · Feel: cardio (easy) · Pace: sustain"]}}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min."]}]'::jsonb, 'published', null)
