insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-02', 'Deadlift Primer + Short Station Threshold', 'Deadlift primer · station threshold · sustain', 'Two easy triples and one heavy single, then a short threshold piece on stations.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["General (5 min): 400 m easy row, 10 jumping jacks, 5/side supported hip airplanes.\nSpecific (6 min): 2 × 5 deadlifts building, 5 KB swings, then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row, 10 jumping jacks, 5/side supported hip airplanes.\nSpecific (6 min): 2 × 5 deadlifts building, 5 KB swings, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row, 10 jumping jacks, 5/side supported hip airplanes.\nSpecific (6 min): 2 × 5 deadlifts building, 5 KB swings, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row, 10 jumping jacks, 5/side supported hip airplanes.\nSpecific (6 min): 2 × 5 deadlifts building, 5 KB swings, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength · ramp", "title": "Deadlift 2×3 @ 75%", "minutes": 5, "lift": {"movement": "Deadlift", "gentleMovement": "Kettlebell deadlift", "mode": "percent", "sets": 2, "reps": 3, "pct": [null, 75, 75, 75], "note": "Ramp: 40% × 5, 50% × 3, 60% × 2; reset every rep, no bouncing; rest 2:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Kettlebell deadlift (one light kettlebell between your feet; stand it on a low step if the floor is too far): 2 × 3 at RPE 6–7 (3–4 reps left). These are the lighter ramp sets before today''s top sets. Rest 2:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Deadlift: 2 × 3 @ 75% of your estimated max (e1RM). Rest 2:00. These are the lighter ramp sets before today''s top sets.\nLoad = e1RM × 0.75, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Deadlift: 2 × 3 @ 75% of your estimated max (e1RM). Rest 2:00. These are the lighter ramp sets before today''s top sets.\nLoad = e1RM × 0.75, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Deadlift: 2 × 3 @ 75% of your estimated max (e1RM). Rest 2:00. These are the lighter ramp sets before today''s top sets.\nLoad = e1RM × 0.75, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "strength", "label": "Strength · top sets", "title": "Deadlift 1×1 @ 85%", "minutes": 11, "lift": {"movement": "Deadlift", "gentleMovement": "Kettlebell deadlift", "mode": "percent", "sets": 1, "reps": 1, "pct": [null, 85, 85, 85], "note": "Ramp: 40% × 5, 50% × 3, 60% × 2; reset every rep, no bouncing; rest 2:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Kettlebell deadlift (one light kettlebell between your feet; stand it on a low step if the floor is too far): 1 × 1 at RPE 6–7 (3–4 reps left). Top sets, after the ramp sets. Rest 2:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Deadlift: 1 × 1 @ 85% of your estimated max (e1RM). Rest 2:00. Top sets, after the ramp sets.\nLoad = e1RM × 0.85, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Deadlift: 1 × 1 @ 85% of your estimated max (e1RM). Rest 2:00. Top sets, after the ramp sets.\nLoad = e1RM × 0.85, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Deadlift: 1 × 1 @ 85% of your estimated max (e1RM). Rest 2:00. Top sets, after the ramp sets.\nLoad = e1RM × 0.85, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Short Station Threshold", "minutes": 22, "versions": ["2 × 8:00 AMRAP / 2:00 rest, at threshold effort (about 7/10, RPE 5–6):\n5/6 cal row\n8 wall balls 4/6 lb to a low target\n20 m farmers carry 2 × 13/18 lb\nNo machine free: 5/6 cal row → 0:20 step-jacks or marching on the spot.\nCap 18:00 · Aim: steady; the blocks don''t have to match · Feel: cardio · Pace: sustain", "2 × 8:00 AMRAP / 2:00 rest, at threshold effort (about 7/10, RPE 6–7):\n6/8 cal row\n10 wall balls 6/10 lb\n20 m farmers carry 2 × 18/26 lb\nNo machine free: 6/8 cal row → 30 jumping jacks.\nCap 18:00 · Aim: steady, block 2 = block 1 · Feel: cardio · Pace: sustain", "2 × 8:00 AMRAP / 2:00 rest, at threshold effort (about 7/10, RPE 6–7):\n9/12 cal row\n10 wall balls 6/10 lb\n20 m farmers carry 2 × 26/35 lb\nNo machine free: 9/12 cal row → 80 single-unders.\nCap 18:00 · Aim: block 2 = block 1 (±1 round) · Feel: cardio · Pace: sustain", "2 × 8:00 AMRAP / 2:00 rest, at threshold effort (about 7/10, RPE 6–7):\n9/12 cal row\n10 wall balls 10/14 lb\n20 m farmers carry 2 × 35/53 lb\nNo machine free: 9/12 cal row → 80 single-unders.\nCap 18:00 · Aim: block 2 = block 1 (±1 round) · Feel: cardio · Pace: sustain"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory superset", "minutes": 4, "versions": ["Superset, 2 rounds, 3–4 reps left: 8 light chest-supported dumbbell rows + 15 m/side light kettlebell suitcase carry.", "Superset, 2 rounds, 3 reps left: 10 light dumbbell rows + 20 m/side kettlebell suitcase carry.", "Superset, 2 rounds, 3 reps left: 10 dumbbell rows + 20 m/side heavy kettlebell suitcase carry.", "Superset, 2 rounds, 3 reps left: 10 dumbbell rows + 20 m/side heavy kettlebell suitcase carry."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 4, "versions": ["3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
