insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-03', 'Accessory Strength + Easy Row/Bike Intervals', 'Accessory strength · easy intervals · easy', 'The easy day: strength work for joints and posture, then easy intervals with set work and rest. Nobody should breathe hard today.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 7, "versions": ["General (4 min): 2 min easy bike, 10 deep-squat pries, 10/side ankle rocks.\nSpecific (3 min): 5/side split squats (bodyweight), 10 band face pulls, 20 s hollow hold.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (4 min): 2 min easy bike, 10 deep-squat pries, 10/side ankle rocks.\nSpecific (3 min): 5/side split squats (bodyweight), 10 band face pulls, 20 s hollow hold.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (4 min): 2 min easy bike, 10 deep-squat pries, 10/side ankle rocks.\nSpecific (3 min): 5/side split squats (bodyweight), 10 band face pulls, 20 s hollow hold.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (4 min): 2 min easy bike, 10 deep-squat pries, 10/side ankle rocks.\nSpecific (3 min): 5/side split squats (bodyweight), 10 band face pulls, 20 s hollow hold.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "skill", "label": "Accessory", "title": "Accessory strength + core", "minutes": 21, "versions": ["2 rounds, 3–4 reps left on every set (1:00 rest after each round):\nA1) 8/side split squats holding the rig, short range\nA2) 10 light dumbbell rear-delt flys, chest on an incline bench\nA3) 20 s tuck hollow hold + 20 m/side light suitcase carry", "2 rounds, 3 reps left on every set (1:00 rest after each round):\nA1) 10/side bodyweight split squats (hold the rig if needed)\nA2) 12 light dumbbell rear-delt flys\nA3) 30 s tuck hollow hold + 30 m/side suitcase carry, light", "2 rounds, 3 reps left on every set (1:00 rest after each round):\nA1) 10/side dumbbell split squats\nA2) 12 dumbbell rear-delt flys\nA3) 30 s hollow hold + 30 m/side suitcase carry", "2 rounds, 3 reps left on every set (1:00 rest after each round):\nA1) 10/side dumbbell split squats\nA2) 12 dumbbell rear-delt flys\nA3) 30 s hollow hold + 30 m/side suitcase carry"]}, {"kind": "conditioning", "label": "Easy intervals", "title": "Easy row/bike intervals", "minutes": 21, "versions": ["3 × 4:00 easy / 1:00 rest (14:00), alternating row and air bike each round.\nEffort: RPE 3–4 (very easy). Air bike or row; each round can be 1:00–2:00 shorter, and slow pedalling is fine.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: marching on the spot, step-ups to a low step, wall push-ups; repeat until the work time ends.\nCap 14:00 (fixed) · Aim: same easy pace every round; you could keep going · Feel: cardio (easy) · Pace: sustain", "3 × 4:00 easy / 1:00 rest (14:00), alternating row and air bike each round.\nEffort: RPE 4 (easy, chatty). Air bike or row. Rounds can be 1:00 shorter.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: step-ups to a low box, jumping jacks, air squats; repeat until the work time ends.\nCap 14:00 (fixed) · Aim: same pace every round: row split 0:15–0:25 per 500 m slower than your 1 km test split; bike, same calories each round (±1) · Feel: cardio (easy) · Pace: sustain", "3 × 4:00 easy / 1:00 rest (14:00), alternating row and air bike each round.\nEffort: RPE 4–5. Row or air bike.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: step-ups, jumping jacks, air squats, easy single-unders; repeat until the work time ends.\nCap 14:00 (fixed) · Aim: same pace every round: row split 0:15–0:25 per 500 m slower than your 1 km test split; bike, same calories each round (±1) · Feel: cardio (easy) · Pace: sustain", "3 × 4:00 easy / 1:00 rest (14:00), alternating row and air bike each round.\nEffort: RPE 5. Row or air bike.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: step-ups, jumping jacks, air squats, easy single-unders; repeat until the work time ends.\nCap 14:00 (fixed) · Aim: same pace every round: row split 0:15–0:25 per 500 m slower than your 1 km test split; bike, same calories each round (±1) · Feel: cardio (easy) · Pace: sustain"]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + mobility", "minutes": 8, "versions": ["3 min easy bike; couch stretch 1 min/side; adductor rocks; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; adductor rocks; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; adductor rocks; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; adductor rocks; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
