insert into public.workout_coach_notes (class_date, body) values ('2026-12-03', 'If there aren''t enough rowers and bikes, run the class in two waves: wave 1 does the intervals while wave 2 does the accessory strength, then swap at about minute 31; or send the overflow to the ''No machine free'' bodyweight rounds. The intervals have no outside version on purpose: Thursday is machine-only so weekly running volume stays as planned.')
