insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-04', 'Power Clean + Press Primer + Short Sprint', 'Clean + press primer · short sprint · hard', 'Fast, fresh and short: light cleans, a primer press, then a quick sprint to sharpen up.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["General (5 min): 2 min jump rope, 5 inchworm push-ups, 10 lunges.\nSpecific (7 min): hang power clean × 5, push press × 5, push jerk × 5 (empty bar), then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.", "General (5 min): 2 min jump rope, 5 inchworm push-ups, 10 lunges.\nSpecific (7 min): hang power clean × 5, push press × 5, push jerk × 5 (empty bar), then ramp sets.", "General (5 min): 2 min jump rope, 5 inchworm push-ups, 10 lunges.\nSpecific (7 min): hang power clean × 5, push press × 5, push jerk × 5 (empty bar), then ramp sets.", "General (5 min): 2 min jump rope, 5 inchworm push-ups, 10 lunges.\nSpecific (7 min): hang power clean × 5, push press × 5, push jerk × 5 (empty bar), then ramp sets."]}, {"kind": "strength", "label": "Strength", "title": "Power clean technique", "minutes": 8, "versions": ["Dumbbell clean technique, same clock (EMOM 6): one light dumbbell or kettlebell, hang clean it to your shoulder, then 1–2 goblet squats in place of each front squat.\nHalf the reps is fine. Stay at RPE 5–6; smooth reps only.", "Power clean technique: EMOM 6: 2 power cleans, light and fast (RPE 6).\nStay light: empty bar or light plates, and catch from the hang (above the knee) if the floor start feels rushed. Every rep fast and crisp; RPE 6 is plenty.", "Power clean technique: EMOM 6: 2 power cleans, light and fast (RPE 6).\nBuild by feel only: no percentages today. Every rep fast and crisp; stop adding weight when it slows down.", "Power clean technique: EMOM 6: 2 power cleans, light and fast (RPE 6).\nBuild by feel only: no percentages today. Every rep fast and crisp; stop adding weight when it slows down."]}, {"kind": "strength", "label": "Strength · ramp", "title": "Strict press 2×3 @ 75%", "minutes": 4, "lift": {"movement": "Strict press", "gentleMovement": "Dumbbell press", "mode": "percent", "sets": 2, "reps": 3, "pct": [null, 75, 75, 75], "note": "Build to the working weight in 2–3 lighter sets; rest 1:30–2:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Seated dumbbell press (light dumbbells, back against a bench): 2 × 3 at RPE 6–7 (3–4 reps left). These are the lighter ramp sets before today''s top sets. Rest 1:30–2:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nBetween sets: 10 light dumbbell rear-delt flys.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Strict press: 2 × 3 @ 75% of your estimated max (e1RM). Rest 1:30–2:00. These are the lighter ramp sets before today''s top sets.\nLoad = e1RM × 0.75, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Strict press: 2 × 3 @ 75% of your estimated max (e1RM). Rest 1:30–2:00. These are the lighter ramp sets before today''s top sets.\nLoad = e1RM × 0.75, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Strict press: 2 × 3 @ 75% of your estimated max (e1RM). Rest 1:30–2:00. These are the lighter ramp sets before today''s top sets.\nLoad = e1RM × 0.75, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "strength", "label": "Strength · top sets", "title": "Strict press 1×2 @ 82.5%", "minutes": 6, "lift": {"movement": "Strict press", "gentleMovement": "Dumbbell press", "mode": "percent", "sets": 1, "reps": 2, "pct": [null, 82.5, 82.5, 82.5], "note": "Build to the working weight in 2–3 lighter sets; rest 1:30–2:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%)."}, "versions": ["Seated dumbbell press (light dumbbells, back against a bench): 1 × 2 at RPE 6–7 (3–4 reps left). Top sets, after the ramp sets. Rest 1:30–2:00.\nPick one easy weight and keep it for every set; fewer reps is fine if the last ones slow down.\nBetween sets: 10 light dumbbell rear-delt flys.\nPain or injury: keep the movement pattern in a pain-free range and tell your coach.", "Strict press: 1 × 2 @ 82.5% of your estimated max (e1RM). Rest 1:30–2:00. Top sets, after the ramp sets.\nLoad = e1RM × 0.825, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Strict press: 1 × 2 @ 82.5% of your estimated max (e1RM). Rest 1:30–2:00. Top sets, after the ramp sets.\nLoad = e1RM × 0.825, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling.", "Strict press: 1 × 2 @ 82.5% of your estimated max (e1RM). Rest 1:30–2:00. Top sets, after the ramp sets.\nLoad = e1RM × 0.825, rounded to the nearest 5 lb (lookup table in the coach book).\nStop and drop 5–10% if a set feels harder than RPE 8 (fewer than 2 reps left) or form breaks.\nBetween sets: 10 light dumbbell rear-delt flys.\nMasters (40+): never above 85%; RPE 8 is the ceiling."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Short Bike/T2B/Wall Ball Sprint", "minutes": 19, "versions": ["2 rounds for time:\n5/6 cal air bike\n8 lying bent-knee raises\n10 wall balls 4/6 lb to a low target\nNo machine free: 5/6 cal air bike → 0:20 step-jacks or marching on the spot.\nCap 10:00 · Aim: finish under the cap · Feel: gas · Pace: reach", "2 rounds for time:\n8/10 cal air bike\n12 lying leg raises\n15 wall balls 6/10 lb\nNo machine free: 8/10 cal air bike → 35 jumping jacks.\nCap 10:00 · Aim: finish under the cap · Feel: gas · Pace: reach", "2 rounds for time:\n12/15 cal air bike\n12 hanging knee raises\n15 wall balls 10/14 lb\nNo machine free: 12/15 cal air bike → 110 single-unders.\nCap 10:00 · Aim: finish under the cap · Feel: gas · Pace: reach", "2 rounds for time:\n12/15 cal air bike\n12 toes-to-bar\n15 wall balls 14/20 lb\nNo machine free: 12/15 cal air bike → 110 single-unders.\nCap 10:00 · Aim: 5:00–7:00 · Feel: gas · Pace: reach"]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 8, "versions": ["3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
