insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-07', 'RETEST: 3RM Back Squat + Bike Intervals', 'Squat retest · bike intervals · hard', 'Same squat test as Week 1, so you can see how far you''ve come. Short, fast bike intervals after to open up the lungs.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["General (5 min): 400 m easy row or bike, 10 spiderman lunges with reach, 10 PVC pass-throughs.\nSpecific (6 min): 8 tempo goblet squats (3 s down), 3 squat jumps, then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row or bike, 10 spiderman lunges with reach, 10 PVC pass-throughs.\nSpecific (6 min): 8 tempo goblet squats (3 s down), 3 squat jumps, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row or bike, 10 spiderman lunges with reach, 10 PVC pass-throughs.\nSpecific (6 min): 8 tempo goblet squats (3 s down), 3 squat jumps, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row or bike, 10 spiderman lunges with reach, 10 PVC pass-throughs.\nSpecific (6 min): 8 tempo goblet squats (3 s down), 3 squat jumps, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "RETEST: 3RM back squat", "minutes": 20, "lift": {"movement": "Back squat", "gentleMovement": "Goblet squat", "mode": "build", "sets": 1, "reps": 3, "pct": [null, null, null, null], "note": "Follow the ladder; no RPE 9–10 grinders. Week 1 3RM × 1.06 = e1RM for every squat % this block."}, "versions": ["RETEST: build to a 3RM goblet squat in 18 min (one dumbbell or kettlebell at your chest; sit to a box if you need a depth guide).\nLadder: light × 8, then 3 sets of 3 getting heavier, then 2–4 attempts at 3 reps, stopping at RPE 8 (2 reps left).\nThe last clean set = your 3RM.\nUse your Week 1 result as your second-to-last attempt.\nRecord: your 3RM goblet squat load in lb, the level you did, and the change from Week 1.", "RETEST: build to a 3RM back squat in 18 min.\nLadder: bar × 8, ~50% × 5, ~65% × 3, ~75% × 3, then 2–4 attempts at 3 reps, adding 5–10 lb each time.\nYour coach calls the set if depth or position breaks. The last clean set = your 3RM.\nStart with the empty bar (or a lighter training bar). First 4 weeks after on-ramp: no max attempt; stop at your first RPE 8 set and record that.\nUse your Week 1 result as your second-to-last attempt.\nRecord: your 3RM load in lb, the level you did, and the change from Week 1.", "RETEST: build to a 3RM back squat in 18 min.\nLadder: bar × 8, ~50% × 5, ~65% × 3, ~75% × 3, then 2–4 attempts at 3 reps, adding 5–15 lb each time.\nYour coach calls the set if depth or position breaks. The last clean set = your 3RM.\nUse your Week 1 result as your second-to-last attempt.\nRecord: your 3RM load in lb, the level you did, and the change from Week 1.", "RETEST: build to a 3RM back squat in 18 min.\nLadder: bar × 8, ~50% × 5, ~65% × 3, ~75% × 3, then 2–4 attempts at 3 reps, adding 5–20 lb each time.\nYour coach calls the set if depth or position breaks. The last clean set = your 3RM.\nUse your Week 1 result as your second-to-last attempt.\nRecord: your 3RM load in lb, the level you did, and the change from Week 1."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Bike intervals", "minutes": 13, "versions": ["6 rounds: 0:30 hard / 1:30 easy (12:00).\nMachine: air bike or rower, whichever feels easier. Hard = RPE 6, smooth (hard pieces can be 0:20 if you need). Use the same machine for all 6 rounds and the same machine as Week 1.\nMasters (40+): RPE 8 at most on the hard pieces. Knee or back pain: air bike only.\nNo machine free: 0:30 hard = fast marching or step-jacks; 1:30 easy = slow walk. Score = reps instead of calories.\nCap 12:00 (fixed) · Aim: beat your Week 1 average calories per hard piece · Feel: gas · Pace: reach", "6 rounds: 0:30 hard / 1:30 easy (12:00).\nMachine: any machine (air bike, rower). Hard = RPE 7, smooth. Use the same machine for all 6 rounds and the same machine as Week 1.\nMasters (40+): RPE 8 at most on the hard pieces. Knee or back pain: air bike only.\nNo machine free: 0:30 hard = jumping jacks, fast but smooth; 1:30 easy = walk. Score = reps instead of calories.\nCap 12:00 (fixed) · Aim: beat your Week 1 average calories per hard piece · Feel: gas · Pace: reach", "6 rounds: 0:30 hard / 1:30 easy (12:00).\nMachine: rower. Hard = RPE 8. Use the same machine for all 6 rounds and the same machine as Week 1.\nMasters (40+): RPE 8 at most on the hard pieces. Knee or back pain: air bike only.\nNo machine free: 0:30 hard = fast single-unders or high knees; 1:30 easy = walk. Score = reps instead of calories.\nCap 12:00 (fixed) · Aim: beat your Week 1 average calories per hard piece · Feel: gas · Pace: reach", "6 rounds: 0:30 hard / 1:30 easy (12:00).\nMachine: air bike. Hard = RPE 9. Use the same machine for all 6 rounds and the same machine as Week 1.\nMasters (40+): RPE 8 at most on the hard pieces. Knee or back pain: air bike only.\nNo machine free: 0:30 hard = max-effort single-unders or high knees; 1:30 easy = walk. Score = reps instead of calories.\nCap 12:00 (fixed) · Aim: beat your Week 1 average calories per hard piece · Feel: gas · Pace: reach"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory superset", "minutes": 5, "versions": ["Superset, 2 rounds, 3–4 reps left: 6/side split squats holding the rig, short range + 15 s/side side plank from the knees.", "Superset, 2 rounds, 3 reps left: 10/side bodyweight split squats (hold the rig if needed) + 30 s/side side plank from the knees.", "Superset, 2 rounds, 3 reps left: 10/side light dumbbell split squats + 30 s/side side plank.", "Superset, 2 rounds, 3 reps left: 10/side light dumbbell split squats + 30 s/side side plank."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + log", "minutes": 7, "versions": ["3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads. Write your 3RM on your scorecard.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads. Write your 3RM on your scorecard.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads. Write your 3RM on your scorecard.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads. Write your 3RM on your scorecard.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
on conflict (class_date) do update set title = excluded.title, focus = excluded.focus, why = excluded.why, parts = excluded.parts, status = excluded.status, updated_at = now();
insert into public.workout_coach_notes (class_date, body) values ('2026-12-07', 'Two coaches on test days if possible. Watch depth and back position; you call the set. Steady, Strong and Full all test the barbell back squat (smaller jumps at Steady); only Gentle tests the goblet squat. Machine-only intervals: Monday has no running on purpose (heavy-leg day), so there is no outside version.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-08', 'RETEST: 1 km Run Time Trial + T2B Maintenance', '1 km retest · toes-to-bar · hard', 'Same 1 km test as Week 1: compare your time. Toes-to-bar work stays light today.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["General (5 min): 400 m easy row or jog, 10 cat-cows, 10 PVC pass-throughs.\nSpecific (6 min): 20 s hollow hold, 10 arch rocks, 2 × 5 kip swings, 2 × 3 easy T2B or knee raises.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row or jog, 10 cat-cows, 10 PVC pass-throughs.\nSpecific (6 min): 20 s hollow hold, 10 arch rocks, 2 × 5 kip swings, 2 × 3 easy T2B or knee raises.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row or jog, 10 cat-cows, 10 PVC pass-throughs.\nSpecific (6 min): 20 s hollow hold, 10 arch rocks, 2 × 5 kip swings, 2 × 3 easy T2B or knee raises.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row or jog, 10 cat-cows, 10 PVC pass-throughs.\nSpecific (6 min): 20 s hollow hold, 10 arch rocks, 2 × 5 kip swings, 2 × 3 easy T2B or knee raises.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "skill", "label": "Skill", "title": "Toes-to-bar maintenance", "minutes": 13, "versions": ["Toes-to-bar maintenance, every 2:00 × 4 (not a test; the retest is Week 9):\n5 lying bent-knee raises + 10 s tuck hollow hold", "Toes-to-bar maintenance, every 2:00 × 4 (not a test; the retest is Week 9):\n5 hanging knee raises", "Toes-to-bar maintenance, every 2:00 × 4 (not a test; the retest is Week 9):\n2 kip swings + 3–5 kipping knee raises", "Toes-to-bar maintenance, every 2:00 × 4 (not a test; the retest is Week 9):\n2 kip swings + 3–5 toes-to-bar"]}, {"kind": "conditioning", "label": "Retest", "title": "1,000 m row time trial", "minutes": 15, "versions": ["RETEST: 1,000 m row time trial.\n1,000 m row, steady and comfortable-hard; a short pause at 500 m is fine (note it).\nUse the same machine as Week 1.\nRest 8–10 min after: walk and drink water.\nNo machine free: do the test on the next free rower, or as the 1 km run outside if it is safe; a bodyweight swap can''t be compared with Week 8.\nCap 15:00 · Aim: beat your Week 1 time on the same machine · Feel: cardio · Pace: reach\nRecord: time, level, and whether you ran or rowed.", "RETEST: 1,000 m row time trial.\n1,000 m row, as fast as you can hold for the whole 1,000 m.\nUse the same machine as Week 1.\nRest 8–10 min after: walk and drink water.\nNo machine free: do the test on the next free rower, or as the 1 km run outside if it is safe; a bodyweight swap can''t be compared with Week 8.\nCap 15:00 · Aim: beat your Week 1 time on the same machine · Feel: cardio · Pace: reach\nRecord: time, level, and whether you ran or rowed.", "RETEST: 1,000 m row time trial.\n1,000 m row, even pace.\nUse the same machine as Week 1.\nRest 8–10 min after: walk and drink water.\nNo machine free: do the test on the next free rower, or as the 1 km run outside if it is safe; a bodyweight swap can''t be compared with Week 8.\nCap 15:00 · Aim: beat your Week 1 time on the same machine · Feel: cardio · Pace: reach\nRecord: time, level, and whether you ran or rowed.", "RETEST: 1,000 m row time trial.\n1,000 m row, hard but even: the same split every 250 m.\nUse the same machine as Week 1.\nRest 8–10 min after: walk and drink water.\nNo machine free: do the test on the next free rower, or as the 1 km run outside if it is safe; a bodyweight swap can''t be compared with Week 8.\nCap 15:00 · Aim: beat your Week 1 time on the same machine · Feel: cardio · Pace: reach\nRecord: time, level, and whether you ran or rowed."], "outdoor": {"title": "1 km run time trial", "versions": ["RETEST: 1 km run time trial.\n1 km walk/jog: jog 1:00, walk 1:00, repeat (or brisk walk the whole way). Keep the same plan in Week 8.\nUse the same route as Week 1.\nRest 8–10 min after: walk and drink water.\nCap 15:00 · Aim: beat your Week 1 time on the same route · Feel: cardio · Pace: reach\nRecord: time, level, and whether you ran or rowed.", "RETEST: 1 km run time trial.\n1 km run/walk, as fast as you can hold for the whole 1 km.\nUse the same route as Week 1.\nRest 8–10 min after: walk and drink water.\nCap 15:00 · Aim: beat your Week 1 time on the same route · Feel: cardio · Pace: reach\nRecord: time, level, and whether you ran or rowed.", "RETEST: 1 km run time trial.\n1 km run, even pace.\nUse the same route as Week 1.\nRest 8–10 min after: walk and drink water.\nCap 15:00 · Aim: beat your Week 1 time on the same route · Feel: cardio · Pace: reach\nRecord: time, level, and whether you ran or rowed.", "RETEST: 1 km run time trial.\n1 km run, hard but even: the same pace every 200 m.\nUse the same route as Week 1.\nRest 8–10 min after: walk and drink water.\nCap 15:00 · Aim: beat your Week 1 time on the same route · Feel: cardio · Pace: reach\nRecord: time, level, and whether you ran or rowed."]}}, {"kind": "conditioning", "label": "Conditioning", "title": "Easy jump rope flush", "minutes": 13, "versions": ["12:00 easy, RPE 4, 3 rounds, not for time:\n1:00 step-jacks or marching on the spot\n8 incline push-ups (hands on a box or the wall)\n8 air squats to a box\nYou should be able to talk the whole time.\nCap 12:00 · Aim: smooth and easy · Feel: cardio (easy) · Pace: sustain", "12:00 easy, RPE 5, 3 rounds, not for time:\n1:00 easy jumping jacks or single-unders\n8 incline push-ups (hands on a box)\n12 air squats\nYou should be able to talk the whole time.\nCap 12:00 · Aim: smooth and easy · Feel: cardio (easy) · Pace: sustain", "12:00 easy, RPE 5, 3 rounds, not for time:\n1:30 easy single-unders (break whenever you like)\n10 push-ups (knees if needed)\n15 air squats\nYou should be able to talk the whole time.\nCap 12:00 · Aim: smooth and easy · Feel: cardio (easy) · Pace: sustain", "12:00 easy, RPE 5, 3 rounds, not for time:\n1:30 easy single-unders (break whenever you like)\n10 push-ups\n15 air squats\nYou should be able to talk the whole time.\nCap 12:00 · Aim: smooth and easy · Feel: cardio (easy) · Pace: sustain"], "outdoor": {"title": "Easy run flush", "versions": ["12:00 easy, RPE 4, 3 rounds, not for time:\n300 m walk/jog\n8 incline push-ups (hands on a box or the wall)\n8 air squats to a box\nYou should be able to talk the whole time.\nCap 12:00 · Aim: smooth and easy · Feel: cardio (easy) · Pace: sustain", "12:00 easy, RPE 5, 3 rounds, not for time:\n400 m easy run/walk\n8 incline push-ups (hands on a box)\n12 air squats\nYou should be able to talk the whole time.\nCap 12:00 · Aim: smooth and easy · Feel: cardio (easy) · Pace: sustain", "12:00 easy, RPE 5, 3 rounds, not for time:\n400 m easy run\n10 push-ups (knees if needed)\n15 air squats\nYou should be able to talk the whole time.\nCap 12:00 · Aim: smooth and easy · Feel: cardio (easy) · Pace: sustain", "12:00 easy, RPE 5, 3 rounds, not for time:\n400 m easy run\n10 push-ups\n15 air squats\nYou should be able to talk the whole time.\nCap 12:00 · Aim: smooth and easy · Feel: cardio (easy) · Pace: sustain"]}}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min."]}]'::jsonb, 'published', null)
on conflict (class_date) do update set title = excluded.title, focus = excluded.focus, why = excluded.why, parts = excluded.parts, status = excluded.status, updated_at = now();
insert into public.workout_coach_notes (class_date, body) values ('2026-12-08', 'Start the 1 km in waves of 4–6 and read times out as they finish; if rowers run out inside, the next wave rows when a machine frees up (don''t swap the test). Members choose run or row once and repeat the same option in Week 8. The easy flush after the test needs no machines inside (jump ropes, floor space), so finished waves start it while the next wave rows. Record each member''s Week 1 vs Week 8 time on their scorecard.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-09', 'RETEST: 3RM Deadlift + Easy Bike EMOM', 'Deadlift retest · easy bike EMOM', 'Deadlift retest: compare with Week 1. Then an easy air bike EMOM to move and breathe: no hinging, nothing like yesterday (no run test today).', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["General (5 min): 400 m easy row, 10 jumping jacks, 5/side supported hip airplanes.\nSpecific (6 min): 2 × 5 deadlifts building, 5 KB swings, then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row, 10 jumping jacks, 5/side supported hip airplanes.\nSpecific (6 min): 2 × 5 deadlifts building, 5 KB swings, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row, 10 jumping jacks, 5/side supported hip airplanes.\nSpecific (6 min): 2 × 5 deadlifts building, 5 KB swings, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row, 10 jumping jacks, 5/side supported hip airplanes.\nSpecific (6 min): 2 × 5 deadlifts building, 5 KB swings, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "RETEST: 3RM deadlift", "minutes": 18, "lift": {"movement": "Deadlift", "gentleMovement": "Kettlebell deadlift", "mode": "build", "sets": 1, "reps": 3, "pct": [null, null, null, null], "note": "Follow the ladder; reset every rep. Week 1 3RM × 1.06 = e1RM for every deadlift % this block."}, "versions": ["RETEST: build to a 3RM kettlebell deadlift in 16 min (bell between your feet, on a low step if the floor is too far).\nLadder: light × 5, then 3 sets of 3 getting heavier, then 2–4 attempts at 3 reps, stopping at RPE 8. Reset each rep.\nThe last clean set = your 3RM.\nUse your Week 1 result as your second-to-last attempt.\nRecord: your 3RM kettlebell deadlift load in lb, the level you did, and the change from Week 1.", "RETEST: build to a 3RM deadlift in 16 min.\nLadder: 40% × 5, 55% × 3, 65% × 3, 75% × 3, then 2–4 attempts at 3 reps, adding 5–15 lb each time.\nNo touch-and-go: reset each rep. Your coach stops the set if your back rounds. The last clean set = your 3RM.\nStart light (bar plus small plates on blocks if needed). First 4 weeks after on-ramp: no max attempt; stop at your first RPE 8 set and record that.\nUse your Week 1 result as your second-to-last attempt.\nRecord: your 3RM load in lb, the level you did, and the change from Week 1.", "RETEST: build to a 3RM deadlift in 16 min.\nLadder: 40% × 5, 55% × 3, 65% × 3, 75% × 3, then 2–4 attempts at 3 reps, adding 10–20 lb each time.\nNo touch-and-go: reset each rep. Your coach stops the set if your back rounds. The last clean set = your 3RM.\nUse your Week 1 result as your second-to-last attempt.\nRecord: your 3RM load in lb, the level you did, and the change from Week 1.", "RETEST: build to a 3RM deadlift in 16 min.\nLadder: 40% × 5, 55% × 3, 65% × 3, 75% × 3, then 2–4 attempts at 3 reps, adding 10–30 lb each time.\nNo touch-and-go: reset each rep. Your coach stops the set if your back rounds. The last clean set = your 3RM.\nUse your Week 1 result as your second-to-last attempt.\nRecord: your 3RM load in lb, the level you did, and the change from Week 1."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Easy bike EMOM", "minutes": 14, "versions": ["EMOM 12 (3 rounds), not for score, RPE 4–5:\nMinute 1: 0:30 very easy air bike\nMinute 2: 6/side reverse lunges holding the rig (or step-backs)\nMinute 3: 0:30 very easy air bike\nMinute 4: 10 m hands-and-knees crawl + 8 two-leg glute bridges\nSore low back after the test: keep the bike very easy and skip the bear crawl (glute bridges only).\nNo machine free: each 0:30 air bike minute → 0:30 easy step-jacks or marching on the spot.\nCap 12:00 (fixed) · Aim: smooth and easy; breathing stays calm · Feel: cardio (easy) · Pace: sustain", "EMOM 12 (3 rounds), not for score, RPE 5–6:\nMinute 1: 0:40 easy air bike\nMinute 2: 8/side bodyweight reverse lunges\nMinute 3: 0:40 easy air bike\nMinute 4: 15 m bear crawl + 10 glute bridges\nSore low back after the test: keep the bike very easy and skip the bear crawl (glute bridges only).\nNo machine free: each 0:40 air bike minute → 0:40 easy jumping jacks.\nCap 12:00 (fixed) · Aim: smooth and easy; breathing stays calm · Feel: cardio (easy) · Pace: sustain", "EMOM 12 (3 rounds), not for score, RPE 5–6:\nMinute 1: 0:40 easy air bike\nMinute 2: 8/side bodyweight reverse lunges\nMinute 3: 0:40 easy air bike\nMinute 4: 20 m bear crawl + 10 glute bridges\nSore low back after the test: keep the bike very easy and skip the bear crawl (glute bridges only).\nNo machine free: each 0:40 air bike minute → 0:40 easy single-unders.\nCap 12:00 (fixed) · Aim: smooth and easy; breathing stays calm · Feel: cardio (easy) · Pace: sustain", "EMOM 12 (3 rounds), not for score, RPE 5–6:\nMinute 1: 0:40 easy air bike\nMinute 2: 10/side bodyweight reverse lunges\nMinute 3: 0:40 easy air bike\nMinute 4: 20 m bear crawl + 12 glute bridges\nSore low back after the test: keep the bike very easy and skip the bear crawl (glute bridges only).\nNo machine free: each 0:40 air bike minute → 0:40 easy single-unders.\nCap 12:00 (fixed) · Aim: smooth and easy; breathing stays calm · Feel: cardio (easy) · Pace: sustain"], "outdoor": {"title": "Easy jog EMOM", "versions": ["EMOM 12 (3 rounds), not for score, RPE 4–5:\nMinute 1: 100 m walk/jog, walk the rest of the minute\nMinute 2: 6/side reverse lunges holding the rig (or step-backs)\nMinute 3: 100 m walk/jog, walk the rest of the minute\nMinute 4: 10 m hands-and-knees crawl + 8 two-leg glute bridges\nSore low back after the test: walk the jog minutes and skip the bear crawl (glute bridges only).\nCap 12:00 (fixed) · Aim: smooth and easy; breathing stays calm · Feel: cardio (easy) · Pace: sustain", "EMOM 12 (3 rounds), not for score, RPE 5–6:\nMinute 1: 100 m easy jog/walk, walk the rest of the minute\nMinute 2: 8/side bodyweight reverse lunges\nMinute 3: 100 m easy jog/walk, walk the rest of the minute\nMinute 4: 15 m bear crawl + 10 glute bridges\nSore low back after the test: walk the jog minutes and skip the bear crawl (glute bridges only).\nCap 12:00 (fixed) · Aim: smooth and easy; breathing stays calm · Feel: cardio (easy) · Pace: sustain", "EMOM 12 (3 rounds), not for score, RPE 5–6:\nMinute 1: 100 m easy jog, walk the rest of the minute\nMinute 2: 8/side bodyweight reverse lunges\nMinute 3: 100 m easy jog, walk the rest of the minute\nMinute 4: 20 m bear crawl + 10 glute bridges\nSore low back after the test: walk the jog minutes and skip the bear crawl (glute bridges only).\nCap 12:00 (fixed) · Aim: smooth and easy; breathing stays calm · Feel: cardio (easy) · Pace: sustain", "EMOM 12 (3 rounds), not for score, RPE 5–6:\nMinute 1: 100 m easy jog, walk the rest of the minute\nMinute 2: 10/side bodyweight reverse lunges\nMinute 3: 100 m easy jog, walk the rest of the minute\nMinute 4: 20 m bear crawl + 12 glute bridges\nSore low back after the test: walk the jog minutes and skip the bear crawl (glute bridges only).\nCap 12:00 (fixed) · Aim: smooth and easy; breathing stays calm · Feel: cardio (easy) · Pace: sustain"]}}, {"kind": "skill", "label": "Accessory", "title": "Core", "minutes": 6, "versions": ["Core, 2 rounds: 6/side dead bugs, arms only + 15 s/side side plank from the knees.", "Core, 2 rounds: 10/side dead bugs + 20 s/side side plank from the knees.", "Core, 2 rounds: 10/side dead bugs + 20 s/side side plank.", "Core, 2 rounds: 10/side dead bugs + 20 s/side side plank."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + log", "minutes": 8, "versions": ["3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s. Write your 3RM on your scorecard.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s. Write your 3RM on your scorecard.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s. Write your 3RM on your scorecard.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s. Write your 3RM on your scorecard.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
