insert into public.workout_coach_notes (class_date, body) values ('2026-12-10', 'If there aren''t enough rowers and bikes, run the class in two waves: wave 1 does the intervals while wave 2 does the accessory strength, then swap at about minute 31; or send the overflow to the ''No machine free'' bodyweight rounds. The intervals have no outside version on purpose: Thursday is machine-only so weekly running volume stays as planned.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-11', 'RETEST: 5RM Strict Press + Station AMRAP', 'Press retest · stations · moderate', 'Press retest, then the Week 1 station piece again: compare both. The station piece is steady, not a max effort.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["General (5 min): 2 min jump rope, 5 inchworm push-ups, 10 lunges.\nSpecific (7 min): hang power clean × 5, push press × 5, push jerk × 5 (empty bar), then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.", "General (5 min): 2 min jump rope, 5 inchworm push-ups, 10 lunges.\nSpecific (7 min): hang power clean × 5, push press × 5, push jerk × 5 (empty bar), then ramp sets.", "General (5 min): 2 min jump rope, 5 inchworm push-ups, 10 lunges.\nSpecific (7 min): hang power clean × 5, push press × 5, push jerk × 5 (empty bar), then ramp sets.", "General (5 min): 2 min jump rope, 5 inchworm push-ups, 10 lunges.\nSpecific (7 min): hang power clean × 5, push press × 5, push jerk × 5 (empty bar), then ramp sets."]}, {"kind": "strength", "label": "Strength", "title": "RETEST: 5RM strict press", "minutes": 17, "lift": {"movement": "Strict press", "gentleMovement": "Dumbbell press", "mode": "build", "sets": 1, "reps": 5, "pct": [null, null, null, null], "note": "Follow the ladder; no leg drive. Week 1 5RM × 1.13 = e1RM for every press % this block."}, "versions": ["RETEST: build to a 5RM seated dumbbell press in 15 min (back against a bench; record the weight per hand).\nLadder: light × 10, then 2 sets of 5 getting heavier, then 2–4 attempts at 5 reps, stopping at RPE 8.\nThe last clean set = your 5RM.\nUse your Week 1 result as your second-to-last attempt.\nRecord: your 5RM dumbbell press load per hand in lb, the level you did, and the change from Week 1.", "RETEST: build to a 5RM strict press in 15 min.\nLadder: bar × 10, ~50% × 5, ~65% × 5, then 2–4 attempts at 5 reps, adding 2.5–5 lb each time.\nNo leg drive; ribs down. The last clean set = your 5RM.\nStart with the empty bar (or a lighter training bar). First 4 weeks after on-ramp: no max attempt; stop at your first RPE 8 set and record that.\nUse your Week 1 result as your second-to-last attempt.\nRecord: your 5RM load in lb, the level you did, and the change from Week 1.", "RETEST: build to a 5RM strict press in 15 min.\nLadder: bar × 10, ~50% × 5, ~65% × 5, then 2–4 attempts at 5 reps, adding 5 lb each time.\nNo leg drive; ribs down. The last clean set = your 5RM.\nUse your Week 1 result as your second-to-last attempt.\nRecord: your 5RM load in lb, the level you did, and the change from Week 1.", "RETEST: build to a 5RM strict press in 15 min.\nLadder: bar × 10, ~50% × 5, ~65% × 5, then 2–4 attempts at 5 reps, adding 5–10 lb each time.\nNo leg drive; ribs down. The last clean set = your 5RM.\nUse your Week 1 result as your second-to-last attempt.\nRecord: your 5RM load in lb, the level you did, and the change from Week 1."]}, {"kind": "conditioning", "label": "Benchmark", "title": "Station AMRAP", "minutes": 16, "versions": ["Learn the four station standards first (4 min).\nThen AMRAP 10:00, steady (RPE 6), on your own:\n10 wall balls 4/6 lb to a low target (about 7 ft)\n20 m farmers carry 2 × 13/18 lb\n10 step-ups to a low step (total)\n4 incline step-back burpees (hands on a box), each followed by 2 long strides\nShoulder sore after the press: goblet squats instead of wall balls. Knees: step-ups instead of lunges.\nCap 10:00 · Aim: beat your Week 1 rounds · Feel: cardio · Pace: sustain\nRecord: rounds + reps and level (compare with Week 1).", "Learn the four station standards first (4 min).\nThen AMRAP 10:00, steady (RPE 6), on your own:\n10 wall balls 6/10 lb to a lower target\n20 m farmers carry 2 × 18/26 lb\n10 bodyweight lunges (total)\n4 step-back burpees, each followed by a broad jump\nShoulder sore after the press: goblet squats instead of wall balls. Knees: step-ups instead of lunges.\nCap 10:00 · Aim: beat your Week 1 rounds · Feel: cardio · Pace: sustain\nRecord: rounds + reps and level (compare with Week 1).", "Learn the four station standards first (4 min).\nThen AMRAP 10:00, steady (RPE 6), on your own:\n10 wall balls 6/10 lb\n20 m farmers carry 2 × 26/35 lb\n10 sandbag lunges 22/33 lb (total)\n4 burpee broad jumps\nShoulder sore after the press: goblet squats instead of wall balls. Knees: step-ups instead of lunges.\nCap 10:00 · Aim: beat your Week 1 rounds · Feel: cardio · Pace: sustain\nRecord: rounds + reps and level (compare with Week 1).", "Learn the four station standards first (4 min).\nThen AMRAP 10:00, steady (RPE 6), on your own:\n10 wall balls 10/14 lb\n20 m farmers carry 2 × 35/53 lb\n10 sandbag lunges 22/44 lb (total)\n4 burpee broad jumps\nShoulder sore after the press: goblet squats instead of wall balls. Knees: step-ups instead of lunges.\nCap 10:00 · Aim: beat your Week 1 rounds · Feel: cardio · Pace: sustain\nRecord: rounds + reps and level (compare with Week 1)."]}, {"kind": "skill", "label": "Accessory", "title": "Accessory superset", "minutes": 4, "versions": ["Superset, 2 rounds, 3–4 reps left: 8 light dumbbell rear-delt flys, chest on an incline bench + 6 lying bent-knee raises.", "Superset, 2 rounds, 3 reps left: 10 light dumbbell rear-delt flys + 8 lying leg raises.", "Superset, 2 rounds, 3 reps left: 10 dumbbell rear-delt flys + 8 hanging knee raises.", "Superset, 2 rounds, 3 reps left: 10 dumbbell rear-delt flys + 8 hanging knee raises."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 8, "versions": ["3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
