insert into public.workout_coach_notes (class_date, body) values ('2026-12-11', 'Demo the wall ball, farmers carry, sandbag lunge and burpee broad jump standards before the AMRAP (4 min). Start members on different stations if kit is short. Steady, Strong and Full all test the barbell strict press; only Gentle tests the seated dumbbell press. Benchmark: Full is the Rx standard; members record their level. No outside version: there is no running in this piece.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-14', 'Squat Technique + Community AMRAP', 'Squat technique · steady AMRAP · moderate', 'Light squat technique and a steady piece everyone does at their own level. A great day to bring a friend.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["General (5 min): 400 m easy row or bike, 10 spiderman lunges with reach, 10 PVC pass-throughs.\nSpecific (6 min): 8 tempo goblet squats (3 s down), 3 squat jumps, then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row or bike, 10 spiderman lunges with reach, 10 PVC pass-throughs.\nSpecific (6 min): 8 tempo goblet squats (3 s down), 3 squat jumps, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row or bike, 10 spiderman lunges with reach, 10 PVC pass-throughs.\nSpecific (6 min): 8 tempo goblet squats (3 s down), 3 squat jumps, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row or bike, 10 spiderman lunges with reach, 10 PVC pass-throughs.\nSpecific (6 min): 8 tempo goblet squats (3 s down), 3 squat jumps, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "Back squat technique 3×5 @ 65%", "minutes": 20, "lift": {"movement": "Back squat", "gentleMovement": "Goblet squat", "mode": "percent", "sets": 3, "reps": 5, "pct": [null, 65, 65, 65], "note": "Optional technique work: stop well short of RPE 8. These are not tests."}, "versions": ["Optional: goblet box squat 3 × 6, very light (RPE 5–6), 2 s pause on the box.\nFocus: brace, knees out, stand up tall.", "Optional: back squat 3 × 5 @ 65% of your estimated max, 2 s pause at the bottom. Rest 1:30.\nFocus: brace, knees out, same depth every rep. Stop well short of RPE 8.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Optional: back squat 3 × 5 @ 65% of your estimated max, 2 s pause at the bottom. Rest 1:30.\nFocus: brace, knees out, same depth every rep. Stop well short of RPE 8.", "Optional: back squat 3 × 5 @ 65% of your estimated max, 2 s pause at the bottom. Rest 1:30.\nFocus: brace, knees out, same depth every rep. Stop well short of RPE 8."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Community AMRAP", "minutes": 15, "versions": ["AMRAP 20:00 at RPE 6–7, on your own, steady:\n5/6 cal row\n8 wall balls 4/6 lb to a low target\n8 Russian KB swings to chest height 13/18 lb\nNew or visiting? Do Steady, or Gentle for an easier start; your coach demos every movement.\nNo machine free: 5/6 cal row → 0:20 step-jacks or marching on the spot.\nCap 20:00 (fixed) · Aim: steady rounds; rest when you need to · Feel: cardio · Pace: sustain", "AMRAP 20:00 at RPE 6–7, on your own, steady:\n6/8 cal row\n12 wall balls 6/10 lb\n12 KB swings 18/26 lb\nNew or visiting? Do Steady, or Gentle for an easier start; your coach demos every movement.\nNo machine free: 6/8 cal row → 30 jumping jacks.\nCap 20:00 (fixed) · Aim: steady rounds, same pace · Feel: cardio · Pace: sustain", "AMRAP 20:00 at RPE 6–7, on your own, steady:\n9/12 cal row\n12 wall balls 10/14 lb\n12 KB swings 26/35 lb\nNew or visiting? Do Steady, or Gentle for an easier start; your coach demos every movement.\nNo machine free: 9/12 cal row → 80 single-unders.\nCap 20:00 (fixed) · Aim: steady rounds, same pace · Feel: cardio · Pace: sustain", "AMRAP 20:00 at RPE 6–7, on your own, steady:\n9/12 cal row\n12 wall balls 14/20 lb\n12 KB swings 35/53 lb\nNew or visiting? Do Steady, or Gentle for an easier start; your coach demos every movement.\nNo machine free: 9/12 cal row → 80 single-unders.\nCap 20:00 (fixed) · Aim: 6–8 rounds at the same pace · Feel: cardio · Pace: sustain"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory superset", "minutes": 5, "versions": ["Superset, 2 rounds, 3–4 reps left: 8 very light goblet squats to a box + 6 lying bent-knee raises.", "Superset, 2 rounds, 3 reps left: 10 light goblet squats with a pause + 8 lying leg raises.", "Superset, 2 rounds, 3 reps left: 10 goblet squats with a pause + 8 hanging knee raises.", "Superset, 2 rounds, 3 reps left: 10 goblet squats with a pause + 8 hanging knee raises."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; child''s pose 1 min. Log your loads.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
