insert into public.workout_coach_notes (class_date, body) values ('2026-12-14', 'Flex week: every session is optional (members pick 3–4); guests and on-ramp members join at Steady (Foundations), or Gentle if they need an easier start. Machine-only intervals (no running on squat day by design), so no outside version.')
