insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-15', 'T2B RETEST + Easy Bike Flow', 'Toes-to-bar retest · easy bike flow · moderate', 'Retest this block''s skill and compare with Week 2. An easy bike, step-up and plank flow keeps you fresh for Helen and the Mini Challenge.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["General (5 min): 400 m easy row or jog, 10 cat-cows, 10 PVC pass-throughs.\nSpecific (6 min): 20 s hollow hold, 10 arch rocks, 2 × 5 kip swings, 2 × 3 easy T2B or knee raises.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row or jog, 10 cat-cows, 10 PVC pass-throughs.\nSpecific (6 min): 20 s hollow hold, 10 arch rocks, 2 × 5 kip swings, 2 × 3 easy T2B or knee raises.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row or jog, 10 cat-cows, 10 PVC pass-throughs.\nSpecific (6 min): 20 s hollow hold, 10 arch rocks, 2 × 5 kip swings, 2 × 3 easy T2B or knee raises.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row or jog, 10 cat-cows, 10 PVC pass-throughs.\nSpecific (6 min): 20 s hollow hold, 10 arch rocks, 2 × 5 kip swings, 2 × 3 easy T2B or knee raises.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "skill", "label": "Retest", "title": "Toes-to-bar RETEST", "minutes": 13, "versions": ["Warm up the skill: 2 × 3 easy lying bent-knee raises.\nRETEST: max unbroken lying bent-knee raises, one attempt. Compare with Week 2.\nRecord: your max unbroken lying knee raises, your level, and the change from Week 2.", "Warm up the skill: 3 × 3 easy hanging knee raises.\nRETEST: max unbroken hanging knee raises to hip height, one attempt. Compare with Week 2.\nRecord: your max unbroken knee raises, your level, and the change from Week 2.", "Warm up the skill: 3 × 3 easy kipping knee raises.\nRETEST: max unbroken hanging knee raises to hip height, one attempt. Compare with Week 2.\nRecord: your max unbroken knee raises, your level, and the change from Week 2.\nOptional: max strict pull-ups, one set (baseline for the next block). Record: strict pull-ups.", "Warm up the skill: 3 × 3 easy toes-to-bar.\nRETEST: max unbroken toes-to-bar, one attempt. Compare with Week 2.\nRecord: your max unbroken toes-to-bar, your level, and the change from Week 2.\nOptional: max strict pull-ups, one set (baseline for the next block). Record: strict pull-ups."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Easy bike flow", "minutes": 28, "versions": ["Easy flow, 4 rounds, not for time (RPE 3–4, about 20:00):\n2:00 very easy air bike\n6/side step-ups to a low step, holding the rig\n15 s/side side plank from the knees\nZone 2: you can talk in full sentences. Bodyweight only on the step-ups: save your legs for Helen and the Mini Challenge.\nNo machine free: each 2:00 air bike → 2:00 easy marching on the spot or step-jacks.\nCap 20:00 · Aim: the same easy bike pace every round · Feel: cardio (easy) · Pace: sustain", "Easy flow, 4 rounds, not for time (RPE 4, about 20:00):\n2:30 easy air bike\n8/side step-ups to a low box\n20 s/side side plank from the knees\nZone 2: you can talk in full sentences. Bodyweight only on the step-ups: save your legs for Helen and the Mini Challenge.\nNo machine free: each 2:30 air bike → 2:30 easy jumping jacks and marching.\nCap 20:00 · Aim: the same easy bike pace every round · Feel: cardio (easy) · Pace: sustain", "Easy flow, 4 rounds, not for time (RPE 4–5, about 20:00):\n3:00 easy air bike\n8/side step-ups to a knee-height box\n20 s/side side plank\nZone 2: you can talk in full sentences. Bodyweight only on the step-ups: save your legs for Helen and the Mini Challenge.\nNo machine free: each 3:00 air bike → 3:00 easy single-unders and jumping jacks.\nCap 20:00 · Aim: the same easy bike pace every round · Feel: cardio (easy) · Pace: sustain", "Easy flow, 4 rounds, not for time (RPE 5, about 20:00):\n3:00 easy air bike\n10/side step-ups to a knee-height box\n30 s/side side plank\nZone 2: you can talk in full sentences. Bodyweight only on the step-ups: save your legs for Helen and the Mini Challenge.\nNo machine free: each 3:00 air bike → 3:00 easy single-unders and jumping jacks.\nCap 20:00 · Aim: the same easy bike pace every round · Feel: cardio (easy) · Pace: sustain"]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min.", "Walk 2 min; calf and hamstring stretch 1 min/side; lat stretch on the rig 1 min."]}]'::jsonb, 'published', null)
