insert into public.workout_coach_notes (class_date, body) values ('2026-12-15', 'Flex week: every session is optional (members pick 3–4); guests and on-ramp members join at Steady (Foundations), or Gentle if they need an easier start. Write each retest next to the Week 2 baseline on the scorecard; members retest at the same level as their baseline. The easy flow is air bike only on purpose (no running before Helen and the Mini Challenge; rowers stay free), so no outside version. Short on bikes? Half the class starts with the step-ups and side plank.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-16', 'Deadlift Technique + HELEN', 'Deadlift technique · Helen benchmark · hard', 'Benchmark day: Helen. Your time is the baseline to beat next block.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["General (5 min): 400 m easy row, 10 jumping jacks, 5/side supported hip airplanes.\nSpecific (6 min): 2 × 5 deadlifts building, 5 KB swings, then ramp sets.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row, 10 jumping jacks, 5/side supported hip airplanes.\nSpecific (6 min): 2 × 5 deadlifts building, 5 KB swings, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row, 10 jumping jacks, 5/side supported hip airplanes.\nSpecific (6 min): 2 × 5 deadlifts building, 5 KB swings, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 400 m easy row, 10 jumping jacks, 5/side supported hip airplanes.\nSpecific (6 min): 2 × 5 deadlifts building, 5 KB swings, then ramp sets.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "Deadlift technique 3×5 @ 60%", "minutes": 12, "lift": {"movement": "Deadlift", "gentleMovement": "Kettlebell deadlift", "mode": "percent", "sets": 3, "reps": 5, "pct": [null, 60, 60, 60], "note": "Optional technique work: stop well short of RPE 8. These are not tests."}, "versions": ["Optional: kettlebell deadlift 3 × 6, light (RPE 5), bell on a low step if needed. Reset each rep.", "Optional: deadlift 3 × 5 @ 60% of your estimated max. Reset each rep; light because of today''s swings. Rest 1:30.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Optional: deadlift 3 × 5 @ 60% of your estimated max. Reset each rep; light because of today''s swings. Rest 1:30.", "Optional: deadlift 3 × 5 @ 60% of your estimated max. Reset each rep; light because of today''s swings. Rest 1:30."]}, {"kind": "conditioning", "label": "Benchmark", "title": "HELEN (row version)", "minutes": 24, "versions": ["HELEN (inside): 3 rounds for time:\n250 m row\n12 Russian KB swings to chest height 13/18 lb\n8 ring rows on a high bar, body nearly upright\nLighter option: 2 rounds, RPE 5–6.\nNo machine free: 250 m row → 1:00 step-jacks or marching on the spot.\nCap 15:00 · Aim: finish under the cap · Feel: cardio · Pace: sustain, then reach in round 3\nRecord: time, level, and whether you ran or rowed.", "HELEN (inside): 3 rounds for time:\n400 m row\n21 KB swings 18/26 lb\n12 ring rows\nLighter option: 2 rounds at Gentle, RPE 6.\nNo machine free: 400 m row → 100 jumping jacks.\nCap 15:00 · Aim: finish under the cap · Feel: cardio · Pace: sustain, then reach in round 3\nRecord: time, level, and whether you ran or rowed.", "HELEN (inside): 3 rounds for time:\n500 m row\n21 KB swings 26/35 lb\n12 banded or jumping pull-ups\nLighter option: 2 rounds at Gentle, RPE 6.\nNo machine free: 500 m row → 250 single-unders.\nCap 15:00 · Aim: 11:00–14:00 · Feel: cardio · Pace: sustain, then reach in round 3\nRecord: time, level, and whether you ran or rowed.", "HELEN (inside): 3 rounds for time:\n500 m row\n21 KB swings 35/53 lb\n12 pull-ups (kipping OK)\nLighter option: 2 rounds at Gentle, RPE 6.\nNo machine free: 500 m row → 250 single-unders.\nCap 15:00 · Aim: 9:00–12:00 · Feel: cardio · Pace: sustain, then reach in round 3\nRecord: time, level, and whether you ran or rowed."], "outdoor": {"title": "HELEN", "versions": ["HELEN: 3 rounds for time:\n200 m walk/jog\n12 Russian KB swings to chest height 13/18 lb\n8 ring rows on a high bar, body nearly upright\nLighter option: 2 rounds, RPE 5–6.\nCap 15:00 · Aim: finish under the cap · Feel: cardio · Pace: sustain, then reach in round 3\nRecord: time, level, and whether you ran or rowed.", "HELEN: 3 rounds for time:\n300 m run\n21 KB swings 18/26 lb\n12 ring rows\nLighter option: 2 rounds at Gentle, RPE 6.\nCap 15:00 · Aim: finish under the cap · Feel: cardio · Pace: sustain, then reach in round 3\nRecord: time, level, and whether you ran or rowed.", "HELEN: 3 rounds for time:\n400 m run\n21 KB swings 26/35 lb\n12 banded or jumping pull-ups\nLighter option: 2 rounds at Gentle, RPE 6.\nCap 15:00 · Aim: 11:00–14:00 · Feel: cardio · Pace: sustain, then reach in round 3\nRecord: time, level, and whether you ran or rowed.", "HELEN: 3 rounds for time:\n400 m run\n21 KB swings 35/53 lb\n12 pull-ups (kipping OK)\nLighter option: 2 rounds at Gentle, RPE 6.\nCap 15:00 · Aim: 9:00–12:00 · Feel: cardio · Pace: sustain, then reach in round 3\nRecord: time, level, and whether you ran or rowed."]}}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 10, "versions": ["3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy row; pigeon stretch 1 min/side; dead hang 3 × 15 s.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
