insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-17', 'Accessory Strength + Easy Row/Bike Intervals', 'Accessory strength · easy intervals · easy', 'The easy day plus your scorecard: compare your Week 1 and Week 8 numbers and set one goal for the next block.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 7, "versions": ["General (4 min): 2 min easy bike, 10 deep-squat pries, 10/side ankle rocks.\nSpecific (3 min): 5/side split squats (bodyweight), 10 band face pulls, 20 s hollow hold.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (4 min): 2 min easy bike, 10 deep-squat pries, 10/side ankle rocks.\nSpecific (3 min): 5/side split squats (bodyweight), 10 band face pulls, 20 s hollow hold.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (4 min): 2 min easy bike, 10 deep-squat pries, 10/side ankle rocks.\nSpecific (3 min): 5/side split squats (bodyweight), 10 band face pulls, 20 s hollow hold.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (4 min): 2 min easy bike, 10 deep-squat pries, 10/side ankle rocks.\nSpecific (3 min): 5/side split squats (bodyweight), 10 band face pulls, 20 s hollow hold.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "skill", "label": "Accessory", "title": "Accessory strength + core", "minutes": 21, "versions": ["2 rounds, 3–4 reps left on every set:\nA1) 8 light dumbbell rear-delt flys, chest on an incline bench\nA2) 6/side split squats holding the rig, short range\nA3) 6/side dead bugs, arms only + 10 calf raises holding the rig", "2 rounds, 3 reps left on every set:\nA1) 10 light dumbbell rear-delt flys\nA2) 10/side bodyweight split squats (hold the rig)\nA3) 10/side dead bugs + 15 calf raises", "2 rounds, 3 reps left on every set:\nA1) 10 dumbbell rear-delt flys\nA2) 10/side dumbbell split squats\nA3) 10/side dead bugs + 15 calf raises", "2 rounds, 3 reps left on every set:\nA1) 10 dumbbell rear-delt flys\nA2) 10/side dumbbell split squats\nA3) 10/side dead bugs + 15 calf raises"]}, {"kind": "conditioning", "label": "Easy intervals", "title": "Easy row/bike intervals", "minutes": 21, "versions": ["4 × 4:00 easy / 1:00 rest (19:00), alternating row and air bike each round.\nEffort: RPE 3–4 (very easy). Air bike or row; each round can be 1:00–2:00 shorter, and slow pedalling is fine.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: marching on the spot, step-ups to a low step, wall push-ups; repeat until the work time ends.\nCap 19:00 (fixed) · Aim: same easy pace every round; you could keep going · Feel: cardio (easy) · Pace: sustain", "4 × 4:00 easy / 1:00 rest (19:00), alternating row and air bike each round.\nEffort: RPE 4 (easy, chatty). Air bike or row. Rounds can be 1:00 shorter.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: step-ups to a low box, jumping jacks, air squats; repeat until the work time ends.\nCap 19:00 (fixed) · Aim: same pace every round: row split 0:15–0:25 per 500 m slower than your 1 km test split; bike, same calories each round (±1) · Feel: cardio (easy) · Pace: sustain", "4 × 4:00 easy / 1:00 rest (19:00), alternating row and air bike each round.\nEffort: RPE 4–5. Row or air bike.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: step-ups, jumping jacks, air squats, easy single-unders; repeat until the work time ends.\nCap 19:00 (fixed) · Aim: same pace every round: row split 0:15–0:25 per 500 m slower than your 1 km test split; bike, same calories each round (±1) · Feel: cardio (easy) · Pace: sustain", "4 × 4:00 easy / 1:00 rest (19:00), alternating row and air bike each round.\nEffort: RPE 5. Row or air bike.\nZone 2: you can talk in full sentences the whole time. If you can only say a few words, slow down.\nMasters or injury: today is the best day for extra mobility or rehab work.\nNo machine free: same clock, easy bodyweight rounds instead, 1:00 each: step-ups, jumping jacks, air squats, easy single-unders; repeat until the work time ends.\nCap 19:00 (fixed) · Aim: same pace every round: row split 0:15–0:25 per 500 m slower than your 1 km test split; bike, same calories each round (±1) · Feel: cardio (easy) · Pace: sustain"]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + mobility", "minutes": 8, "versions": ["3 min easy bike; couch stretch 1 min/side; adductor rocks; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; adductor rocks; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; adductor rocks; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; couch stretch 1 min/side; adductor rocks; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
