insert into public.workout_coach_notes (class_date, body) values ('2026-12-17', 'Flex week: every session is optional (members pick 3–4); guests and on-ramp members join at Steady (Foundations), or Gentle if they need an easier start. Scorecard review with a coach during the accessory block: about 5 min per small group; help each member write one goal for the next block. If there aren''t enough rowers and bikes, run the class in two waves: wave 1 does the intervals while wave 2 does the accessory strength, then swap at about minute 31; or send the overflow to the ''No machine free'' bodyweight rounds. The intervals have no outside version on purpose: Thursday is machine-only so weekly running volume stays as planned.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-18', 'Press Technique + Court6 Mini Challenge', 'Press technique · Mini Challenge benchmark · hard', 'Our mini challenge: 4 short runs, each followed by a station. It''s your baseline for the next block.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["General (5 min): 600 m easy jog or row, leg swings, arm circles.\nSpecific (7 min): walk the course and the standards, then 1 round at challenge pace, 10–15 s each: row, burpee broad jump, sandbag lunges, wall balls; 10 empty-bar strict presses.\nStep instead of jumping, walk instead of jogging, and stay in a comfortable range.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 600 m easy jog or row, leg swings, arm circles.\nSpecific (7 min): walk the course and the standards, then 1 round at challenge pace, 10–15 s each: row, burpee broad jump, sandbag lunges, wall balls; 10 empty-bar strict presses.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 600 m easy jog or row, leg swings, arm circles.\nSpecific (7 min): walk the course and the standards, then 1 round at challenge pace, 10–15 s each: row, burpee broad jump, sandbag lunges, wall balls; 10 empty-bar strict presses.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "General (5 min): 600 m easy jog or row, leg swings, arm circles.\nSpecific (7 min): walk the course and the standards, then 1 round at challenge pace, 10–15 s each: row, burpee broad jump, sandbag lunges, wall balls; 10 empty-bar strict presses.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}, {"kind": "strength", "label": "Strength", "title": "Strict press technique 3×5 @ 60%", "minutes": 7, "lift": {"movement": "Strict press", "gentleMovement": "Dumbbell press", "mode": "percent", "sets": 3, "reps": 5, "pct": [null, 60, 60, 60], "note": "Optional technique work: stop well short of RPE 8. These are not tests."}, "versions": ["Optional: seated dumbbell press 2 × 8, light (RPE 5–6), + 2 × 8 light dumbbell rear-delt flys.", "Optional: strict press 3 × 5 @ 60% of your estimated max, + 2 × 10 dumbbell rear-delt flys. Smooth reps; rest 1:30.\nNewer to the barbell (or in your first 4 weeks): same sets and reps with the empty bar or light plates, at RPE 7.", "Optional: strict press 3 × 5 @ 60% of your estimated max, + 2 × 10 dumbbell rear-delt flys. Smooth reps; rest 1:30.", "Optional: strict press 3 × 5 @ 60% of your estimated max, + 2 × 10 dumbbell rear-delt flys. Smooth reps; rest 1:30."]}, {"kind": "conditioning", "label": "Benchmark", "title": "Court6 Mini Challenge (bike version)", "minutes": 30, "versions": ["COURT6 MINI CHALLENGE, for time, on your own:\n8/10 cal air bike → 200 m row\n8/10 cal air bike → 10 incline step-back burpees (hands on a box)\n8/10 cal air bike → 16 step-ups to a low step (total)\n8/10 cal air bike → 20 wall balls 4/6 lb to a low target\nLighter option: RPE 5–6 all the way.\nNo machine free: 200 m row → 0:50 step-jacks or marching on the spot; 8/10 cal air bike → 0:35 step-jacks or marching on the spot.\nCap 26:00 · Aim: finish under the cap · Feel: cardio · Pace: sustain (even run splits)\nRecord: total time, level, run 1 and run 4 split, and whether you ran or biked.", "COURT6 MINI CHALLENGE, for time, on your own:\n12/15 cal air bike → 300 m row\n12/15 cal air bike → 20 m step-back burpees, each followed by a broad jump\n12/15 cal air bike → 30 lunges, sandbag 13/22 lb or none (total)\n12/15 cal air bike → 30 wall balls 6/10 lb\nLighter option: Gentle at RPE 6.\nNo machine free: 300 m row → 75 jumping jacks; 12/15 cal air bike → 55 jumping jacks.\nCap 26:00 · Aim: finish under the cap · Feel: cardio · Pace: sustain (even run splits)\nRecord: total time, level, run 1 and run 4 split, and whether you ran or biked.", "COURT6 MINI CHALLENGE, for time, on your own:\n16/20 cal air bike → 500 m row\n16/20 cal air bike → 20 m burpee broad jumps\n16/20 cal air bike → 30 sandbag lunges 22/33 lb (total)\n16/20 cal air bike → 40 wall balls 6/10 lb to 9 ft\nLighter option: Gentle at RPE 6.\nNo machine free: 500 m row → 250 single-unders; 16/20 cal air bike → 140 single-unders.\nCap 26:00 · Aim: 17:00–23:00 · Feel: cardio · Pace: sustain (even run splits)\nRecord: total time, level, run 1 and run 4 split, and whether you ran or biked.", "COURT6 MINI CHALLENGE, for time, on your own:\n16/20 cal air bike → 500 m row\n16/20 cal air bike → 20 m burpee broad jumps\n16/20 cal air bike → 30 sandbag lunges 22/44 lb (total)\n16/20 cal air bike → 40 wall balls 10/14 lb to 9/10 ft\nLighter option: Gentle at RPE 6.\nNo machine free: 500 m row → 250 single-unders; 16/20 cal air bike → 140 single-unders.\nCap 26:00 · Aim: 15:00–20:00 · Feel: cardio · Pace: sustain (even run splits)\nRecord: total time, level, run 1 and run 4 split, and whether you ran or biked."], "outdoor": {"title": "Court6 Mini Challenge", "versions": ["COURT6 MINI CHALLENGE, for time, on your own:\n200 m walk/jog → 200 m row\n200 m walk/jog → 10 incline step-back burpees (hands on a box)\n200 m walk/jog → 16 step-ups to a low step (total)\n200 m walk/jog → 20 wall balls 4/6 lb to a low target\nLighter option: RPE 5–6 all the way.\nNo machine free: 200 m row → 150 m walk/jog.\nCap 26:00 · Aim: finish under the cap · Feel: cardio · Pace: sustain (even run splits)\nRecord: total time, level, run 1 and run 4 split, and whether you ran or biked.", "COURT6 MINI CHALLENGE, for time, on your own:\n300 m run → 300 m row\n300 m run → 20 m step-back burpees, each followed by a broad jump\n300 m run → 30 lunges, sandbag 13/22 lb or none (total)\n300 m run → 30 wall balls 6/10 lb\nLighter option: Gentle at RPE 6.\nNo machine free: 300 m row → 250 m run.\nCap 26:00 · Aim: finish under the cap · Feel: cardio · Pace: sustain (even run splits)\nRecord: total time, level, run 1 and run 4 split, and whether you ran or biked.", "COURT6 MINI CHALLENGE, for time, on your own:\n400 m run → 500 m row\n400 m run → 20 m burpee broad jumps\n400 m run → 30 sandbag lunges 22/33 lb (total)\n400 m run → 40 wall balls 6/10 lb to 9 ft\nLighter option: Gentle at RPE 6.\nNo machine free: 500 m row → 400 m run.\nCap 26:00 · Aim: 17:00–23:00 · Feel: cardio · Pace: sustain (even run splits)\nRecord: total time, level, run 1 and run 4 split, and whether you ran or biked.", "COURT6 MINI CHALLENGE, for time, on your own:\n400 m run → 500 m row\n400 m run → 20 m burpee broad jumps\n400 m run → 30 sandbag lunges 22/44 lb (total)\n400 m run → 40 wall balls 10/14 lb to 9/10 ft\nLighter option: Gentle at RPE 6.\nNo machine free: 500 m row → 400 m run.\nCap 26:00 · Aim: 15:00–20:00 · Feel: cardio · Pace: sustain (even run splits)\nRecord: total time, level, run 1 and run 4 split, and whether you ran or biked."]}}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 8, "versions": ["3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.", "3 min easy bike; doorway chest stretch 1 min/side; box breathing 1 min.\nNo machine free: swap the machine for easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal."]}]'::jsonb, 'published', null)
